// Feature: the person's control over Dispatch Pilot, the `/dp` command.
//
//   /dp                  opens the rationale pane (依据面板), or closes it when open
//   /dp log              opens the same pane (the old habit's name for it)
//   /dp status           what is on, the lock
//   /dp on | off         the whole mod
//   /dp <name> on | off  one feature (each registers its own, core/switches.ts)
//   /dp lock <effort>    hold the main agent at that effort on every step
//   /dp unlock           release it
//   /dp log N            the last N decisions and why, in the conversation
//
// A pane the surface does not place (one that places no panes) is closed again
// at once, and the answer says so (spec #22: no pane left open and waiting).
//
// What the person flips is kept in $.store and loaded back at session start.
// The engine puts the plugin's name before a command's answer, so the texts
// here do not start with one.
//
// It also records what the engine measures of the session (context fill, limit
// percentages, cost) in the debug log. Only recorded: nothing reads them to
// decide anything (spec, 可见性与控制; a later quota-saving mode may).

import type { On, SessionMeasureInput } from 'claude-code'
import { EFFORTS, isEffort, type Effort } from '../decision/effort.ts'
import { decisionLine, LOG_ENTRIES, report, unplacedText, type DecisionModelIo, type LogEntry, type SwitchIo } from '../core/report.ts'
import { describeDefaults, removedDecisionModel, type Ctx } from '../core/setup.ts'
import { defineSwitch, isOn, listSwitches, loadOverrides, masterOn, overrides, parseOverrides, setMaster, setSwitch } from '../core/switches.ts'
import { errorText } from '../decision/backend.ts'
import { PANE_COLUMNS, PANE_ID, PANE_TITLE } from '../board/rationale.ts'

const LOCK = { plugin: 'dispatch-pilot', key: 'lock' } as const
const DECISIONS = { plugin: 'dispatch-pilot', key: 'decisionLog' } as const
const BOARD = { plugin: 'dispatch-pilot', key: 'board' } as const
/** The switches the person flipped, in $.store. */
const SWITCHES_KEY = 'switches'

export function registerControl(on: On, ctx: Ctx): void {
  defineSwitch({ name: 'signals', info: '把上下文、限额和花费的读数记进 debug log，不参与任何决策' })

  // Under a match-all matcher: other features set themselves up at session start too.
  on('session.start', { cwd: /(?:)/ }, async ($, e, next) => {
    // The person's switches first: the features beneath read them while the session starts.
    loadOverrides(await $.store.get(SWITCHES_KEY).catch(() => undefined))
    // The environment's Perplexity key (the options' comes first), for the requests that follow; never written down, only where it came from.
    // Read before anything is said of the decision model: whether it is pplx or Jev depends on it (core/setup.ts, `Ctx`).
    ctx.secrets.perplexityEnvKey = ((await $.env.get('PERPLEXITY_API_KEY').catch(() => undefined)) ?? '').trim()
    // Which options the decision model's defaults decided (core/setup.ts BACKEND_DEFAULTS).
    $.ui.log(describeDefaults(ctx.config), { to: 'debug' })
    const modelIo: DecisionModelIo = {
      board: { get: () => $.state.get(BOARD), set: (value, options) => $.state.set(BOARD, value, options) },
      decisions: { get: () => $.state.get(DECISIONS), set: (value, options) => $.state.set(DECISIONS, value, options) },
      debug: (line) => $.ui.log(line, { to: 'debug' }),
    }
    // Jev decides only for want of a Perplexity key: the decision log says so (ADR 0006), where the person looks for why.
    if (ctx.fellBack) await report(modelIo, { fellBack: { asked: 'pplx', using: 'jev' } })
    // The model that takes images (#56, ADR 0008) is chosen by the keys alone: pplx for want of a TypeSafe key is said once; none, in the debug log.
    const images = ctx.images
    if (images === null) $.ui.log('images: no decision model takes them (no TypeSafe or Perplexity key)', { to: 'debug' })
    else if (images.fellBack) await report(modelIo, { fellBack: { asked: 'jev', using: images.name, for: 'images' } })
    if (ctx.config.backend === 'pplx') $.ui.log(`pplx key: ${ctx.config.perplexityApiKey !== '' ? 'from the options' : ctx.secrets.perplexityEnvKey !== '' ? 'from PERPLEXITY_API_KEY' : 'not set'}`, { to: 'debug' })
    // A decisionModel left over in the person's settings that names a model since removed: the engine reads it as the default.
    const removed = removedDecisionModel(await $.settings.read({ source: 'user' }).catch(() => undefined))
    if (removed !== null) $.ui.log(`decisionModel ${removed} 已移除，按没设处理`, { to: 'debug' })
    const result = await next(e)
    await $.command
      .register({
        name: 'dp',
        description: 'Dispatch Pilot：依据面板、功能开关、effort 锁定、最近的决定',
        argumentHint: '[log | status | on|off | <name> on|off | lock <effort> | unlock | log N]',
        immediate: true,
      })
      .catch((error) => $.ui.log(`/dp was not registered: ${errorText(error)}`, { to: 'debug' }))
    return result
  })

  // `window` is in every measurement: a matcher on a field that is always there.
  on('session.measure', { context: { window: /(?:)/ } }, async ($, e, next) => {
    if (isOn('signals')) {
      try {
        $.ui.log(describeSignals(e), { to: 'debug' })
      } catch {
        // a reading that cannot be written down is skipped
      }
    }
    return next(e)
  })

  on('command.run', { command: 'dp' }, async ($, e) => {
    const command = parseControl(e.args)
    // The screens draw again: they leave out what a feature that is off owns.
    const reporting: SwitchIo = { redraw: () => $.ui.invalidate('ui.render') }
    // Keeps one switch as the person just flipped it, beside whatever another session saved meanwhile;
    // says so when it cannot.
    const save = async (name: string) => {
      try {
        const saved = parseOverrides(await $.store.get(SWITCHES_KEY))
        const now = overrides()[name]
        if (now === undefined) delete saved[name]
        else saved[name] = now
        await $.store.set(SWITCHES_KEY, saved)
        return ''
      } catch {
        return '（没有保存：本地存储用不了，只在这个会话里有效）'
      }
    }
    try {
      switch (command.kind) {
        case 'pane': {
          // `/dp` toggles; `/dp log` only opens (and asks for the keys again).
          if (command.toggle && (await $.ui.panes()).some((pane) => pane.id === PANE_ID)) {
            await $.ui.close({ id: PANE_ID })
            return { text: '依据面板已关闭' }
          }
          const opened = await $.ui.open({ id: PANE_ID, title: PANE_TITLE, focus: true, closeOnEscape: true, columns: PANE_COLUMNS })
          if (opened.isPlaced) return { text: '依据面板已打开：p / n 翻看 agent，Esc 关闭' }
          await $.ui.close({ id: PANE_ID })
          return { text: unplacedText(opened.reason) }
        }
        case 'status': {
          const { value: lock = null } = await $.state.get(LOCK)
          return { text: describeStatus(lock) }
        }
        case 'master':
          setMaster(command.on)
          await report(reporting, { switched: true })
          return { text: `Dispatch Pilot 已${command.on ? '打开' : '关闭'}${await save('master')}` }
        case 'switch': {
          const spec = listSwitches().find((s) => s.name === command.name)
          if (spec === undefined || !setSwitch(command.name, command.on)) {
            const names = listSwitches().map((s) => s.name).join(', ')
            return { text: `没有叫「${command.name}」的开关（现有：${names}）` }
          }
          await report(reporting, { switched: true })
          return { text: `${spec.name} 已${command.on ? '打开' : '关闭'}：${spec.info}${await save(spec.name)}` }
        }
        case 'lock': {
          await $.state.set(LOCK, command.effort)
          const inert = masterOn() ? '' : '（Dispatch Pilot 关着：/dp on 才生效）'
          return { text: `主 agent 已锁在 ${command.effort}：每一步都用这一档${inert}；/dp unlock 解除` }
        }
        case 'unlock':
          await $.state.set(LOCK, null)
          return { text: '已解除锁定，effort 回到按决定走' }
        case 'log': {
          const { value: kept = [] } = await $.state.get(DECISIONS)
          return { text: describeDecisions(kept.slice(-command.count)) }
        }
        case 'unknown':
          return { text: `没看懂这条命令。\n${USAGE}` }
      }
    } catch (error) {
      // Always answer: a failing command must not leave the person without a word.
      return { text: `出错了（${errorText(error)}）` }
    }
  })
}

type Control =
  | { kind: 'pane'; toggle: boolean }
  | { kind: 'status' }
  | { kind: 'master'; on: boolean }
  | { kind: 'switch'; name: string; on: boolean }
  | { kind: 'lock'; effort: Effort }
  | { kind: 'unlock' }
  | { kind: 'log'; count: number }
  | { kind: 'unknown' }

/** The words after `/dp`, case and spacing aside. */
function parseControl(args: string): Control {
  const words = args.trim().toLowerCase().split(/\s+/).filter(Boolean)
  const [first, second] = words
  if (words.length === 0) return { kind: 'pane', toggle: true }
  if (words.length === 1 && first === 'status') return { kind: 'status' }
  if (words.length === 1 && (first === 'on' || first === 'off')) return { kind: 'master', on: first === 'on' }
  if (words.length === 1 && first === 'unlock') return { kind: 'unlock' }
  if (words.length === 2 && first === 'lock' && second === 'off') return { kind: 'unlock' }
  if (words.length === 2 && first === 'lock' && isEffort(second)) return { kind: 'lock', effort: second }
  if (words.length === 1 && first === 'log') return { kind: 'pane', toggle: false }
  if (words.length === 2 && first === 'log' && /^[1-9]\d*$/.test(second ?? '')) return { kind: 'log', count: Math.min(LOG_ENTRIES, Number(second)) }
  if (words.length === 2 && first !== undefined && (second === 'on' || second === 'off')) return { kind: 'switch', name: first, on: second === 'on' }
  return { kind: 'unknown' }
}

const USAGE = `/dp（依据面板） | /dp status | /dp on|off | /dp <功能名> on|off | /dp lock <${EFFORTS.join('|')}> | /dp unlock | /dp log N`

/** `/dp status`'s answer: whether the mod is on, the lock, each feature's switch. */
function describeStatus(lock: Effort | null): string {
  const switches = listSwitches()
  const width = Math.max(0, ...switches.map((s) => s.name.length))
  return [
    `Dispatch Pilot ${masterOn() ? '开着' : '关着'}。effort 锁定：${lock ?? '没有'}。`,
    '功能开关（/dp <功能名> on|off）：',
    ...switches.map((s) => `  ${s.on ? '开' : '关'}  ${s.name.padEnd(width)}  ${s.info}`),
    USAGE,
  ].join('\n')
}

/** `/dp log N`'s answer: the decisions, oldest first, each with its reason. */
function describeDecisions(entries: readonly LogEntry[]): string {
  if (entries.length === 0) return '还没有记下任何决定'
  const header = `最近 ${entries.length} 条决定，最新的在最后`
  return [header, ...entries.map((entry) => `#${entry.n} ${entry.feature}：${decisionLine(entry)}`)].join('\n')
}

/** One measurement as a debug-log line: what the engine reported, `n/a` for what it has no figure for. */
function describeSignals(measure: SessionMeasureInput): string {
  const { context, rateLimits, cost } = measure
  const fill = context.percent === undefined ? `n/a (window ${context.window})` : `${context.percent}% (${context.tokens ?? '?'}/${context.window} tokens)`
  const limits = rateLimits.length === 0 ? 'n/a' : rateLimits.map((limit) => `${limit.kind} ${limit.percentUsed}%${limit.resetsAt === undefined ? '' : ` resets ${limit.resetsAt}`}`).join(', ')
  const spent = cost === undefined ? 'n/a' : `$${cost.usd.toFixed(4)}`
  return `signals: context ${fill}; limits ${limits}; cost ${spent}; changed ${measure.changed.join(', ')}`
}

files.hooks/features/dispatched-agents.ts:
// Feature: each agent the main agent dispatches gets its own decision on its
// model and effort, once, when it is spawned (agent.spawn). The model is
// rewritten on the spawn; the effort goes into the plan table under the
// agent's id, and the core's turn.step writer sends it on every step of that
// agent. The main agent's own model and cache are untouched (ADR 0001).
//
// The decision reads the person's own words this turn (`said`), so a model
// they name for the work wins over the decision model, which wins over the
// main agent's pick; it also reads the problem summary and the conversation
// the agent is dispatched from, what the main agent wrote the brief out of
// (BACKEND_DEFAULTS agentBackground). Agents dispatched together (one message,
// several Agent calls) share one request (core/agent-lane.ts, ADR 0009): what
// they share goes in once, each brief beside it. A failed or late answer lets
// the agent start as the main agent asked.
//
// The main agent reads, after the Agent tool's result, the model and effort its
// agent started with and whose choice the model was (#34): agent.spawn runs
// inside the Agent tool call, under its id, so the spawn leaves the note for the
// call to append.
//
// Its switch is `dispatched-agents` (`/dp dispatched-agents off`).

import type { EngineInterface, HttpInit, On } from 'claude-code'
import { timedOut, within, type Failure } from '../decision/backend.ts'
import { conversationUpTo, messageText, type ContextMessage } from '../decision/context.ts'
import { dispatchEvidence, dispatchNote, dispatchReason, modelFamily, termsOf, type DispatchNote } from '../decision/dispatched-agent.ts'
import { quoteStart } from '../decision/redact.ts'
import { problemBackground, readingBackground } from '../decision/workflow.ts'
import { agentCallsBeside, askAgent, type AgentAnswer, type AgentInput, type LaneIo } from '../core/agent-lane.ts'
import { update, type Cell } from '../core/plans.ts'
import { isPersonsMessage } from '../core/prompts.ts'
import { report, type ReportIo } from '../core/report.ts'
import { dispatchSettings, saidTokens, type Ctx } from '../core/setup.ts'
import { defineSwitch, isOn } from '../core/switches.ts'
import { sessionReading } from './reference-hint.ts'
import { UNRESOLVED_SWITCH } from './unresolved.ts'

const AGENTS = { plugin: 'dispatch-pilot', key: 'agents' } as const
const SAID = { plugin: 'dispatch-pilot', key: 'said' } as const
const BOARD = { plugin: 'dispatch-pilot', key: 'board' } as const
const DECISIONS = { plugin: 'dispatch-pilot', key: 'decisionLog' } as const
const COUNT = { plugin: 'dispatch-pilot', key: 'unresolved' } as const
const PPLX_RATE = { plugin: 'dispatch-pilot', key: 'pplxRate' } as const
const READINGS = { plugin: 'dispatch-pilot', key: 'referenceReadings' } as const

/** The switch's name, in `/dp` and in the decision log. */
const SWITCH = 'dispatched-agents'
/**
 * The notes spawns left for their Agent tool calls, by the call's tool_use_id: written by the agent.spawn inside the
 * call, taken as the call returns. A module variable (CLAUDE.md): the kit's `$.state` does not show the outer hook
 * what the nested spawn wrote (measured in the kit, DEVELOPMENT.md 已实测的引擎行为; not yet on the engine), and a hot
 * reload while an agent runs loses only that agent's note. At most MAX_NOTES are kept: past that (calls whose result never came
 * back, or more agents running at once) the oldest go.
 */
const pendingNotes = new Map<string, string>()
const MAX_NOTES = 32
/** At most this many of the person's messages are kept for one turn. */
const MAX_SAID = 8

export function registerDispatchedAgents(on: On, ctx: Ctx): void {
  defineSwitch({ name: SWITCH, info: '主 agent 派出 agent 时决定它的模型和 effort' })
  const settings = dispatchSettings(ctx)

  // The person's words this turn: a message sent while idle starts them
  // afresh, one typed during the turn joins them. Other prompts (an agent's
  // hand-back, a task notification) leave them as they are. Kept whatever the
  // switches say (nothing is asked or changed here), so a decision made right
  // after the person switches the feature back on still reads them.
  on('prompt.submit', { text: /(?:)/ }, async ($, e, next) => {
    const result = await next(e)
    if (!isPersonsMessage(e) || result.drop !== undefined) return result
    const words = messageText(e.text, saidTokens(ctx.config))
    const said: Cell<string[]> = { get: () => $.state.get(SAID), set: (value, options) => $.state.set(SAID, value, options) }
    await update(said, (list) => (e.turnId === undefined ? [words] : [...(list ?? []), words].slice(-MAX_SAID)))
    return result
  })

  // The note the spawn left for its Agent tool call goes beside the tool's result; a call whose spawn left none (a fork,
  // a teammate, a refused spawn) is answered as it is.
  on('tool.call', { tool: 'Agent' }, async ($, e, next) => {
    const result = await next(e)
    const note = pendingNotes.get(e.tool_use_id)
    pendingNotes.delete(e.tool_use_id)
    if (note === undefined || result.deny !== undefined) return result
    return { ...result, context: [...(result.context ?? []), note] }
  })

  on('agent.spawn', { tool_use_id: /(?:)/ }, async ($, e, next) => {
    // A fork always runs on its parent's model. A teammate lives across many
    // tasks that one decision at its spawn cannot see. A Workflow's agent is the
    // Workflow features': workflow-agents wrote its call into the script, or
    // workflow-labels routes it at this same spawn. A resumed run (2.1.299 on)
    // goes on as its agent was decided: the engine keeps its model, and its plan
    // is the one written here.
    if (e.fork || e.isTeammate || e.workflow !== undefined || e.resume !== undefined) return next(e)
    /** Leaves the note for the Agent tool call this spawn belongs to. */
    const leaveNote = (note: DispatchNote) => {
      pendingNotes.set(e.tool_use_id, dispatchNote(note))
      while (pendingNotes.size > MAX_NOTES) pendingNotes.delete(pendingNotes.keys().next().value as string)
    }
    if (!isOn(SWITCH)) {
      const started = await next(e)
      if (started.deny === undefined) leaveNote({ routed: false, started: started.model, why: 'off' })
      return started
    }
    const { value: said = [] } = await $.state.get(SAID)
    // The problem the main agent is on goes along as background, with no hint (#41): the summary (the cheap model's, Haiku 5.5
    // by default) and the count, while the unresolved switch is on and there are any.
    const { value: held } = isOn(UNRESOLVED_SWITCH) ? await $.state.get(COUNT) : { value: undefined }
    // The conversation the agent is dispatched from (the main one, or the dispatching agent's own): up to the Agent call
    // where the decision model reads it (BACKEND_DEFAULTS agentBackground), and the Agent calls of the same message, which
    // are asked about with it.
    const recent = await conversationOf($, e.parentAgentId)
    // What the session's reference images read as (#64): the latest reading, as text.
    const reference = await sessionReading({ get: () => $.state.get(READINGS) }, (line) => $.ui.log(line, { to: 'debug' }))
    const lines = !ctx.config.agents.background || recent.length === 0 ? [] : (conversationUpTo(recent, ctx.config.context.messages, e.tool_use_id) ?? conversationUpTo(recent, ctx.config.context.messages) ?? [])
    const input: AgentInput = {
      dispatch: { user_message: '', agent_type: e.subagentType, description: e.description, prompt: e.prompt, requested_model: e.model ?? null },
      shared: {
        words: said.join('\n'),
        background: {
          ...problemBackground(held, ctx.ask.language),
          ...readingBackground(reference),
          ...(lines.length === 0 ? {} : { recent: lines }),
        },
      },
    }
    const io: LaneIo = {
      backend: {
        fetch: (url: string, init: HttpInit) => $.http.fetch(url, init),
        sleep: (ms: number, signal: AbortSignal) => $.clock.sleep(ms, { signal }),
        pace: { now: () => $.clock.now(), sentAt: { get: () => $.state.get(PPLX_RATE), set: (value, options) => $.state.set(PPLX_RATE, value, options) } },
      },
      now: () => $.clock.now(),
      debug: (line) => $.ui.log(line, { to: 'debug' }),
    }
    const reporting: ReportIo = {
      board: { get: () => $.state.get(BOARD), set: (value, options) => $.state.set(BOARD, value, options) },
      decisions: { get: () => $.state.get(DECISIONS), set: (value, options) => $.state.set(DECISIONS, value, options) },
      debug: (line) => $.ui.log(line, { to: 'debug' }),
      now: () => $.clock.now(),
      toast: (text) => $.ui.toast(text),
    }
    const about = `${quoteStart(e.description)}（${e.subagentType}）`
    /** What every report of this agent says of it; its id is known once it has started (a spawn is not yet an agent). */
    const reportOf = (agent: string) => ({ feature: SWITCH, agent, subject: about, node: { kind: 'agent' as const, name: e.name ?? (e.description === '' ? e.subagentType : e.description), type: e.subagentType } })
    // Asked with the agents dispatched beside it (core/agent-lane.ts), which logs the request; it waits `agents.waitMs` at most.
    const waitMs = ctx.config.agents.waitMs
    const deadline = (await $.clock.now()) + waitMs
    const call = { id: e.tool_use_id, siblings: agentCallsBeside(recent, e.tool_use_id) }
    const late: AgentAnswer = { ok: false, failure: timedOut(waitMs) }
    const asked = await within(io.backend.sleep, askAgent(ctx, settings, { key: `agent:${e.parentAgentId ?? 'main'}`, kind: 'agent', input, call, deadline, about: `agent ${about}`, io }), waitMs, late)
    // The agent starts as the main agent asked; the board says why it was not routed, once it has an id to say it of.
    // A spawn refused beneath started no agent: there is nothing to say of it.
    const notRouted = async (failure: Failure) => {
      const started = await next(e)
      if (started.deny !== undefined) return started
      await report(reporting, { decision: { ...reportOf(started.agentId ?? e.tool_use_id), routed: false, failure: { backend: ctx.backend.name, ...failure } } })
      leaveNote({ routed: false, started: started.model, why: { failure, backend: ctx.backend.name } })
      return started
    }
    if (!asked.ok) return notRouted(asked.failure)
    const decision = asked.decision
    // The main agent's pick, when it stands, goes on as the main agent wrote it.
    const spawn = decision.model !== null && decision.model !== modelFamily(e.model) ? { ...e, model: decision.model } : e
    const result = await next(spawn)
    if (result.deny !== undefined) return result
    leaveNote({ routed: true, decision, started: result.model, requested: modelFamily(e.model), thetaOverride: settings.thetaOverride })
    // The agent has started: nothing after this may fail its spawn.
    try {
      // The effort and the person's terms go into the plan (what changes the agent later keeps to the
      // terms); the model is set on the spawn, and a planned model would also pin every step against the
      // engine's overload fallback.
      const terms = termsOf(decision)
      if (result.agentId !== undefined && (decision.effort !== null || terms !== null)) {
        await $.state.set({ ...AGENTS, id: result.agentId }, { effort: decision.effort, floor: null, model: null, terms })
      }
      const family = decision.model ?? modelFamily(result.model)
      const model = family ?? result.model
      const outcome = decision.effort === null ? model : `${model} ${decision.effort}`
      await report(reporting, {
        decision: {
          ...reportOf(result.agentId ?? e.tool_use_id),
          routed: true,
          outcome,
          reason: dispatchReason(decision, modelFamily(e.model), settings.thetaOverride, '主 agent 指定的'),
          ...dispatchEvidence(decision),
          ...(family === null ? {} : { model: family }),
          ...(decision.effort === null ? {} : { effort: decision.effort }),
        },
      })
    } catch (error) {
      $.ui.log(`agent ${about} started (${result.agentId ?? 'no id'}), but its plan was not recorded: ${String(error)}`, { to: 'debug' })
    }
    return result
  })
}

/** The conversation of the loop `agentId` (absent: the main one), as the transcript rows; none when it cannot be read. */
async function conversationOf($: EngineInterface, agentId: string | undefined): Promise<readonly ContextMessage[]> {
  const read: unknown = await (agentId === undefined ? $.session.messages() : $.session.messages({ agentId })).catch(() => [])
  return Array.isArray(read) ? (read as ContextMessage[]) : []
}

