// Feature: find_skill (#12). Most skills are left out of the main agent's
// listing (features/skills.ts, ADR 0002), so when, partway through a turn,
// the work turns out to need a skill nobody suggested, the main agent can ask:
// it calls the tool with a few words on the work, and the decision model rates
// the session's skills against them, the same way it rates them beside a
// message (the same ranker, `modRanker`, in the same two stages (#11), over the
// same skills and their profiles, with the recent conversation read by the
// same rules). Nothing is pushed: the skills come back only as the tool's
// answer.
//
// Its switch is `find-skill` (`/dp find-skill off`), apart from `skills`
// (spec #56). The tool stays registered whatever the switches say, with a
// description that never changes (the tool list is part of the prompt cache);
// switched off, it says so when called.

import type { EngineInterface, HttpInit, On } from 'claude-code'
import { type Asked, type BackendIo, describeAsked, errorText, failureText } from '../decision/backend.ts'
import { turnStartState } from '../decision/context.ts'
import { quoteStart } from '../decision/redact.ts'
import { modRanker, pickSkills, skillOpening, type SkillPick, type SkillPolicy, type SkillRanking } from '../decision/skills.ts'
import { answersFor, mergeParts, type DecisionRequest } from '../decision/system-one.ts'
import { readSessionSkills } from '../core/profiles.ts'
import { report, type ReportIo } from '../core/report.ts'
import type { Ctx } from '../core/setup.ts'
import { describeStages, rankingSettings, type CatalogSkill } from '../core/skills.ts'
import { defineSwitch, isOn, masterOn } from '../core/switches.ts'

const CATALOG = { plugin: 'dispatch-pilot', key: 'skillCatalog' } as const
const BOARD = { plugin: 'dispatch-pilot', key: 'board' } as const
const DECISIONS = { plugin: 'dispatch-pilot', key: 'decisionLog' } as const
const PPLX_RATE = { plugin: 'dispatch-pilot', key: 'pplxRate' } as const

/** The switch's name, in `/dp` and in the decision log. */
const SWITCH = 'find-skill'
/** The skills feature's switch for profiles (#11): off, skills are rated by their descriptions here too. */
const PROFILES = 'skill-profiles'
/** The tool's name; the model calls it as `mcp__dispatch-pilot__find_skill`. */
const TOOL = 'find_skill'
const TOOL_CALLED = 'mcp__dispatch-pilot__find_skill'

/** What the model reads about the tool. Fixed: nothing of the session goes into it. */
const DESCRIPTION =
  "Searches this session's skills for the ones that fit a piece of work, and returns each one's exact name, its relevance (0 to 1) and what it is for. Use it when the work at hand might have a skill you have not been shown: a file format, a service or its tooling, or a way of working such as reviewing, planning, testing or releasing. Load a skill it returns with the Skill tool by that exact name. Skills only the user can start are never returned."
const INPUT = {
  type: 'object',
  properties: {
    query: {
      type: 'string',
      description: 'The kind of work you need a skill for, in a few words, such as "fill in a form in a PDF file" or "review a branch before merging".',
    },
  },
  required: ['query'],
  additionalProperties: false,
}
/** How an answer that brings no skill ends: the main agent's way on. */
const CARRY_ON = 'Carry on without it, or load a skill you know with the Skill tool by its exact name.'

/**
 * The session's skills: as read earlier this session (the skills feature
 * reads them at its start), else read now, with the profiles the store holds
 * (#11), and kept for the session; null when the session cannot be read.
 */
async function sessionCatalog($: EngineInterface, model: string): Promise<CatalogSkill[] | null> {
  const { value } = await $.state.get(CATALOG)
  if (value) return value.skills
  const found = await readSessionSkills(
    {
      commands: () => $.command.list(),
      listed: async () => (await $.session.usage({ breakdown: 'summary' })).context.breakdown?.skills?.skillFrontmatter ?? [],
      overrides: async (source) => (await $.settings.read({ source })).skillOverrides,
      home: () => $.env.get('HOME'),
      cwd: () => $.session.cwd(),
      exists: (path) => $.fs.exists(path),
      read: (path) => $.fs.read(path),
      list: (path) => $.fs.list(path),
      get: (key) => $.store.get(key),
    },
    model,
  )
  if (found !== null) await $.state.set(CATALOG, { skills: found.skills })
  return found?.skills ?? null
}

/** One decision request for find_skill through the person's decision model, its outcome in the debug log. */
async function askLogged($: EngineInterface, ctx: Ctx, what: string, about: string, request: DecisionRequest, timeoutMs: number): Promise<Asked> {
  const io: BackendIo = {
    fetch: (url: string, init: HttpInit) => $.http.fetch(url, init),
    sleep: (ms: number, signal: AbortSignal) => $.clock.sleep(ms, { signal }),
    pace: { now: () => $.clock.now(), sentAt: { get: () => $.state.get(PPLX_RATE), set: (value, options) => $.state.set(PPLX_RATE, value, options) } },
  }
  const startedAt = await $.clock.now()
  const asked = await ctx.backend.ask(io, request, timeoutMs)
  const ms = (await $.clock.now()) - startedAt
  $.ui.log(`${what} [${Object.keys(request.questions).join(', ')}] to ${ctx.backend.name} ${about}: ${describeAsked(asked, ms)}`, { to: 'debug' })
  return asked
}

/** The opening of a catalog skill's SKILL.md for the ranking's second stage; null when it has no file. */
async function openingOf($: EngineInterface, catalog: readonly CatalogSkill[], name: string): Promise<string | null> {
  const file = catalog.find((skill) => skill.name === name)?.file ?? null
  return file === null ? null : skillOpening(await $.fs.read(file))
}

export function registerFindSkill(on: On, ctx: Ctx): void {
  defineSwitch({ name: SWITCH, info: '回答主 agent 的 find_skill：挑出适合它说的那项工作的 skill' })

  /** Skills never offered (the option the skills feature reads too). */
  const neverSuggested = new Set(ctx.config.skills.neverSuggested)
  const policy = (): SkillPolicy => ctx.config.skills.find
  /** How the mod's ranker ranks: the settings it rates the skills beside each message with. */
  const rankBy = rankingSettings(ctx)
  /** The model whose profiles the skills are offered by (#11). */
  const model = ctx.config.skills.profileModel

  // Registered once every plugin is loaded, under a match-all matcher (other
  // features set themselves up at session start too). Without a decision
  // model nothing could rate the skills, and the main agent keeps its listing.
  on('session.start', { cwd: /(?:)/ }, async ($, e, next) => {
    const result = await next(e)
    if (ctx.backend.configured === false) return result
    try {
      // In the prompt's tool list (2.1.293 on; older engines put it behind ToolSearch, as the listing's hint allows for):
      // the main agent's skill listing is cut short, and this is its way to the rest. Its description never changes.
      const { tool } = await $.tool.register({ name: TOOL, description: DESCRIPTION, inputSchema: INPUT, isDeferred: false })
      if (tool !== TOOL_CALLED) $.ui.log(`find_skill is registered as ${tool}, but the hook answers ${TOOL_CALLED}: its calls will fail`, { to: 'debug' })
    } catch (error) {
      $.ui.log(`find_skill was not registered: ${errorText(error)}`, { to: 'debug' })
    }
    return result
  })

  // The model's call: answered here, never passed on. Whatever goes wrong,
  // the answer says so at once (fail open: the turn goes on without a skill).
  on('tool.call', { tool: TOOL_CALLED }, async ($, e) => {
    if (!masterOn()) return { result: `Dispatch Pilot is switched off (/dp on turns it back on), so find_skill rated no skills. ${CARRY_ON}` }
    if (!isOn(SWITCH)) return { result: `find_skill is switched off (/dp ${SWITCH} on turns it back on), so it rated no skills. ${CARRY_ON}` }
    // A dispatched agent's listing is left whole (ADR 0002): it has every skill in view.
    if (e.agentId !== undefined) {
      return { result: "find_skill rates skills for the main agent, whose skill listing is cut short. Yours lists this session's skills: pick from it and load one with the Skill tool by its exact name." }
    }
    const query = typeof e.query === 'string' ? e.query.replace(/\s+/g, ' ').trim() : ''
    if (query === '') return { result: 'find_skill needs a query: a few words on the kind of work you need a skill for.' }
    const io: ReportIo = {
      board: { get: () => $.state.get(BOARD), set: (value, options) => $.state.set(BOARD, value, options) },
      decisions: { get: () => $.state.get(DECISIONS), set: (value, options) => $.state.set(DECISIONS, value, options) },
      debug: (line) => $.ui.log(line, { to: 'debug' }),
      now: () => $.clock.now(),
      toast: (text) => $.ui.toast(text),
    }
    // The main agent's own call, beside its decision for the turn: in the log, not on its node.
    const call = { feature: SWITCH, agent: 'main', aside: true as const }
    try {
      // The skills the main agent can load, as a message asks about them: their question of stage
      // one is the very one beside a message (those only the person can start have one of their
      // own, which is not asked: they never come back); each by its profile, as beside a message,
      // unless profiles are switched off.
      const known = await sessionCatalog($, model)
      const candidates = known?.filter((skill) => skill.by === 'model' && !neverSuggested.has(skill.name)).map((skill) => (isOn(PROFILES) ? skill : { ...skill, profile: null })) ?? null
      if (candidates === null) {
        await report(io, { decision: { ...call, skipped: 'unread' as const } })
        return { result: `find_skill could not read this session's skills. ${CARRY_ON}` }
      }
      const about = `for find_skill ${quoteStart(query)}`
      const ranker = modRanker(
        {
          ask: (request, timeoutMs) => askLogged($, ctx, 'second request', about, request, timeoutMs),
          opening: (option) => openingOf($, candidates, option.name),
        },
        rankBy,
      )
      // The first request offers each skill by its profile where the decision model can read them all in time
      // (BACKEND_DEFAULTS findSkillProfiles), else by its description; the second re-reads by both.
      const part = ranker.part(ctx.config.skills.findByProfile ? candidates : candidates.map((skill) => ({ ...skill, profile: null })))
      if (part === null) {
        await report(io, { decision: { ...call, skipped: 'none' as const } })
        return { result: `This session has no skill that find_skill could return. ${CARRY_ON}` }
      }

      // The same state as beside a message, the work named in place of the message; the ranker's second
      // request (#11) asks about the same. Both requests share one wait: the second gets what the first left
      // of it. The wait is the decision model's (findWaitMs: a message's timeoutMs with Jev),
      // within the hook's own 10 s.
      const waitMs = ctx.config.skills.findWaitMs
      const startedAt = await $.clock.now()
      const messages = ctx.config.context.messages > 0 ? await $.session.messages().catch(() => []) : []
      const request = mergeParts(turnStartState({ prompt: query, messages, limits: ctx.config.context }), [part])
      const asked = await askLogged($, ctx, 'request', about, request, waitMs)
      const left = waitMs - ((await $.clock.now()) - startedAt)
      const ranked = asked.ok ? await ranker.rank(answersFor(part, asked.answers), candidates, { state: request.state, timeoutMs: left }) : null
      const unranked = { kind: 'parse' as const, detail: 'no answer about the skills' }
      const lost = !asked.ok ? asked.failure : ranked === null ? unranked : ranked.failed
      if (ranked === null || lost !== undefined) {
        const failure = lost ?? unranked
        const why = failureText(ctx.backend.name, failure)
        await report(io, { decision: { ...call, failure: { backend: ctx.backend.name, ...failure } } })
        return { result: `find_skill could not rate the skills (${why}). ${CARRY_ON}` }
      }

      // Only skills the main agent can load were asked about, and they alone can come back.
      const { suggest } = pickSkills(ranked, candidates, policy())
      const names = suggest.map((skill) => skill.name).join('、')
      await report(io, {
        decision: {
          ...call,
          subject: quoteStart(query),
          outcome: suggest.length > 0 ? `查到 ${names}` : '没查到 skill',
          reason: describeRanking(ranked, policy()),
          tone: suggest.length > 0 ? 'ok' : 'info',
          skills: { suggest: suggest.map(({ name, relevance }) => ({ name, relevance })), try: [] },
        },
      })
      return { result: found(query, suggest, policy()) }
    } catch (error) {
      $.ui.log(`find_skill failed: ${errorText(error)}`, { to: 'debug' })
      await report(io, { decision: { ...call, skipped: 'error' as const } })
      return { result: `find_skill could not rate the skills (an error in Dispatch Pilot, written to the debug log). ${CARRY_ON}` }
    }
  })
}

/** Why: what each stage of the ranking said (`describeStages`), and the bar a skill had to reach. */
function describeRanking(ranking: SkillRanking, policy: SkillPolicy): string {
  return `${describeStages(ranking)}；相关度 ${policy.minRelevance.toFixed(2)} 起返回，最多 ${policy.max} 个`
}

/** The answer: the skills that fit, each by name, relevance and description, most relevant first; or that none does. */
function found(query: string, suggest: readonly SkillPick[], policy: SkillPolicy): string {
  if (suggest.length === 0) {
    return `No skill fits "${query}": none reached relevance ${policy.minRelevance.toFixed(2)}. Carry on without one, try other words for the work, or load a skill you know with the Skill tool by its exact name.`
  }
  return [
    `Skills that fit "${query}", rated by Dispatch Pilot’s decision model (relevance 0 to 1), most relevant first. Load one with the Skill tool by its exact name if it fits the work:`,
    ...suggest.map((skill) => `- ${skill.name} (relevance ${skill.relevance.toFixed(2)})${skill.description ? `: ${skill.description}` : ''}`),
  ].join('\n')
}

files.hooks/features/image-routing.ts:
// Feature: image routing (#63, ADR 0008), the first half. When the person's message comes with reference images, its effort is
// decided from what the images read as, not from the words alone: how complex it is to build what they show.
//
// The switch is `image-routing` (`/dp image-routing on`), off by default: the images leave the machine for the decision model.
//
// The effort question of such a message is not in its ballot (features/main-effort.ts hands it to core/deferred.ts instead). The
// images are not in `prompt.submit` (it carries their metadata only), they are in the message's row when the engine appends it
// (`session.append`, door `prompt`; the row also names the file the original is in). So the decision waits for the turn:
//   1. session.append  notes the message's images (their files, or their bytes when no file is named), not the whole conversation.
//   2. turn.start      reads the images (core/complexity.ts: a request to the decision model that takes images, at most ~3 s, a
//                      group asked only once), then sends the effort question with the reading in its state, as any message's,
//                      and writes the answer as a pending decision, which the core claims in this same `turn.start`: the first
//                      step goes out at that effort. The core stays the one writer of the plan (ADR 0003).
// Whatever goes wrong with the reading, the effort is decided without it; when the effort request fails, the turn goes out
// unrouted, and says why (the main-effort feature's report). A lock, and an effort or a model the person named, still come
// first: the plan table's priorities are not touched (core/plans.ts `planStep`).

import type { EngineInterface, HttpInit, On } from 'claude-code'
import { type BackendIo, describeAsked, errorText, within } from '../decision/backend.ts'
import type { ReferenceReading } from '../decision/complexity.ts'
import { MIN_ASK_MS } from '../core/agent-lane.ts'
import { askGroups, type AskIo } from '../core/ask-group.ts'
import { CALL_ROOM_MS } from '../core/call-budget.ts'
import { readReferenceComplexity, type ComplexityIo, type ReferenceReadings, type ReferenceSource } from '../core/complexity.ts'
import { enteringPrompt } from '../core/core.ts'
import type { Cell } from '../core/plans.ts'
import { takeDeferred } from '../core/deferred.ts'
import type { ImageFilesIo } from '../core/image-files.ts'
import { report, type NodeFailure, type ReportIo } from '../core/report.ts'
import type { Ctx } from '../core/setup.ts'
import { defineSwitch, isOn, masterOn } from '../core/switches.ts'
import { newWorkFile } from '../core/work-files.ts'

/** The switch's name, in `/dp` and in the decision log. */
export const IMAGE_ROUTING_SWITCH = 'image-routing'

const PPLX_RATE = { plugin: 'dispatch-pilot', key: 'pplxRate' } as const
const READINGS = { plugin: 'dispatch-pilot', key: 'referenceReadings' } as const
const BOARD = { plugin: 'dispatch-pilot', key: 'board' } as const
const DECISIONS = { plugin: 'dispatch-pilot', key: 'decisionLog' } as const

/** How long the turn's start waits for the reading: the images prepared and the request answered (ADR 0008: about 3 seconds). */
const READING_WAIT_MS = 3000

/** Whether a prompt's attachments (`prompt.submit`'s `e.attachments`) include an image. */
export function hasImage(attachments: readonly { type: string }[] | undefined): boolean {
  return attachments?.some((attachment) => attachment.type === 'image') === true
}

// ---- The images of the message --------------------------------------------------------------------------------------

/** A message's images as its row carried them: the words (what the person typed) and the images to read. */
type Pasted = { text: string; sources: ReferenceSource[] }

/**
 * The latest messages' images, newest last (module level: the message's row comes in `session.append` and its turn starts a
 * moment later; a hot reload in between loses them, at the cost of that one message's reading). They are taken when the turn
 * starts, and a message that never starts a turn is pushed out by the next ones.
 */
const pasted: Pasted[] = []
const MOST_PASTED = 4

/** A pasted image's bytes are kept for a reading only up to this long (base64 characters): the file the row names is the better source. */
const MOST_BYTES = 12_000_000

/** A block of a row's content, as the engine appends it. */
export type Block = { type: string; [field: string]: unknown }

/**
 * The file a row names for an image the person pasted: the engine adds a text block, `[Image: source: <path> ...]`, with the
 * path of the original (before it was scaled to fit the model). Null for any other text.
 */
function sourceOf(text: string): string | null {
  return /\[Image: source: (\/[^\s\]]*?\.(?:png|jpe?g|gif|webp|heic|heif|tiff?|bmp))/i.exec(text)?.[1] ?? null
}

/** What the images of a user row come to: their files when the row names them, else their bytes. Null for a row with no image. */
export function pastedOf(content: readonly Block[]): Pasted | null {
  const images = content.filter((block) => block.type === 'image')
  if (images.length === 0) return null
  const texts = content.flatMap((block) => (block.type === 'text' && typeof block.text === 'string' ? [block.text] : []))
  const paths = texts.flatMap((text) => {
    const path = sourceOf(text)
    return path === null ? [] : [path]
  })
  const bytes = images.flatMap((block) => {
    const source = block.source as { data?: unknown } | undefined
    return typeof source?.data === 'string' && source.data.length <= MOST_BYTES ? [source.data] : []
  })
  const sources: ReferenceSource[] = paths.length > 0 ? paths.map((path) => ({ path })) : bytes.map((base64) => ({ base64 }))
  return { text: texts.filter((text) => !text.startsWith('[Image')).join('\n').trim(), sources }
}

/**
 * The images of the message the turn starts for (the latest one whose words are one of `texts`); they are taken. Null when no
 * message matches: the images of another message are not guessed at, the effort is decided without a reading.
 */
function takePasted(texts: readonly string[]): Pasted | null {
  const wanted = texts.map((text) => text.trim())
  let at = -1
  pasted.forEach((one, i) => {
    if (wanted.includes(one.text)) at = i
  })
  const found = pasted[at]
  pasted.length = 0
  return found ?? null
}

// ---- The engine, as closures -----------------------------------------------------------------------------------------

/** The files the images need of the engine, as closures. */
function filesOf($: EngineInterface): ImageFilesIo {
  return {
    run: (argv, init) => $.process.run(argv, init),
    readBytes: async (path) => (await $.fs.read(path, { as: 'bytes' })).base64,
    // The session's directory in the mod's temporary directory, like every file the mod makes (core/work-files.ts, #62).
    newFile: (extension) => newWorkFile({ run: (argv) => $.process.run(argv), tmpdir: () => $.env.get('TMPDIR'), sessionId: () => $.session.id() }, extension),
  }
}

export function registerImageRouting(on: On, ctx: Ctx): void {
  defineSwitch({ name: IMAGE_ROUTING_SWITCH, info: '带图路由：发消息带参考图时，先读出图的复杂度，再决定主 agent 的 effort（默认关，图会发给决策模型）', default: false })

  // The message's row: its images, noted for the turn that starts next. Looked at only while the feature could use them, and
  // never changed.
  on('session.append', { door: 'prompt' }, async (_$, e, next) => {
    if (e.agentId === undefined && e.message.type === 'user' && isOn(IMAGE_ROUTING_SWITCH) && ctx.images !== null) {
      const one = pastedOf(e.message.content as Block[])
      if (one !== null) {
        pasted.push(one)
        if (pasted.length > MOST_PASTED) pasted.shift()
      }
    }
    return next(e)
  })

  // The main agent's turn starts: the message that came with images is decided now. Inside the core's `turn.start`, which claims
  // the decision written here.
  on('turn.start', { turnId: /(?:)/ }, async ($, e, next) => {
    if (e.agentId !== undefined) return next(e)
    const entering = enteringPrompt()
    const taken = takeDeferred(entering === undefined ? [e.text] : [entering, e.text])
    if (taken === null) return next(e)
    try {
      // Switched off (/dp off) since the message was sent: nothing is asked, the turn goes out as the engine made it.
      if (masterOn()) await decide($, ctx, taken, [e.text, taken.prompt])
    } catch (error) {
      $.ui.log(`image routing: ${errorText(error)}`, { to: 'debug' })
    }
    return next(e)
  })
}

/** What a request to the decision model needs of the engine, as closures. */
function backendOf($: EngineInterface): BackendIo {
  return {
    fetch: (url: string, init: HttpInit) => $.http.fetch(url, init),
    sleep: (ms: number, signal: AbortSignal) => $.clock.sleep(ms, { signal }),
    pace: { now: () => $.clock.now(), sentAt: { get: () => $.state.get(PPLX_RATE), set: (value, options) => $.state.set(PPLX_RATE, value, options) } },
  }
}

/**
 * Everything a reading needs of the engine, as closures: `$` may not cross a file (DEVELOPMENT.md 「事件和 matcher」), and a picture
 * met in the middle of a turn (features/reference-midturn.ts) is read the same way. Each hook file builds it from its own `$`.
 */
export type ReadIo = {
  backend: BackendIo
  files: ImageFilesIo
  store: Cell<ReferenceReadings>
  now: () => Promise<number>
  debug: (line: string) => void
  /** A reading that failed, for the board's notes: beside the route, no toast. */
  note: (failure: NodeFailure) => Promise<void>
}

/**
 * What the reference images `sources` read as: asked of the image backend (a group read before is answered from the readings
 * kept), within `READING_WAIT_MS`. Null when there is no reading: no image backend, the images could not be read, the request
 * failed or came too late; the board notes a failed one, beside the route and without a toast. Never throws. The message that
 * starts a turn (below) and a picture met in the middle of one (features/reference-midturn.ts) read the same way.
 */
export async function readReference(io: ReadIo, ctx: Ctx, sources: readonly ReferenceSource[]): Promise<ReferenceReading | null> {
  const images = ctx.images
  if (images === null || sources.length === 0) return null
  try {
    const complexity: ComplexityIo = {
      files: io.files,
      ask: async (request) => {
        const at = await io.now()
        const asked = await images.backend.ask(io.backend, request, READING_WAIT_MS)
        io.debug(`complexity reading [${Object.keys(request.questions).join(', ')}] to ${images.backend.name}: ${describeAsked(asked, (await io.now()) - at)}`)
        return asked
      },
      store: io.store,
      now: io.now,
      backend: images.name,
      debug: io.debug,
    }
    const late = { late: true } as const
    const read = await within(io.backend.sleep, readReferenceComplexity(complexity, sources), READING_WAIT_MS, late)
    if ('late' in read) {
      io.debug(`image routing: no reading in ${READING_WAIT_MS} ms; the effort is decided without it`)
      await io.note({ backend: images.name, kind: 'timeout', detail: `no reading in ${READING_WAIT_MS} ms` })
      return null
    }
    if (read.ok) {
      io.debug(`image routing: the images read as level ${read.reading.level} (${read.cached ? 'read before' : 'asked'}), from ${read.reading.images} image${read.reading.images === 1 ? '' : 's'}`)
      return read.reading
    }
    io.debug(`image routing: no reading (${read.reason}); the effort is decided without it`)
    if (read.failure !== undefined) await io.note({ backend: images.name, ...read.failure })
    return null
  } catch (error) {
    io.debug(`image routing: ${errorText(error)}`)
    return null
  }
}

/** What a reading needs of the engine, from this file's hooks. */
function readIoOf($: EngineInterface): ReadIo {
  return {
    backend: backendOf($),
    files: filesOf($),
    store: { get: () => $.state.get(READINGS), set: (value: ReferenceReadings, options) => $.state.set(READINGS, value, options) },
    now: () => $.clock.now(),
    debug: (line) => $.ui.log(line, { to: 'debug' }),
    note: (failure) => note($, failure),
  }
}

/** The message's effort, decided with the reading of its images when there is one. */
async function decide($: EngineInterface, ctx: Ctx, taken: NonNullable<ReturnType<typeof takeDeferred>>, texts: readonly string[]): Promise<void> {
  const debug = (line: string) => $.ui.log(line, { to: 'debug' })
  const backend = backendOf($)
  const startedAt = await $.clock.now()
  let reading: ReferenceReading | null = null
  // Off since the message was sent: it is decided as any message is, without its images.
  if (ctx.images !== null && isOn(IMAGE_ROUTING_SWITCH)) {
    const found = takePasted(texts)
    if (found === null || found.sources.length === 0) debug('image routing: the message came with images, but none was found to read; its effort is decided without a reading')
    else reading = await readReference(readIoOf($), ctx, found.sources)
  }
  // The effort question, as a message's ever is: the reading is in its state. Its answer is written as the pending decision.
  const messages = ctx.config.context.messages > 0 ? await $.session.messages().catch(() => []) : []
  const spent = (await $.clock.now()) - startedAt
  const io: AskIo = { backend, now: () => $.clock.now(), debug }
  // A `$.clock.sleep` counts toward the hook's 10 s: the effort request waits for what is left of the call room, never longer than the decision model's own setting.
  await askGroups(io, ctx, { prompt: taken.prompt, messages, groups: [[taken.deferred(reading)]], maxWaitMs: Math.max(MIN_ASK_MS, CALL_ROOM_MS - spent) })
}

/** A reading that failed, for the board's notes: beside the route, no toast (the effort is decided all the same). */
async function note($: EngineInterface, failure: NodeFailure): Promise<void> {
  const io: ReportIo = {
    board: { get: () => $.state.get(BOARD), set: (value, options) => $.state.set(BOARD, value, options) },
    decisions: { get: () => $.state.get(DECISIONS), set: (value, options) => $.state.set(DECISIONS, value, options) },
    debug: (line) => $.ui.log(line, { to: 'debug' }),
    now: () => $.clock.now(),
    toast: (text) => $.ui.toast(text),
  }
  await report(io, { decision: { feature: IMAGE_ROUTING_SWITCH, agent: 'main', aside: true, failure } })
}

files.hooks/features/main-effort.ts:
// Feature: the main agent's effort, decided each time the person sends a
// message, and when a report starts a turn of its own: a dispatched agent's
// hand-back or a background task's notice reaching the idle session (those
// turns are usually a look at a result and the next dispatch; the session's own
// effort would be a waste). It adds the effort question to the message's ballot
// (the core sends it); the answer becomes the effort of the turn the message
// starts, on every step of that turn (the core's turn.step writer). A report's
// text is read as the message; its turn is not re-decided mid-turn.
//
// A command turn (#19: `/implement #19`, a skill or markdown command the
// person typed) is decided like their message: the decision model reads the
// command as typed and what the command is for (core/commands.ts), never the
// prompt it expands to.
//
// A message typed while a turn runs (`e.turnId`) is delivered into that turn
// at its next step (a `queued_command` attachment; measured on 2.1.289), so
// its decision takes the running turn from then on. It also waits as pending,
// in case the turn ends first and the message starts a turn of its own.

import type { EngineInterface, On } from 'claude-code'
import { errorText } from '../decision/backend.ts'
import { EFFORTS, LEVEL, probsOf, readEffort, readingText, traceEffort, type Effort, type EffortReading } from '../decision/effort.ts'
import { quoteStart } from '../decision/redact.ts'
import { turnStartPart } from '../decision/turn-start.ts'
import { givesHint, HINTED, judgeUnresolved, readUnresolved, UNRESOLVED, usesHinted } from '../decision/unresolved.ts'
import { contribute, type Contribution, type PartOutcome } from '../core/ballot.ts'
import { commandOf, commandState } from '../core/commands.ts'
import { hintDecision, keptCount, keptSummary, moveCount, unresolvedDecision, type CountCell } from '../core/unresolved.ts'
import { defer, withdraw } from '../core/deferred.ts'
import { addPending, revise, turnKey, update, type Cell, type PendingDecision, type TurnRecord } from '../core/plans.ts'
import { isPersonsMessage, startsReportTurn } from '../core/prompts.ts'
import { report, type HintRecord, type ReferenceRecord, type ReportIo, type UnresolvedRecord } from '../core/report.ts'
import { hintedRules, type Ctx } from '../core/setup.ts'
import { defineSwitch, isOn } from '../core/switches.ts'
import type { ReferenceReading } from '../decision/complexity.ts'
import { hasImage, IMAGE_ROUTING_SWITCH } from './image-routing.ts'
import { UNRESOLVED_SWITCH } from './unresolved.ts'

const PENDING = { plugin: 'dispatch-pilot', key: 'pending' } as const
const TURNS = { plugin: 'dispatch-pilot', key: 'turns' } as const
const BOARD = { plugin: 'dispatch-pilot', key: 'board' } as const
const DECISIONS = { plugin: 'dispatch-pilot', key: 'decisionLog' } as const
const CATALOG = { plugin: 'dispatch-pilot', key: 'skillCatalog' } as const
const COUNT = { plugin: 'dispatch-pilot', key: 'unresolved' } as const

/**
 * What a command turn's command is for: its skill in the session's catalog as
 * the skills feature read it (by its profile while profiles are on), else the
 * command as `$.command.list()` describes it.
 */
async function describeCommand($: EngineInterface, name: string): Promise<Readonly<Record<string, string>> | null> {
  const { value: catalog } = await $.state.get(CATALOG)
  const found = catalog?.skills.find((skill) => skill.name === name)
  const skill = found && !isOn('skill-profiles') ? { ...found, profile: null } : found
  const listed = skill?.description ? undefined : (await $.command.list().catch(() => [])).find((command) => command.name === name)?.description
  return commandState(name, skill, listed)
}

/** The unresolved count and summary in `$.state`, as a cell. */
function countCell($: EngineInterface): CountCell {
  return { get: () => $.state.get(COUNT), set: (value, options) => $.state.set(COUNT, value, options) }
}

export function registerMainEffort(on: On, ctx: Ctx): void {
  defineSwitch({ name: 'main-effort', info: '发消息时决定主 agent 的 effort' })

  on('prompt.submit', { text: /(?:)/ }, async ($, e, next) => {
    // The person's own message, or a report that starts a turn of its own (a dispatched agent's hand-back, a task notice).
    const handBack = !isPersonsMessage(e) && startsReportTurn(e)
    if ((!isPersonsMessage(e) && !handBack) || !isOn('main-effort')) return next(e)
    const pending: Cell<PendingDecision[]> = { get: () => $.state.get(PENDING), set: (value, options) => $.state.set(PENDING, value, options) }
    let added: PendingDecision | null = null

    /** The message waits for its turn, decided or not: the turn it starts is the person's own (mid-turn re-decisions are for such turns). */
    const wait = async (effort: Effort | null) => {
      const entry: PendingDecision = { text: e.text, effort, at: await $.clock.now(), ...(handBack ? { report: true as const } : {}) }
      await update(pending, (list) => addPending(list ?? [], entry))
      added = entry
    }

    const ran = handBack ? null : commandOf(e.text)
    const command = ran === null ? null : await describeCommand($, ran.command)

    // The person's own message also asks whether it says the problem they are on is still not solved (the unresolved
    // count); a report that starts a turn is no word of theirs, and the switch can leave the question out. It travels
    // in this part, so it is in the effort request with the state it reads (ADR 0005).
    const counting = !handBack && isOn(UNRESOLVED_SWITCH)
    // The summary there is: a write that is not done yet is no reason to wait, the decision uses the one before it.
    const summary = counting ? await keptSummary(countCell($)).catch(() => null) : null
    // The count before this message (its own answer comes in the same request), and with it the strong hint once it has
    // reached the setting: a sentence in the effort question about the kind of work, the level still the decision model's (ADR 0005).
    const count = counting ? await keptCount(countCell($)).catch(() => 0) : 0
    const maxAfter = ctx.config.unresolved.maxAfter
    const hint: HintRecord | undefined = givesHint(count, maxAfter) ? { count, maxAfter } : undefined
    // A message with reference images (#63) is decided when its turn starts, once its images have been read: its effort part
    // does not go in the ballot, and the image-routing feature asks it at `turn.start` (core/deferred.ts). That turn has started
    // by then, so its decision is about the turn running.
    const imaged = !handBack && ran === null && e.turnId === undefined && ctx.images !== null && isOn(IMAGE_ROUTING_SWITCH) && hasImage(e.attachments)
    // About the main agent of the turn this message starts, or of the one running when it was typed into it.
    const forTurn = e.turnId === undefined && !imaged ? ('next' as const) : ('current' as const)

    /** Whether the hinted effort answer was the one used (set by decideEffort; false when it was not asked or not used). */
    let hintUsed = false

    /** The effort this message's turn goes out at, and the board's word for it. */
    const decideEffort = async (outcome: PartOutcome, io: ReportIo, unresolved?: UnresolvedRecord, reference?: ReferenceRecord): Promise<Effort | null> => {
      const about = { feature: handBack ? 'main-effort (agent report)' : 'main-effort', agent: 'main', forTurn, subject: quoteStart(e.text) }
      if (!outcome.ok) {
        await report(io, { decision: { ...about, routed: false, failure: { backend: ctx.backend.name, ...outcome.failure } } })
        await wait(null)
        return null
      }
      // With the strong hint the request asked the hinted effort question beside the plain one: its answer is taken when this
      // message's own three-way answer added one to the count (the problem is still unresolved), else the plain one's.
      const hintedReading = hint === undefined || !usesHinted(unresolved?.change ?? null) ? null : readEffort(outcome.answers[HINTED])
      const reading = hintedReading ?? readEffort(outcome.answers[LEVEL])
      if (hint !== undefined) hintUsed = hintedReading !== null
      if (reading === null) {
        await report(io, { decision: { ...about, routed: false, failure: { backend: ctx.backend.name, kind: 'parse', detail: 'no effort answer' } } })
        await wait(null)
        return null
      }
      // pickEffort's rules with their working: the board shows the steps, never recomputes them (#23). With the strong hint, max has its own threshold.
      const rules = hintedReading === null ? ctx.config : hintedRules(ctx.config, ctx.config)
      const { effort, steps } = traceEffort(reading, rules)
      await report(io, {
        decision: {
          ...about,
          routed: true,
          outcome: `effort ${effort}`,
          // The level as data: what reads the log (the band, the pane) never reads it out of the words.
          effort,
          reason: describeReading(reading, effort, rules.thetaMax),
          probs: probsOf(reading),
          ...(reading.confidence === null ? {} : { conf: reading.confidence }),
          trace: steps,
          // What the reference images it came with read as: the card draws it with the effort's.
          ...(reference === undefined ? {} : { reference }),
          // What this message did to the unresolved count: the card draws it with the effort's.
          ...(unresolved === undefined ? {} : { unresolved }),
          // The card says the hint was given, and whether its answer was the one used.
          ...(hint === undefined ? {} : { hint: { ...hint, used: hintedReading !== null } }),
        },
      })
      await wait(effort)
      const running = e.turnId
      if (running !== undefined) {
        const ref = { ...TURNS, id: turnKey(running, undefined) }
        const turn: Cell<TurnRecord> = { get: () => $.state.get(ref), set: (value, options) => $.state.set(ref, value, options) }
        await update(turn, (record) => revise(record, effort))
      }
      return effort
    }

    /**
     * What the answer to the unresolved question does to the count, which is moved here: what the log and the card say
     * of it; null when there is no answer or the count cannot be kept (the debug log says so, the count stays).
     */
    const countUnresolved = async (answered: Extract<PartOutcome, { ok: true }>) => {
      const reading = readUnresolved(answered.answers[UNRESOLVED])
      if (reading === null) {
        $.ui.log(`unresolved for ${quoteStart(e.text)}: no answer, the count stays`, { to: 'debug' })
        return null
      }
      const judged = judgeUnresolved(reading)
      try {
        return unresolvedDecision(judged, await moveCount(countCell($), judged.change))
      } catch (error) {
        $.ui.log(`unresolved count not kept: ${errorText(error)}`, { to: 'debug' })
        return null
      }
    }

    /** The message's effort part; `reading`: what its reference images read as, when they have been (the state carries it, the decision reports it). */
    const effortPart = (reading: ReferenceReading | null): Contribution => ({
      // Asked as the decision model's table says for these questions (Chinese with Jev); the other questions keep ctx.ask's.
      ...turnStartPart({ ask: ctx.config.ask.turnStart, unresolved: counting, command, summary, count, maxAfter, reference: reading }),
      settle: async (outcome) => {
        const io: ReportIo = {
          board: { get: () => $.state.get(BOARD), set: (value, options) => $.state.set(BOARD, value, options) },
          decisions: { get: () => $.state.get(DECISIONS), set: (value, options) => $.state.set(DECISIONS, value, options) },
          debug: (line) => $.ui.log(line, { to: 'debug' }),
          now: () => $.clock.now(),
          toast: (text) => $.ui.toast(text),
        }
        // The count first, so the effort's decision can say what this message did to it; neither depends on the other
        // (either answer can be missing, and the effort is decided and kept whatever becomes of the count).
        const counted = counting && outcome.ok ? await countUnresolved(outcome) : null
        const effort = await decideEffort(outcome, io, counted?.unresolved, reading ?? undefined)
        // A count that moved is a decision of its own in the log (an answer that left it as it was is on the effort's card only).
        if (counted?.unresolved !== undefined && counted.unresolved.before !== counted.unresolved.count) {
          await report(io, { decision: { feature: UNRESOLVED_SWITCH, agent: 'main', aside: true, forTurn, subject: quoteStart(e.text), ...counted } })
        }
        // Each hint given is a decision of its own in the log: the count, that it was given, the level that came of it.
        if (hint !== undefined) await report(io, { decision: { feature: UNRESOLVED_SWITCH, agent: 'main', aside: true, forTurn, subject: quoteStart(e.text), ...hintDecision({ ...hint, used: hintUsed }, effort) } })
      },
    })
    if (imaged) defer(e.text, effortPart)
    else contribute(e.text, effortPart(null))

    const result = await next(e)
    // Refused beneath: no turn will take this decision.
    if (imaged && result.drop !== undefined) withdraw(e.text)
    const withdrawn = added as PendingDecision | null
    if (result.drop !== undefined && withdrawn !== null) {
      await update(pending, (list) => (list ?? []).filter((entry) => !(entry.text === withdrawn.text && entry.at === withdrawn.at)))
    }
    return result
  })
}

/** Why a level was picked: every level's probability, `max` held back below thetaMax when it was the most likely, and the backend's confidence. */
function describeReading(reading: EffortReading, picked: Effort, thetaMax: number): string {
  const p = reading.probabilities
  const max = p[EFFORTS.length - 1] ?? 0
  const held = picked !== 'max' && p.every((other) => other <= max)
  return readingText(reading, held ? `max 的概率没到 max 门槛 ${thetaMax.toFixed(2)}` : undefined)
}

