// Feature: the prompt hint. While the person writes a message, the prompt box
// shows after the draft, dimmed, what Dispatch Pilot already knows it will do
// with it (decision/prompt-hint.ts): switched off, the effort locked, a model
// or an effort named for the agents the message may dispatch. The text is
// `virtualText`: drawn only, never in the draft or the message sent.
//
// `prompt.edit` paints it after each edit the person types (its answer carries
// the decorations; 50 ms is all the hook has, so it reads one `$.state` value
// and nothing else). A draft that lands without an edit (`prompt.change`: a
// recalled history entry) carries none, so it is put back in the box once with
// the hint painted on it; the box keeps the same text and the cursor at its end,
// where a recall leaves it.
//
// Its switch is `prompt-hint` (`/dp prompt-hint off`).

import type { EngineInterface, On, PromptDecoration } from 'claude-code'
import { promptHint } from '../decision/prompt-hint.ts'
import { defineSwitch, isOn, masterOn } from '../core/switches.ts'

const LOCK = { plugin: 'dispatch-pilot', key: 'lock' } as const

/** The switch's name, in `/dp`. */
const SWITCH = 'prompt-hint'

/** The decorations that draw the hint after `text`; none when there is nothing to say. */
async function hintDecorations($: EngineInterface, text: string): Promise<PromptDecoration[]> {
  // Off with the mod too, but then the hint says so: the master switch is read on its own.
  if (masterOn() && !isOn(SWITCH)) return []
  const { value: lock = null } = masterOn() ? await $.state.get(LOCK) : { value: null }
  const hint = promptHint(text, { master: masterOn(), lock, agents: isOn('dispatched-agents') || isOn('workflow-agents') || isOn('workflow-labels') })
  return hint === null ? [] : [{ start: text.length, end: text.length, virtualText: `  ${hint}`, dimColor: true }]
}

export function registerPromptHint(on: On): void {
  defineSwitch({ name: SWITCH, info: 'show after the draft what dp will do with it (dim, never sent)' })

  on('prompt.edit', { origin: { kind: 'composer' } }, async ($, e, next) => {
    const box = await next(e)
    try {
      const mine = await hintDecorations($, box.text)
      return mine.length === 0 ? box : { ...box, decorations: [...(box.decorations ?? []), ...mine] }
    } catch {
      // no hint this time: the box is as the edit left it
      return box
    }
  })

  on('prompt.change', { origin: { kind: 'history' } }, async ($, e, next) => {
    const changed = await next(e)
    try {
      const mine = await hintDecorations($, e.text)
      if (mine.length > 0) await $.prompt.fill({ text: e.text, mode: 'replace', decorations: mine })
    } catch {
      // the recalled draft goes without its hint until the next edit
    }
    return changed
  })
}

files.hooks/features/reference-midturn.ts:
// Feature: image routing, the second half (#64, ADR 0008). The first half (features/image-routing.ts) reads the reference images a
// message comes with before its turn's first effort. Here the main agent meets reference images in the middle of a turn, and
// the effort is judged again, with what they read as:
//   - a Read of a picture file that was there before the loop began (a design the person pointed it at, a photo they pasted
//     earlier): not one the agent made itself in this loop, a screenshot or a frame it rendered, which is not a reference;
//   - a message with images the person types into the running turn.
// Either way the images are read first (a request to the image backend; a group read before is answered from the readings kept),
// and the re-decision goes out the moment the reading is in, for the next step (features/midturn-effort.ts
// `judgeAgainWithReference`). Its answer is taken as any re-decision's: before the next step goes out, by the same thresholds,
// debounce, floor and lock. Whatever goes wrong with the reading, the re-decision is asked without it.
//
// The switch is `image-routing` (off by default: the images leave the machine), and the re-decision is the mid-turn feature's,
// so it needs `midturn-effort` on too. With the first off, nothing here does anything.

import type { EngineInterface, HttpInit, On } from 'claude-code'
import { errorText, type BackendIo } from '../decision/backend.ts'
import { keepNewest } from '../decision/keep-newest.ts'
import type { ReferenceReadings } from '../core/complexity.ts'
import type { ImageFilesIo } from '../core/image-files.ts'
import { startedBefore } from '../core/loop-start.ts'
import { MAIN, update, type Cell } from '../core/plans.ts'
import { isPersonsMessage } from '../core/prompts.ts'
import { report, type NodeFailure, type ReportIo } from '../core/report.ts'
import type { Ctx } from '../core/setup.ts'
import { isOn, masterOn } from '../core/switches.ts'
import { newWorkFile } from '../core/work-files.ts'
import { type Block, hasImage, IMAGE_ROUTING_SWITCH, pastedOf, readReference, type ReadIo } from './image-routing.ts'
import { askedFor, judgeAgainWithReference, type LaunchIo, type MidturnRecord } from './midturn-effort.ts'
import { UNRESOLVED_SWITCH } from './unresolved.ts'

const LOOPS = { plugin: 'dispatch-pilot', key: 'loops' } as const
const MAIN_STEP = { plugin: 'dispatch-pilot', key: 'mainStep' } as const
const READINGS = { plugin: 'dispatch-pilot', key: 'referenceReadings' } as const
const BOARD = { plugin: 'dispatch-pilot', key: 'board' } as const
const DECISIONS = { plugin: 'dispatch-pilot', key: 'decisionLog' } as const
const PPLX_RATE = { plugin: 'dispatch-pilot', key: 'pplxRate' } as const
const TURNS = { plugin: 'dispatch-pilot', key: 'turns' } as const
const MIDTURN = { plugin: 'dispatch-pilot', key: 'midturn' } as const
const FAILURES = { plugin: 'dispatch-pilot', key: 'escalation', id: MAIN } as const
const LOCK = { plugin: 'dispatch-pilot', key: 'lock' } as const
const COUNT = { plugin: 'dispatch-pilot', key: 'unresolved' } as const

/**
 * The messages with images typed into a running turn, by their words, with the turn they were typed into (module level: the
 * message's row comes in `session.append` a moment after `prompt.submit`; a hot reload in between loses the reading of that one
 * message). One the engine refuses beneath is taken back out; the most recent few are kept.
 */
const typedIn = new Map<string, string>()
const MOST_TYPED = 8

export function registerReferenceMidturn(on: On, ctx: Ctx): void {
  /** Whether images met now are to be read: the feature is on and there is an image backend. */
  const reading = () => masterOn() && isOn(IMAGE_ROUTING_SWITCH) && ctx.images !== null

  // A Read of a picture. By the time the call returns, the mid-turn feature (beneath) has recorded it in the turn's steps.
  on('tool.call', { tool: 'Read' }, async ($, e, next) => {
    const result = await next(e)
    // The main agent's own calls only, as the mid-turn feature's: its dispatched agents' are theirs.
    if (e.agentId !== undefined || next.origin.plugin !== 'engine' || !reading() || result.deny !== undefined || result.isError === true) return result
    try {
      const read = result.result as { type?: unknown } | undefined
      const path: unknown = e.file_path
      if (read?.type !== 'image' || typeof path !== 'string') return result
      const [started, modified] = await Promise.all([$.state.get({ ...LOOPS, id: MAIN }), $.fs.stat(path).catch(() => null)])
      // Made in this loop (or no way to tell when the loop began): the agent's own picture, not a reference.
      if (modified === null || started.value === undefined || !startedBefore(modified.mtimeMs, started.value.startedAt)) return result
      await judgeAgainWithReference(launchIoOf($), ctx, () => readReference(readIoOf($), ctx, [{ path }]), '读到参考图')
    } catch (error) {
      $.ui.log(`reference images: ${errorText(error)}`, { to: 'debug' })
    }
    return result
  })

  // A message with images typed while a turn runs: `prompt.submit` says so (and what the turn is), its row, which has the images,
  // comes a moment after.
  on('prompt.submit', { text: /(?:)/ }, async (_$, e, next) => {
    const typed = e.turnId !== undefined && isPersonsMessage(e) && hasImage(e.attachments) && reading()
    if (typed) {
      typedIn.delete(e.text.trim())
      typedIn.set(e.text.trim(), e.turnId as string)
      keepNewest(typedIn, MOST_TYPED)
    }
    const result = await next(e)
    if (typed && result.drop !== undefined) typedIn.delete(e.text.trim())
    return result
  })

  on('session.append', { door: /^(?:prompt|queue)$/ }, async ($, e, next) => {
    const result = await next(e)
    if (e.agentId !== undefined || e.message.type !== 'user' || typedIn.size === 0 || !reading()) return result
    try {
      const row = pastedOf(e.message.content as Block[])
      const turnId = row === null ? undefined : typedIn.get(row.text)
      if (row === null || turnId === undefined) return result
      typedIn.delete(row.text)
      // The turn it was typed into must still be the one running.
      const step = (await $.state.get(MAIN_STEP)).value ?? null
      if (step === null || step.turnId !== turnId || row.sources.length === 0) return result
      await judgeAgainWithReference(launchIoOf($), ctx, () => readReference(readIoOf($), ctx, row.sources), '轮中贴了参考图')
    } catch (error) {
      $.ui.log(`reference images: ${errorText(error)}`, { to: 'debug' })
    }
    return result
  })
}

/** What a request to the decision model needs of the engine, as closures (`$` may not cross a file, so this file builds its own). */
function backendOf($: EngineInterface): BackendIo {
  return {
    fetch: (url: string, init: HttpInit) => $.http.fetch(url, init),
    sleep: (ms: number, signal: AbortSignal) => $.clock.sleep(ms, { signal }),
    pace: { now: () => $.clock.now(), sentAt: { get: () => $.state.get(PPLX_RATE), set: (value, options) => $.state.set(PPLX_RATE, value, options) } },
  }
}

/** What a reading of the pictures needs of the engine (features/image-routing.ts `ReadIo`). */
function readIoOf($: EngineInterface): ReadIo {
  const files: ImageFilesIo = {
    run: (argv, init) => $.process.run(argv, init),
    readBytes: async (path) => (await $.fs.read(path, { as: 'bytes' })).base64,
    newFile: (extension) => newWorkFile({ run: (argv) => $.process.run(argv), tmpdir: () => $.env.get('TMPDIR'), sessionId: () => $.session.id() }, extension),
  }
  const reporting: ReportIo = {
    board: { get: () => $.state.get(BOARD), set: (value, options) => $.state.set(BOARD, value, options) },
    decisions: { get: () => $.state.get(DECISIONS), set: (value, options) => $.state.set(DECISIONS, value, options) },
    debug: (line) => $.ui.log(line, { to: 'debug' }),
    now: () => $.clock.now(),
    toast: (text) => $.ui.toast(text),
  }
  return {
    backend: backendOf($),
    files,
    store: { get: () => $.state.get(READINGS), set: (value: ReferenceReadings, options) => $.state.set(READINGS, value, options) },
    now: () => $.clock.now(),
    debug: (line) => $.ui.log(line, { to: 'debug' }),
    note: (failure: NodeFailure) => report(reporting, { decision: { feature: IMAGE_ROUTING_SWITCH, agent: 'main', aside: true, failure } }),
  }
}

/** What a re-decision needs of the engine (features/midturn-effort.ts `LaunchIo`). */
function launchIoOf($: EngineInterface): LaunchIo {
  return {
    backend: backendOf($),
    now: () => $.clock.now(),
    mainStep: async () => (await $.state.get(MAIN_STEP)).value ?? null,
    state: async (key) => {
      const [{ value: turn }, { value: record }, { value: lock = null }, { value: failures }, { value: held }] = await Promise.all([
        $.state.get({ ...TURNS, id: key }),
        $.state.get({ ...MIDTURN, id: key }),
        $.state.get(LOCK),
        $.state.get(FAILURES),
        isOn(UNRESOLVED_SWITCH) ? $.state.get(COUNT) : Promise.resolve({ value: undefined }),
      ])
      return { turn, record, lock, failures, held }
    },
    asked: async (key, upcoming) => {
      const ref = { ...MIDTURN, id: key }
      const cell: Cell<MidturnRecord> = { get: () => $.state.get(ref), set: (value, options) => $.state.set(ref, value, options) }
      await update(cell, (r) => askedFor(r, upcoming))
    },
    debug: (line) => $.ui.log(line, { to: 'debug' }),
  }
}

files.hooks/features/unresolved.ts:
// Feature: the unresolved count and the problem summary (#39, #40; GLOSSARY 未解决次数,
// 问题摘要). Each of the person's messages is asked, in the effort request, whether it
// says the problem they and the main agent are on is still not solved, is solved, or is
// another one; the answer moves the count (core/unresolved.ts). The question and the
// reading of its answer are in features/main-effort.ts, which owns the effort part of
// the ballot they travel in (one contribution per part); this file owns the switch,
// the count's start-over and the summary.
//
// The summary is a record of the problem for the decision model to read beside the
// conversation. When a turn that the person's own message started ends, a cheap model
// continues it, in the background: the hook does not wait, and a message that comes
// before it is written is decided with the summary as it was (main-effort.ts reads it).
// Writes go one after the other, each continuing what the one before wrote. A write
// that fails (the model errs, times out, answers something that is no summary) or that
// a reload of the mod lost leaves the summary as it was and is told to the decision
// report; one the count's start-over overtook is dropped when it lands.
//
// The count is per session: `/clear` and a new session start it over (`session.end`
// fires for both; `session.start` also fires on a hot reload, which must keep it),
// a compaction keeps it. Switched off, the question is not asked, the count stays as it
// is and no summary is written.

import type { EngineInterface, ModelCompleteResult, On } from 'claude-code'
import { errorText } from '../decision/backend.ts'
import { clipToTokens } from '../decision/context.ts'
import { quoteStart, redactSecrets } from '../decision/redact.ts'
import { readSummary, SUMMARY_MAX_REPLY, SUMMARY_SYSTEM, SUMMARY_TIMEOUT_MS, summaryPrompt, turnTools, type TurnInput } from '../decision/summary.ts'
import { turnKey } from '../core/plans.ts'
import { report, type ReportIo } from '../core/report.ts'
import type { Ctx } from '../core/setup.ts'
import { defineSwitch, isOn } from '../core/switches.ts'
import { clearCount, dropSummary, landSummary, lostSummaries, queueSummary, summaryFailure, summaryFor, type CountCell, type SummaryFailure } from '../core/unresolved.ts'

const COUNT = { plugin: 'dispatch-pilot', key: 'unresolved' } as const
const TURNS = { plugin: 'dispatch-pilot', key: 'turns' } as const
const BOARD = { plugin: 'dispatch-pilot', key: 'board' } as const
const DECISIONS = { plugin: 'dispatch-pilot', key: 'decisionLog' } as const

/** The switch's name: `/dp unresolved on|off`. */
export const UNRESOLVED_SWITCH = 'unresolved'

/** The writes of this load of the mod: after the one before it (they are chained), and the turns they are for. A hot reload empties both. */
let chain: Promise<void> = Promise.resolve()
const running = new Set<string>()
/** The engine refused the summary's model: no more is asked of it until the conversation ends (a reload asks again). */
let refused = false

/** What a write is given when the turn ends: the turn, and what the cheap model is shown of it. */
type Write = { turn: string; subject: string; shown: Omit<TurnInput, 'previous'> }

export function registerUnresolved(on: On, ctx: Ctx): void {
  // Off until the person turns it on (#48, ADR 0006); what they set by hand is in $.store and wins.
  defineSwitch({ name: UNRESOLVED_SWITCH, info: '每条消息判断同一个问题是否仍未解决，数未解决的次数；每轮结束后在后台写问题摘要（默认关）', default: false })

  on('session.end', { reason: /(?:)/ }, async ($, e, next) => {
    refused = false
    try {
      await clearCount(countCell($))
    } catch (error) {
      $.ui.log(`unresolved count not cleared: ${errorText(error)}`, { to: 'debug' })
    }
    return next(e)
  })

  // A reload of the mod loses the writes in flight (the engine drops their calls with the old module): the state still lists them.
  on('session.start', { cwd: /(?:)/ }, async ($, e, next) => {
    const result = await next(e)
    try {
      for (const turn of await lostSummaries(countCell($), running)) await tell($, turn, 'lost', ctx.config.unresolved.summaryModel)
    } catch (error) {
      $.ui.log(`summaries lost to a reload not told: ${errorText(error)}`, { to: 'debug' })
    }
    return result
  })

  // A turn the person's own message started ends: its summary is written, in the background.
  on('turn.complete', { turnId: /(?:)/ }, async ($, e, next) => {
    const result = await next(e)
    // The summary is a paraphrase of the conversation: none is written when the person sends the decision model none (`contextMessages` 0).
    if (e.agentId !== undefined || refused || !isOn(UNRESOLVED_SWITCH) || ctx.backend.configured === false || ctx.config.context.messages <= 0) return result
    try {
      const { value: turn } = await $.state.get({ ...TURNS, id: turnKey(e.turnId, undefined) })
      // Only the person's own message: a hand-back or a task notice that started the turn is no word of theirs.
      if (turn === undefined || !turn.person) return result
      const messages = await $.session.messages().catch(() => [])
      const write: Write = { turn: e.turnId, subject: quoteStart(turn.prompt), shown: { person: turn.prompt, reply: e.answer, tools: turnTools(messages) } }
      await queueSummary(countCell($), e.turnId)
      running.add(e.turnId)
      chain = chain.then(() => writeSummary($, ctx, write)).catch(() => undefined)
    } catch (error) {
      $.ui.log(`summary not queued: ${errorText(error)}`, { to: 'debug' })
    }
    return result
  })
}

function countCell($: EngineInterface): CountCell {
  return { get: () => $.state.get(COUNT), set: (value, options) => $.state.set(COUNT, value, options) }
}

/** The decision report's closures over this hook's `$`. */
function reportIo($: EngineInterface): ReportIo {
  return {
    board: { get: () => $.state.get(BOARD), set: (value, options) => $.state.set(BOARD, value, options) },
    decisions: { get: () => $.state.get(DECISIONS), set: (value, options) => $.state.set(DECISIONS, value, options) },
    debug: (line) => $.ui.log(line, { to: 'debug' }),
    now: () => $.clock.now(),
    toast: (text) => $.ui.toast(text),
  }
}

/** A write that did not make a summary, told to the decision report (the one that was there stays). `turn` only names the write in the debug log. */
async function tell($: EngineInterface, turn: string, failure: SummaryFailure, model: string, subject = ''): Promise<void> {
  $.ui.log(`summary for turn ${turn}: ${failure === 'lost' ? 'lost to a reload' : failure}`, { to: 'debug' })
  await report(reportIo($), { decision: { feature: UNRESOLVED_SWITCH, agent: 'main', aside: true, subject, ...summaryFailure(failure, model) } })
}

/**
 * Continues the summary with one turn, with the cheap model, once the writes before it are done. The summary it
 * continues is read when it starts, so it holds what those wrote. Never throws.
 */
async function writeSummary($: EngineInterface, ctx: Ctx, write: Write): Promise<void> {
  const cell = countCell($)
  const model = ctx.config.unresolved.summaryModel
  try {
    const { wanted, previous } = await summaryFor(cell, write.turn)
    // Cleared since the turn ended (solved, another problem, /clear), or switched off meanwhile: nothing to write.
    if (!wanted || !isOn(UNRESOLVED_SWITCH) || refused) {
      await dropSummary(cell, write.turn)
      return
    }
    let reply: ModelCompleteResult
    try {
      reply = await $.model.complete({ model, system: SUMMARY_SYSTEM, prompt: summaryPrompt({ ...write.shown, previous }), maxTokens: SUMMARY_MAX_REPLY, timeoutMs: SUMMARY_TIMEOUT_MS })
    } catch (error) {
      refused = true
      await dropSummary(cell, write.turn)
      await tell($, write.turn, { reason: 'refused', detail: errorText(error) }, model, write.subject)
      return
    }
    if (!reply.isAnswered) {
      await dropSummary(cell, write.turn)
      await tell($, write.turn, reply.reason === 'api-error' ? { reason: 'api-error', status: reply.status, error: reply.error } : { reason: reply.reason }, model, write.subject)
      return
    }
    const summary = readSummary(reply.text)
    if (summary === null) {
      await dropSummary(cell, write.turn)
      await tell($, write.turn, { reason: 'unfit', text: clipToTokens(redactSecrets(reply.text).replace(/\s+/g, ' ').trim(), 60) }, model, write.subject)
      return
    }
    const kept = await landSummary(cell, write.turn, summary)
    $.ui.log(`summary for turn ${write.turn}: ${kept ? 'written' : 'dropped, it was cleared meanwhile'} (${reply.usage.output_tokens} tokens from ${model})`, { to: 'debug' })
  } catch (error) {
    // The session went away under it, or a bug: either way the session is not held up.
    $.ui.log(`summary for turn ${write.turn} not written: ${errorText(error)}`, { to: 'debug' })
  } finally {
    running.delete(write.turn)
  }
}

files.hooks/features/visual-check.ts:
// Feature: visual_check (#57, ADR 0008). An agent (the main agent, or a dispatched one) hands this tool screenshots and a few
// checks, and the decision model that takes images (Jev; pplx without a TypeSafe key) answers pass, fail or unsure for each, in a
// second or two, where the agent would have had to look at every image itself.
//
// Its switch is `visual-check` (`/dp visual-check off`), on by default. The tool stays registered whatever the switches say,
// with a description that never changes (the tool list is part of the prompt cache); switched off, it says so when called.
//
// A call is a line of stages (`check`), and each later ticket of the images work (#55) has its place in it: the zoomed re-check
// (#59) goes between the first request and the verdicts, the frames of a recording (#60) are read where the images are, the
// quality series (#61) is another kind of comparison, and the report to the board and the log (#58) goes after the verdicts.
// Whatever goes wrong in a stage, the checks it touches end unsure with the reason, and the tool never fails.

import type { EngineInterface, HttpInit, On } from 'claude-code'
import { type Asked, type BackendIo, describeAsked, errorText, type Failure, failureText } from '../decision/backend.ts'
import { imageMegapixelBudget, PPLX_MAX_IMAGES, type Picture } from '../decision/images.ts'
import type { DecisionRequest } from '../decision/system-one.ts'
import { LOOK_IMAGE_LIMITS, limitsFor } from '../decision/image-fit.ts'
import { allUnsure, comparedNames, forgetLoop, isCompared, noteResults, readWholeImage, RECORDING_BARS, wholeImageRequest, type CheckResult, type Comparison, type Streaks } from '../decision/visual-check.ts'
import { locatePlan, readLocated, withBoxes } from '../decision/visual-check-zoom.ts'
import { sameView } from '../decision/zoom.ts'
import { attachmentsOf, type Attachment, zoomReview } from '../core/zoom-review.ts'
import { parseVisualCheckInput, type ShownPlace, visualCheckText, VISUAL_CHECK_INPUT, VISUAL_CHECK_TOOL, VISUAL_CHECK_TOOL_CALLED, visualCheckDescription, type VisualCheckInput } from '../decision/visual-check-tool.ts'
import { FRAME_COUNT, type Frame, framesRequest, isRecording, type Span } from '../decision/visual-check-frames.ts'
import { recordOf } from '../decision/visual-check-record.ts'
import { type ImageFilesIo, loadAll, type LoadedImage } from '../core/image-files.ts'
import { callBudget } from '../core/call-budget.ts'
import { readRecording } from '../core/video-frames.ts'
import { report, type ReportIo } from '../core/report.ts'
import { type CallTrouble, reportCall } from '../core/visual-check-report.ts'
import { newWorkFile } from '../core/work-files.ts'
import type { Ctx } from '../core/setup.ts'
import { defineSwitch, isOn, masterOn } from '../core/switches.ts'
import { type AnswerBlock, imageBlock, load, look } from './visual-check-look.ts'
import { checkSeries, type SeriesDeps } from './visual-check-series.ts'

const PPLX_RATE = { plugin: 'dispatch-pilot', key: 'pplxRate' } as const
const BOARD = { plugin: 'dispatch-pilot', key: 'board' } as const
const DECISIONS = { plugin: 'dispatch-pilot', key: 'decisionLog' } as const

/** The switch's name, in `/dp` and in the decision log. */
const SWITCH = 'visual-check'

/**
 * How long one request with images may take (ADR 0008): a tool call is not held to the 1500 ms Jev has beside a message. The
 * requests of one call share the hook's 10 s, though: a request waits on a `$.clock.sleep`, which counts toward them
 * (core/call-budget.ts), so each is also held to what is left of the call's time.
 */
const REQUEST_MS = 8000

/** What a request that was not sent for want of time failed with: the checks it was for end unsure, with this for the reason. */
const NO_TIME: Failure = { kind: 'timeout', detail: 'no time left in this call (a tool call has about 10 seconds in all)' }

/** A series of quality levels (#61) needs the zoomed re-check of each pair, which needs the boxes only Jev answers: with pplx the call says so and asks nothing. */
const SERIES_NEEDS_JEV =
  'visual_check cannot compare a series of quality levels now: a series is compared pair by pair on enlarged crops (the zoomed re-check), which needs a TypeSafe key, and the decision model that takes images here is pplx. Look at the levels yourself (visual_check with look: true), or compare two of them at a time with compare_to, which with pplx catches only clear differences.'

/** A call that did not run: the agent is told why, and that it can look at the images itself. */
const LOOK_YOURSELF = 'Look at the images yourself.'

/**
 * How many times in a row each check has failed, by agent, in its loop (module level: a hot reload loses it, at the cost of one
 * reminder less).
 */
const streaks: Streaks = new Map()

/** The files and programs one call works with, as closures (a module may not pass `$` across an import). */
function filesOf($: EngineInterface): ImageFilesIo {
  return {
    run: (argv, init) => $.process.run(argv, init),
    readBytes: async (path) => (await $.fs.read(path, { as: 'bytes' })).base64,
    // Derived images go to the session's directory in the mod's temporary directory (core/work-files.ts).
    newFile: (extension) => newWorkFile({ run: (argv) => $.process.run(argv), tmpdir: () => $.env.get('TMPDIR'), sessionId: () => $.session.id() }, extension),
  }
}

export function registerVisualCheck(on: On, ctx: Ctx): void {
  defineSwitch({ name: SWITCH, info: '看图核对：agent 交上截图和检查项，决策模型对每条回答过、不过或没把握', parts: ['checks'] })

  // Registered once every plugin is loaded, under a match-all matcher. Without a decision model that takes images (no TypeSafe
  // and no Perplexity key) the tool would only ever fail, so it is not offered.
  on('session.start', { cwd: /(?:)/ }, async ($, e, next) => {
    const result = await next(e)
    const images = ctx.images
    if (images === null) return result
    try {
      const { tool } = await $.tool.register({
        name: VISUAL_CHECK_TOOL,
        description: visualCheckDescription(images.name),
        inputSchema: VISUAL_CHECK_INPUT,
        isDeferred: false,
      })
      if (tool !== VISUAL_CHECK_TOOL_CALLED) $.ui.log(`visual_check is registered as ${tool}, but the hook answers ${VISUAL_CHECK_TOOL_CALLED}: its calls will fail`, { to: 'debug' })
    } catch (error) {
      $.ui.log(`visual_check was not registered: ${errorText(error)}`, { to: 'debug' })
    }
    return result
  })

  // A loop begins (a turn of the main agent, an agent's run): the count of failed checks starts again. The spec wants it counted
  // for the same agent in the same loop. A dispatched agent's run has a `turn.start` of its own with its `agentId` from 2.1.299 (measured
  // on 2.1.300, and for a run woken by a message, DEVELOPMENT.md 「已实测」); before that an agent had no resumed run, so its one loop
  // began with its first call and nothing needs forgetting. core/loop-start.ts keeps the loops' beginnings, but is not needed here.
  on('turn.start', { turnId: /(?:)/ }, async (_$, e, next) => {
    forgetLoop(streaks, e.agentId ?? 'main')
    return next(e)
  })

  // The model's call: answered here, never passed on. Whatever goes wrong, the answer says so at once.
  on('tool.call', { tool: VISUAL_CHECK_TOOL_CALLED }, async ($, e) => {
    if (!masterOn()) return { result: `Dispatch Pilot is switched off (/dp on turns it back on), so visual_check checked nothing. ${LOOK_YOURSELF}` }
    if (!isOn(SWITCH)) return { result: `visual_check is switched off (/dp ${SWITCH} on turns it back on), so it checked nothing. ${LOOK_YOURSELF}` }
    const parsed = parseVisualCheckInput(e as Record<string, unknown>)
    if (!parsed.ok) return { result: parsed.message }
    const agent = e.agentId ?? 'main'
    const reportTo: ReportIo = {
      board: { get: () => $.state.get(BOARD), set: (value, options) => $.state.set(BOARD, value, options) },
      decisions: { get: () => $.state.get(DECISIONS), set: (value, options) => $.state.set(DECISIONS, value, options) },
      debug: (line) => $.ui.log(line, { to: 'debug' }),
      now: () => $.clock.now(),
      toast: (text) => $.ui.toast(text),
    }
    const files = filesOf($)
    try {
      // Looking at images asks nothing of the decision model.
      if (parsed.input.look) return { result: await look(files, parsed.input.images, parsed.input.span) }
      const images = ctx.images
      if (images === null) return { result: `visual_check has no decision model that takes images (it needs a TypeSafe or a Perplexity key), so it checked nothing. ${LOOK_YOURSELF}` }
      // #61: a series of quality levels is compared pair by pair, by the zoomed re-check, which needs the boxes only Jev answers.
      if (parsed.input.comparison.kind === 'sequence' && images.name !== 'jev') return { result: SERIES_NEEDS_JEV }
      const io: BackendIo = {
        fetch: (url: string, init: HttpInit) => $.http.fetch(url, init),
        sleep: (ms: number, signal: AbortSignal) => $.clock.sleep(ms, { signal }),
        pace: { now: () => $.clock.now(), sentAt: { get: () => $.state.get(PPLX_RATE), set: (value, options) => $.state.set(PPLX_RATE, value, options) } },
      }
      // The requests of this call share the hook's time (core/call-budget.ts).
      const budget = callBudget(() => $.clock.now())
      const ask = (request: DecisionRequest): Promise<Asked> =>
        budget.run(
          REQUEST_MS,
          async (waitMs) => {
            const startedAt = await $.clock.now()
            const asked = await images.backend.ask(io, request, waitMs)
            const ms = (await $.clock.now()) - startedAt
            $.ui.log(`visual_check request [${Object.keys(request.questions).join(', ')}] to ${images.backend.name}: ${describeAsked(asked, ms)}`, { to: 'debug' })
            return asked
          },
          { ok: false, failure: NO_TIME },
        )
      const deps: Deps = { files, ask, backend: images.name, agent, now: () => $.clock.now(), debug: reportTo.debug, report: (record, trouble) => reportCall(reportTo, agent, record, trouble) }
      return { result: parsed.input.comparison.kind === 'sequence' ? await checkSeries(deps, parsed.input) : await check(deps, parsed.input) }
    } catch (error) {
      $.ui.log(`visual_check failed: ${errorText(error)}`, { to: 'debug' })
      // A bug of the mod's own, beside the agent's route: a note on the board, no toast.
      await report(reportTo, { decision: { feature: SWITCH, agent, aside: true, skipped: 'error' } })
      // The whole image goes along when it can be read, so the agent still has it to look at (a recording has no one image).
      const text: AnswerBlock = { type: 'text', text: `visual_check could not run (an error in Dispatch Pilot, written to the debug log). ${LOOK_YOURSELF}` }
      const target = parsed.input.images[0]
      const whole = target === undefined || isRecording(target) ? null : await load(files, target, LOOK_IMAGE_LIMITS)
      return { result: whole?.ok === true ? [text, imageBlock(whole.image)] : [text] }
    }
  })
}

/** What a call needs of the world: files and programs, the decision model that takes images. */
type Deps = SeriesDeps & {
  /** Who calls: 'main', or a dispatched agent's id. */
  agent: string
}

/** One call, from its input to its answer. */
async function check(deps: Deps, input: VisualCheckInput): Promise<AnswerBlock[]> {
  const { comparison, checks } = input
  const target = input.images[0] as string
  const startedAt = await deps.now()
  let trouble: CallTrouble | undefined

  // Stage 1, the images: the screenshot, and what it is compared with. A recording is read into its frames here (#60).
  const subjects = await subjectsOf(deps, comparison, target, checks.length, input.span)
  let results: CheckResult[]
  let attached: Picture | null = subjects.screenshot
  let crops: Attachment[] = []
  let elsewhere: ShownPlace | null = null
  if (!subjects.ok) {
    results = allUnsure(checks, subjects.reason)
    trouble = { kind: 'error' }
    deps.debug(`visual_check could not use its images: ${subjects.reason}`)
  } else if (subjects.kind === 'recording') {
    // The frames of a recording, all in one request, in order of time: only the wording of the checks, or a spec, to judge them by.
    const { request, part } = framesRequest(comparison.kind === 'spec' ? comparison.spec : null, subjects.frames, checks)
    const asked = await deps.ask(request)
    results = asked.ok ? readWholeImage(comparison, part, asked.answers, checks, RECORDING_BARS) : allUnsure(checks, failureText(deps.backend, asked.failure))
    if (!asked.ok) trouble = { kind: 'request', failure: { backend: deps.backend, ...asked.failure } }
  } else {
    // Stage 2, the first request: every check about the whole images, in one request.
    const whole = wholeImageRequest(comparison, { screenshot: subjects.screenshot, references: subjects.references }, checks)
    const { part } = whole
    // With Jev, against an image, the same request also locates the named parts (#59). pplx has no Box question.
    const names = comparedNames(comparison, subjects.references.length)
    const sameViews = subjects.references.map((reference) => sameView(input.sameView, subjects.screenshot, reference))
    const plan = deps.backend === 'jev' && isCompared(comparison) ? locatePlan(names, sameViews, checks) : null
    const asked = await deps.ask(plan === null ? whole.request : withBoxes(whole, plan))
    // Stage 4, the verdicts: of the whole images.
    results = asked.ok ? readWholeImage(comparison, part, asked.answers, checks) : allUnsure(checks, failureText(deps.backend, asked.failure))
    if (!asked.ok) trouble = { kind: 'request', failure: { backend: deps.backend, ...asked.failure } }
    // Stage 3 (#59), the zoomed re-check of the parts the checks name: the crops decide, the whole images only give a fail where it could not be made.
    if (asked.ok && plan !== null) {
      const zoomed = await zoomReview(deps, { candidate: subjects.screenshot, others: subjects.references, names, sameViews }, checks, results, plan, readLocated(plan, asked.answers))
      results = zoomed.results
      ;({ crops, elsewhere } = attachmentsOf(zoomed))
      // A request of the zoomed re-check that failed is a note on the board like the first one (#58).
      if (zoomed.failure !== null) trouble = { kind: 'request', failure: { backend: deps.backend, ...zoomed.failure } }
    }
  }
  // The screenshot goes along for what is unsure, to be looked at.
  if (!results.some((result) => result.verdict === 'unsure')) attached = null
  const repeated = noteResults(streaks, deps.agent, results)
  // Stage 5 (#58): the report to the board and the decision log; a recording is reported like a screenshot, by its path.
  await deps.report(recordOf({ image: target, comparison, backend: deps.backend, results, ms: (await deps.now()) - startedAt }), trouble)
  const text = visualCheckText({ target, against: comparison, results, attached: attached !== null, repeated, recording: isRecording(target), crops: crops.map((crop) => crop.label), elsewhere })
  return [{ type: 'text', text }, ...crops.map((crop) => imageBlock(crop.picture)), ...(attached === null ? [] : [imageBlock(attached)])]
}

/**
 * The images of a call, loaded; or why not, with the screenshot if that one was got (it is then still handed back to look at). A
 * recording (#60) is its frames, in order of time, and there is no screenshot to hand back.
 */
type Subjects =
  | { ok: true; kind: 'still'; screenshot: LoadedImage; references: LoadedImage[] }
  | { ok: true; kind: 'recording'; screenshot: null; frames: Frame[] }
  | { ok: false; reason: string; screenshot: LoadedImage | null }

/** The screenshot and what it is compared with (the references, or the other screenshot; none against a spec), as one request holds them. */
async function subjectsOf(deps: Deps, comparison: Comparison, target: string, questions: number, span: Span): Promise<Subjects> {
  const others = comparison.kind === 'reference' ? comparison.paths : comparison.kind === 'compare_to' ? [comparison.path] : []
  const paths = [target, ...others]
  const compared = others.length > 0
  if (isRecording(target)) {
    if (compared) return { ok: false, screenshot: null, reason: `${target} is a recording, which is checked against a spec or on the wording of the checks alone, not against ${comparison.kind === 'reference' ? 'a reference' : 'another screenshot'}` }
    const read = await readRecording(deps.files, target, span, FRAME_COUNT[deps.backend], limitsFor(deps.backend), imageMegapixelBudget(deps.backend, questions))
    return read.ok ? { ok: true, kind: 'recording', screenshot: null, frames: read.frames } : { ok: false, screenshot: null, reason: read.reason }
  }
  const recording = others.find(isRecording)
  if (recording !== undefined) return { ok: false, screenshot: null, reason: `${recording} is a recording, and only the screenshot to check can be one` }
  if (deps.backend === 'pplx' && paths.length > PPLX_MAX_IMAGES) {
    return { ok: false, screenshot: null, reason: `pplx takes at most ${PPLX_MAX_IMAGES} images in one request, and this call has ${paths.length}` }
  }
  const loaded = await loadAll(deps.files, paths, limitsFor(deps.backend), imageMegapixelBudget(deps.backend, questions))
  if (!loaded.ok) return { ok: false, screenshot: loaded.first, reason: loaded.reason }
  const [screenshot, ...references] = loaded.images
  return screenshot === undefined ? { ok: false, screenshot: null, reason: 'no image was loaded' } : { ok: true, kind: 'still', screenshot, references }
}

files.hooks/features/screenshot-takeover.ts:
// Feature: screenshot takeover (#62, spec #55 「截图接管」, ADR 0008). With the switch on, an image the agent's own loop made does
// not reach the agent: it reads a note in its place (where the image is, how big, and that visual_check checks it, or shows it with
// `look: true`), and the visual_check tool, which reads the file, is where the image goes instead. Two kinds of image are taken:
//
//   - a Read that returns an image file modified since the loop began (core/loop-start.ts): the result is swapped for a Read
//     result in its text form, which the engine records without the `[Image: ...]` text it adds to an image;
//   - an image block in the result of an MCP tool (a screenshot tool): saved as a file in the session's temporary directory
//     (`base64 -D -o`, macOS's flags like the image work's `sips`; `$.fs.write` writes text only) and swapped for the note.
//
// Not taken: an image file that was there before the loop began (a reference image), the images the person pastes (they never
// come through Read), and dispatch-pilot's own tools (`look: true` hands the image back through the tool). The switch is
// `screenshot-takeover`, off until the person turns it on. It acts only where the agent has the means to check the image: the
// visual-check switch is on and an image backend exists. Every image taken is an entry in the log and a count on the agent's row.

import type { EngineInterface, On } from 'claude-code'
import { errorText } from '../decision/backend.ts'
import { extensionOf, formatOf, type Kept, noteAsReadResult, sizeOfImage, swapImages, takeoverNote } from '../decision/screenshot-takeover.ts'
import { isFromLoop } from '../core/loop-start.ts'
import { MAIN } from '../core/plans.ts'
import type { ReportIo } from '../core/report.ts'
import type { Ctx } from '../core/setup.ts'
import { defineSwitch, isOn } from '../core/switches.ts'
import { reportTakeover } from '../core/takeover-report.ts'
import { newWorkFile } from '../core/work-files.ts'

const BOARD = { plugin: 'dispatch-pilot', key: 'board' } as const
const DECISIONS = { plugin: 'dispatch-pilot', key: 'decisionLog' } as const
/** When each loop began (core/loop-start.ts), by `main` or the agentId. */
const LOOPS = { plugin: 'dispatch-pilot', key: 'loops' } as const

/** The switch's name, in `/dp` and in the decision log. */
const SWITCH = 'screenshot-takeover'

/** The switch of the tool the images are sent to: without it the agent could not look at what was kept from it. */
const VISUAL_CHECK_SWITCH = 'visual-check'

/** The tools of this plugin as the model names them: what they return is the agent's to see. */
const OWN_TOOLS = 'mcp__dispatch-pilot__'

/** What Read returns for an image file (claude-code-tools' `BuiltinToolResults.Read`, its `image` form): the bytes the engine would show the model, and the size of the file itself. */
type ReadImage = { type: 'image'; file: { base64: string; type: string; dimensions?: { originalWidth?: number; originalHeight?: number } } }

/** Where the board and the log are written (`report`), as closures over `$`. */
function reportIoOf($: EngineInterface): ReportIo {
  return {
    board: { get: () => $.state.get(BOARD), set: (value, options) => $.state.set(BOARD, value, options) },
    decisions: { get: () => $.state.get(DECISIONS), set: (value, options) => $.state.set(DECISIONS, value, options) },
    debug: (line) => $.ui.log(line, { to: 'debug' }),
    now: () => $.clock.now(),
    toast: (text) => $.ui.toast(text),
  }
}

export function registerScreenshotTakeover(on: On, ctx: Ctx): void {
  defineSwitch({ name: SWITCH, info: '截图接管：agent 本循环里自己生成的图不给它看，换成一句说明，由看图核对去看', default: false })

  /** Whether the takeover acts now: the switch is on (with the whole mod), and the agent has visual_check to send the images to. */
  const acts = (): boolean => isOn(SWITCH) && isOn(VISUAL_CHECK_SWITCH) && ctx.images !== null

  // Read: an image file the loop made. Only the model's own calls (`origin`), not another plugin's `$.tool.call`.
  on('tool.call', { tool: 'Read' }, async ($, e, next) => {
    const result = await next(e)
    if (!acts() || next.origin.plugin !== 'engine' || result.deny !== undefined) return result
    const given = result.result as { type?: unknown } | string | null | undefined
    if (typeof given !== 'object' || given === null || given.type !== 'image') return result
    const read = given as ReadImage
    const agent = e.agentId ?? MAIN
    try {
      // Where no beginning is known, which files are older cannot be told: the image is left as it is.
      const loop = (await $.state.get({ ...LOOPS, id: agent })).value
      if (loop === undefined) return result
      const stat = await $.fs.stat(e.file_path)
      if (!isFromLoop(stat.mtimeMs, loop.startedAt)) return result
      const shown = read.file.dimensions
      const size = shown?.originalWidth !== undefined && shown.originalHeight !== undefined ? { width: shown.originalWidth, height: shown.originalHeight } : sizeOfImage(read.file.base64)
      const kept: Kept = { path: e.file_path, width: size?.width ?? 0, height: size?.height ?? 0, format: formatOf(read.file.type) }
      await reportTakeover(reportIoOf($), agent, [kept])
      // The image goes, and with it what the engine added to it: the `[Image: ...]` text and the reference to its message.
      const { text: _text, ref: _ref, ...rest } = result
      return { ...rest, result: noteAsReadResult(e.file_path, takeoverNote(kept, 'Read returned an image file.')) } as typeof result
    } catch (error) {
      $.ui.log(`screenshot takeover of ${e.file_path} failed, the image goes to the agent: ${errorText(error)}`, { to: 'debug' })
      return result
    }
  })

  // An MCP tool's result with image blocks: each one saved as a file, and swapped for the note. One that cannot be saved stays.
  on('tool.call', { tool: /^mcp__/ }, async ($, e, next) => {
    const result = await next(e)
    if (!acts() || next.origin.plugin !== 'engine' || result.deny !== undefined || ('isError' in result && result.isError === true) || e.tool.startsWith(OWN_TOOLS)) return result
    const agent = e.agentId ?? MAIN
    try {
      const kept: Kept[] = []
      const swapped = await swapImages(result.result, async (image) => {
        try {
          const path = await newWorkFile({ run: (argv) => $.process.run(argv), tmpdir: () => $.env.get('TMPDIR'), sessionId: () => $.session.id() }, extensionOf(image.mediaType))
          const saved = await $.process.run(['base64', '-D', '-o', path], { stdin: image.base64 })
          if (saved.exitCode !== 0) {
            $.ui.log(`screenshot takeover could not save an image of ${e.tool} (base64 ended with ${saved.exitCode}), the image goes to the agent`, { to: 'debug' })
            return null
          }
          const size = sizeOfImage(image.base64)
          const one: Kept = { path, width: size?.width ?? 0, height: size?.height ?? 0, format: formatOf(image.mediaType) }
          kept.push(one)
          return takeoverNote(one, `The tool ${e.tool} returned an image.`)
        } catch (error) {
          $.ui.log(`screenshot takeover could not save an image of ${e.tool}, the image goes to the agent: ${errorText(error)}`, { to: 'debug' })
          return null
        }
      })
      if (swapped.swapped === 0) return result
      await reportTakeover(reportIoOf($), agent, kept)
      const { text: _text, ref: _ref, ...rest } = result
      return { ...rest, result: swapped.result } as typeof result
    } catch (error) {
      $.ui.log(`screenshot takeover of ${e.tool} failed, the images go to the agent: ${errorText(error)}`, { to: 'debug' })
      return result
    }
  })
}

files.hooks/features/skill-profiles.ts:
// Feature: skill profiles (#11). At session start a cheap model writes each
// skill a bilingual profile from its SKILL.md, in the background, once per
// version of the file (core/profiles.ts); the skills feature (features/
// skills.ts) offers a skill by its profile once one is written, by its
// description until then, and find_skill (#12) does the same.
//
// It works on the session's skills as the skills feature reads them at
// session start (`$.state`'s skillCatalog), so it registers outside that
// feature: its session.start goes on once the skills are read. Its switch,
// `skill-profiles`, is registered here; off, none is written, and the skills
// feature and find_skill offer every skill by its description. Nothing is
// written while the skills switch is off or no decision model is set up.
//
// What it does is told to the decision report (core/report.ts, `report` with
// `profiles`; ADR 0004), which writes the debug log lines, keeps `$.state`'s `skillProfiles`
// up to date as the profiles are written and adds the session's entry to the
// decision log. This file shows people nothing itself.

import type { EngineInterface, ModelCompleteResult, On } from 'claude-code'
import { errorText } from '../decision/backend.ts'
import { update, type Cell } from '../core/plans.ts'
import {
  evictions,
  PROFILE_MAX_TOKENS,
  PROFILE_PREFIX,
  PROFILE_SYSTEM,
  PROFILE_TIMEOUT_MS,
  profileKey,
  profilePrompt,
  readProfile,
  storedBytes,
  storedProfile,
  withProfile,
  type StoredProfile,
} from '../core/profiles.ts'
import { report, type ProfileEvent, type ProfilesIo, type ProfilesStop } from '../core/report.ts'
import type { Ctx } from '../core/setup.ts'
import type { CatalogSkill } from '../core/skills.ts'
import { defineSwitch, isOn } from '../core/switches.ts'

const CATALOG = { plugin: 'dispatch-pilot', key: 'skillCatalog' } as const
const BOARD = { plugin: 'dispatch-pilot', key: 'board' } as const
const DECISIONS = { plugin: 'dispatch-pilot', key: 'decisionLog' } as const
const PROFILES_STATE = { plugin: 'dispatch-pilot', key: 'skillProfiles' } as const

/** The skills feature's switch: profiles serve its suggestions. */
const SKILLS = 'skills'
/** The profiles' own switch: written at session start, and offered in the ranking (the skills feature and find_skill read it too). */
const PROFILES = 'skill-profiles'

/** Profiles are being written now (one batch at a time). */
let writing = false

/** How profiles are written: the model, how many at most per session start, the skills never offered (none written for them). */
type ProfileSettings = { model: string; perSession: number; skip: ReadonlySet<string> }

export function registerSkillProfiles(on: On, ctx: Ctx): void {
  defineSwitch({ name: PROFILES, info: '按 skill 画像给 skill 排序：便宜的模型每个 SKILL.md 版本写一次中英文画像（关掉就按描述排序）' })
  const settings: ProfileSettings = { model: ctx.config.skills.profileModel, perSession: ctx.config.skills.profilesPerSession, skip: new Set(ctx.config.skills.neverSuggested) }

  // Once the skills feature (inside this one) has read the session's skills: a
  // line on their profiles, then the ones they lack are written in the background.
  on('session.start', { cwd: /(?:)/ }, async ($, e, next) => {
    const result = await next(e)
    if (!isOn(SKILLS) || !isOn(PROFILES) || ctx.backend.configured === false) return result
    const { value } = await $.state.get(CATALOG)
    if (!value) return result
    const catalog = value.skills
    // A store that cannot be read keeps nothing: every session would write every profile again.
    const offered = catalog.filter((skill) => !settings.skip.has(skill.name))
    if (!(await $.store.keys().then(() => true, () => false))) {
      await report(profilesIo($), { profiles: { event: 'unreadable', model: settings.model, offered: offered.length } })
      return result
    }
    const due = offered.filter((skill) => !skill.profile).length
    await report(profilesIo($), { profiles: { event: 'start', model: settings.model, perSession: settings.perSession, offered: offered.length, due } })
    // In the background: the session goes on, and each profile is used as soon as it is written.
    if (due > 0 && settings.perSession > 0) void writeProfiles($, ctx, catalog, settings).catch(() => undefined)
    return result
  })
}

/**
 * Writes the profiles the catalog lacks, one completion at a time, in the
 * catalog's order (the skills the main agent can load first), at most
 * `perSession`; each is kept in the store and given to the session's catalog
 * at once. Runs in the background from session start: nothing waits for it.
 * Stops for this session when the model is refused or answers with an API
 * error, the store will not keep a profile, or the person switches profiles
 * off; a skill whose reply is not a profile (or is cut short) is skipped.
 * What is left is tried again at the next session start. Then drops the
 * oldest profiles past MAX_PROFILES.
 */
async function writeProfiles($: EngineInterface, ctx: Ctx, catalog: readonly CatalogSkill[], settings: ProfileSettings): Promise<void> {
  if (writing) return
  writing = true
  const io = profilesIo($)
  const tell = (event: ProfileEvent) => report(io, { profiles: event })
  const cell: Cell<{ skills: CatalogSkill[] } | null> = { get: () => $.state.get(CATALOG), set: (value, options) => $.state.set(CATALOG, value, options) }
  const due = catalog.filter((skill) => !skill.profile && typeof skill.profileKey === 'string' && !settings.skip.has(skill.name))
  let written = 0
  // The skills dealt with (written, kept by another session, or failed): what is left of `due` is for a later session start.
  let tried = 0
  let stopped = false
  const stop = async (cause: ProfilesStop) => {
    stopped = true
    await tell({ event: 'stop', cause, left: due.length - tried })
  }
  try {
    for (const skill of due) {
      if (!isOn(SKILLS) || !isOn(PROFILES) || ctx.backend.configured === false) {
        await stop({ reason: 'off' })
        break
      }
      if (written >= settings.perSession) {
        await tell({ event: 'quota', perSession: settings.perSession, left: due.length - tried })
        break
      }
      const markdown = skill.file === null ? null : await $.fs.read(skill.file).catch(() => null)
      const key = profileKey(skill, markdown, settings.model)
      // Another session may have written it meanwhile.
      const kept = storedProfile(await $.store.get(key).catch(() => undefined))
      if (kept !== null) {
        await update(cell, (value) => (value ? { skills: withProfile(value.skills, key, kept) } : null))
        tried++
        await tell({ event: 'found' })
        continue
      }
      const startedAt = await $.clock.now()
      let reply: ModelCompleteResult
      try {
        reply = await $.model.complete({ model: settings.model, system: PROFILE_SYSTEM, prompt: profilePrompt(skill, markdown), maxTokens: PROFILE_MAX_TOKENS, timeoutMs: PROFILE_TIMEOUT_MS })
      } catch (error) {
        await stop({ reason: 'model-refused', model: settings.model, detail: errorText(error) })
        break
      }
      const ms = (await $.clock.now()) - startedAt
      if (!reply.isAnswered) {
        const why = reply.reason === 'api-error' ? `an API error, HTTP ${reply.status ?? 'none'} ${reply.error}` : reply.reason
        if (reply.reason === 'api-error') {
          await stop({ reason: 'api-error', skill: skill.name, why, ms })
          break
        }
        tried++
        await tell({ event: 'failed', skill: skill.name, why, ms })
        continue
      }
      const profile = readProfile(reply.text)
      if (profile === null) {
        tried++
        await tell({ event: 'unfit', skill: skill.name, ms, text: reply.text })
        continue
      }
      const entry: StoredProfile = { name: skill.name, at: await $.clock.now(), profile }
      try {
        await $.store.set(key, entry)
      } catch (error) {
        await stop({ reason: 'store-write', skill: skill.name, detail: errorText(error) })
        break
      }
      await update(cell, (value) => (value ? { skills: withProfile(value.skills, key, profile) } : null))
      written++
      tried++
      await tell({ event: 'written', skill: skill.name, model: settings.model, ms, input: reply.usage.input_tokens, output: reply.usage.output_tokens })
    }
    await dropOldProfiles($, catalog)
    if (!stopped) await tell({ event: 'finish', left: due.length - tried })
  } catch (error) {
    // The session went away under it (its `$` refused), or a bug: either way the session is not held up.
    await stop({ reason: 'error', detail: errorText(error) })
  } finally {
    writing = false
  }
}

/** Past MAX_PROFILES profiles in the store, or MAX_PROFILE_BYTES of them, the oldest written that this session does not use are deleted. */
async function dropOldProfiles($: EngineInterface, catalog: readonly CatalogSkill[]): Promise<void> {
  try {
    const keys = (await $.store.keys()).filter((key) => key.startsWith(PROFILE_PREFIX))
    const entries = await Promise.all(
      keys.map(async (key) => {
        const value = await $.store.get(key).catch(() => null)
        return { key, at: writtenAt(value), bytes: storedBytes(key, value) }
      }),
    )
    const drop = evictions(entries, new Set(catalog.flatMap((skill) => (typeof skill.profileKey === 'string' ? [skill.profileKey] : []))))
    if (drop.length === 0) return
    for (const key of drop) await $.store.delete(key)
    const bytes = entries.reduce((sum, entry) => sum + entry.bytes, 0)
    await report(profilesIo($), { profiles: { event: 'tidied', dropped: drop.length, total: keys.length, kb: Math.round(bytes / 1024) } })
  } catch (error) {
    await report(profilesIo($), { profiles: { event: 'tidy-failed', detail: errorText(error) } })
  }
}

/** What the decision report needs of the session, as closures over `$` (`$` cannot cross an import). */
function profilesIo($: EngineInterface): ProfilesIo {
  return {
    board: { get: () => $.state.get(BOARD), set: (value, options) => $.state.set(BOARD, value, options) },
    decisions: { get: () => $.state.get(DECISIONS), set: (value, options) => $.state.set(DECISIONS, value, options) },
    debug: (line) => $.ui.log(line, { to: 'debug' }),
    profiles: { get: () => $.state.get(PROFILES_STATE), set: (value, options) => $.state.set(PROFILES_STATE, value, options) },
  }
}

/** When a stored profile was written; 0 when the value does not say. */
function writtenAt(value: unknown): number {
  const at = typeof value === 'object' && value !== null ? (value as { at?: unknown }).at : undefined
  return typeof at === 'number' && Number.isFinite(at) ? at : 0
}

files.hooks/features/skills.ts:
// Feature: skills (#10, #11). The main agent no longer reads the full skill
// listing the engine attaches at the start of a session (ADR 0002): a fixed
// note takes its place, saying where the skills went and how to come by one
// (the find_skill tool, while its switch is on). Instead, each time the
// person sends a message, the decision model ranks the skills against it in
// two stages (decision/skills.ts) and the few that fit are suggested beside
// the message. Skills only the person can start are pointed out to the person
// instead (「可试 /x」 on the board), never to the main agent.
//
// The ranking offers a skill by its bilingual profile once one is written
// (features/skill-profiles.ts writes them in the background at session
// start), by its description until then.
//
// Its switch is `skills` (`/dp skills off`, and `/dp off`). Off, nothing is
// suggested and the main agent gets the listing back:
// a listing the engine asks about from then on passes as it is, and one
// already withheld in this conversation (the engine keeps that answer) goes
// beside the next message.
// `skill-profiles` switches the profiles alone (neither written nor offered).
// The find_skill tool (#12) has a switch of its own.

import type { EngineInterface, HttpInit, On } from 'claude-code'
import { type Asked, type BackendIo, describeAsked } from '../decision/backend.ts'
import { quoteStart } from '../decision/redact.ts'
import { modRanker, pickSkills, relevanceBlock, skillOpening, type SkillPick, type SkillPolicy, type SkillRanking } from '../decision/skills.ts'
import type { DecisionRequest } from '../decision/system-one.ts'
import { contribute } from '../core/ballot.ts'
import { commandOf } from '../core/commands.ts'
import { update, type Cell } from '../core/plans.ts'
import { readSessionSkills } from '../core/profiles.ts'
import { isPersonsMessage } from '../core/prompts.ts'
import { report, type ReportIo } from '../core/report.ts'
import type { Ctx } from '../core/setup.ts'
import { describeStages, listingNames, rankingSettings, trimListing, type CatalogSkill } from '../core/skills.ts'
import { defineSwitch, isOn } from '../core/switches.ts'

const SHOWN = { plugin: 'dispatch-pilot', key: 'skillsShown' } as const
const CATALOG = { plugin: 'dispatch-pilot', key: 'skillCatalog' } as const
const LISTING = { plugin: 'dispatch-pilot', key: 'skillListing' } as const
const BOARD = { plugin: 'dispatch-pilot', key: 'board' } as const
const DECISIONS = { plugin: 'dispatch-pilot', key: 'decisionLog' } as const
const PPLX_RATE = { plugin: 'dispatch-pilot', key: 'pplxRate' } as const

/** The feature's switch: the suggestions, and with them the withheld listing. */
const SWITCH = 'skills'
/** The profiles' switch (features/skill-profiles.ts registers it and writes them): off, skills are offered by their descriptions. */
const PROFILES = 'skill-profiles'
/** The find_skill tool's switch (features/find-skill.ts): the note in place of the listing names the tool only while it is on. */
const FIND_SKILL = 'find-skill'

/**
 * The session's skills read afresh, each with its profile when the store
 * holds one, and kept for the session. Null when the session's skills cannot
 * be read.
 */
async function readCatalog($: EngineInterface, model: string): Promise<CatalogSkill[] | null> {
  const found = await readSessionSkills(
    {
      commands: () => $.command.list(),
      listed: async () => (await $.session.usage({ breakdown: 'summary' })).context.breakdown?.skills?.skillFrontmatter ?? [],
      overrides: async (source) => (await $.settings.read({ source })).skillOverrides,
      home: () => $.env.get('HOME'),
      cwd: () => $.session.cwd(),
      exists: (path) => $.fs.exists(path),
      read: (path) => $.fs.read(path),
      list: (path) => $.fs.list(path),
      get: (key) => $.store.get(key),
    },
    model,
  )
  if (found === null) return null
  await $.state.set(CATALOG, { skills: found.skills })
  return found.skills
}

/**
 * The session's skills: as read earlier this session, else read now (and
 * kept for the session); null when the session cannot be read.
 */
async function sessionCatalog($: EngineInterface, model: string): Promise<CatalogSkill[] | null> {
  const { value } = await $.state.get(CATALOG)
  if (value) return value.skills
  return readCatalog($, model)
}

/** One decision request through the person's decision model, its outcome in the debug log as the core logs its own. */
async function askLogged($: EngineInterface, ctx: Ctx, what: string, request: DecisionRequest, timeoutMs: number): Promise<Asked> {
  const io: BackendIo = {
    fetch: (url: string, init: HttpInit) => $.http.fetch(url, init),
    sleep: (ms: number, signal: AbortSignal) => $.clock.sleep(ms, { signal }),
    pace: { now: () => $.clock.now(), sentAt: { get: () => $.state.get(PPLX_RATE), set: (value, options) => $.state.set(PPLX_RATE, value, options) } },
  }
  const startedAt = await $.clock.now()
  const asked = await ctx.backend.ask(io, request, timeoutMs)
  const ms = (await $.clock.now()) - startedAt
  $.ui.log(`${what} [${Object.keys(request.questions).join(', ')}] to ${ctx.backend.name}: ${describeAsked(asked, ms)}`, { to: 'debug' })
  return asked
}

/** The opening of a catalog skill's SKILL.md for the ranking's second stage; null when it has no file or it cannot be read. */
async function openingOf($: EngineInterface, catalog: readonly CatalogSkill[], name: string): Promise<string | null> {
  const file = catalog.find((skill) => skill.name === name)?.file ?? null
  if (file === null) return null
  return skillOpening(await $.fs.read(file))
}

export function registerSkills(on: On, ctx: Ctx): void {
  // On until the person flips it, whichever decision model decides: the switch is defined now, before the session start has settled
  // which one that is (core/setup.ts, `Ctx`), so its default cannot depend on it.
  defineSwitch({ name: SWITCH, info: '给每条消息推荐合适的 skill，完整的 skill 列表不再交给主 agent' })

  /** Skills the main agent keeps in its listing (names as the listing spells them). */
  const alwaysListed = new Set(ctx.config.skills.alwaysListed)
  /** Skills never offered, to the main agent or to the person. */
  const neverSuggested = new Set(ctx.config.skills.neverSuggested)
  /** What a message is suggested (read where it is used: the decision model that decides is settled at the session start). */
  const policy = (): SkillPolicy => ctx.config.skills.suggest
  /** How the skills are ranked: by the mod's ranker (`modRanker`, built for each message), as find_skill (#12) ranks them too. */
  const ranking = rankingSettings(ctx)
  /** The model whose profiles the skills are offered by (#11): the store keys them by it. */
  const profileModel = ctx.config.skills.profileModel
  /**
   * Whether the feature is at work now: its switch (and the master switch)
   * on, and a decision model set up to suggest (without one, withholding the
   * listing would only take the skills away). Asked where it acts, never at
   * register: the person's switches are loaded at session start.
   */
  const active = () => isOn(SWITCH) && ctx.backend.configured !== false
  /**
   * Whether the listing is withheld for this catalog: only while some skill
   * in it could be suggested (one the main agent can load, not in
   * skillsNeverSuggested). Withheld, the listing comes back only as
   * suggestions; with none to make, it stays.
   */
  const withholds = (catalog: readonly CatalogSkill[]) => catalog.some((skill) => skill.by === 'model' && !neverSuggested.has(skill.name))

  // Every plugin loaded (after the others' session.start, so their commands
  // are listed): the session's skills, read afresh, and a line saying what
  // came of it. The profiles they lack are written by features/skill-profiles.ts,
  // outside this feature, once this is done.
  on('session.start', { cwd: /(?:)/ }, async ($, e, next) => {
    const result = await next(e)
    if (!isOn(SWITCH)) return result
    if (!active()) {
      $.ui.log('skills: no decision model is set up, so the main agent keeps the skill listing and nothing is suggested', { to: 'debug' })
      return result
    }
    await $.state.set(CATALOG, null)
    const catalog = await readCatalog($, profileModel)
    if (catalog === null) {
      $.ui.log("skills: the session's skills could not be read, so the main agent keeps the skill listing", { to: 'debug' })
      return result
    }
    const persons = catalog.filter((skill) => skill.by === 'person').map((skill) => `/${skill.name}`)
    const models = catalog.length - persons.length
    const only = persons.length > 0 ? `, ${persons.length} only you can start (${persons.join(' ')})` : ''
    const listing = withholds(catalog) ? 'the listing is withheld from the main agent' : 'the main agent keeps the skill listing, since no skill in it could be suggested'
    $.ui.log(`skills: ${models} the main agent can load${only}; ${listing}`, { to: 'debug' })
    return result
  })

  // The engine's skill listing, as each request of a loop carries it (the
  // engine keeps the answer for the conversation). The main agent's gives way to
  // a fixed note on how to come by a skill, after the skills always listed.
  // A dispatched agent's (and a workflow agent's) reaches it untouched.
  on('prompt.attachment', { type: 'skill_listing' }, async ($, e, next) => {
    if (e.agentId !== undefined) return next(e)
    // Skills that cannot be suggested stay listed: no decision model, no catalog, or none in it to suggest.
    const catalog = active() ? await sessionCatalog($, profileModel) : null
    if (catalog === null || !withholds(catalog)) {
      await $.state.set(LISTING, { answered: 'passed', text: '' })
      return next(e)
    }
    const kept = trimListing(e.text, alwaysListed)
    const keptNames = kept === null ? 'none' : listingNames(kept).join(', ')
    // Picked as the engine asks, by the switch as it stands: the engine keeps the answer for the
    // conversation, so a later `/dp find-skill on|off` shows from the next one (DEVELOPMENT.md, 它做什么).
    const findSkill = isOn(FIND_SKILL)
    const hint = findSkill ? LISTING_HINT : LISTING_HINT_WITHOUT_FIND_SKILL
    const noted = findSkill ? 'the note names find_skill' : 'the note leaves find_skill out (switched off)'
    $.ui.log(`withheld the skill listing from the main agent (${listingNames(e.text).length} skills, ${e.text.length} characters); kept ${keptNames}; ${noted}`, { to: 'debug' })
    await $.state.set(LISTING, { answered: 'withheld', text: e.text })
    return { text: kept === null ? hint : `${kept}\n\n${hint}` }
  })

  // The person's message: the skills question goes into its ballot, beside
  // the effort question (one decision request, sent by the core).
  on('prompt.submit', { text: /(?:)/ }, async ($, e, next) => {
    if (!isPersonsMessage(e)) return next(e)
    if (!active()) {
      // Switched off after the listing was withheld: the engine keeps its answer for the conversation
      // (a $.ui.invalidate does not bring it back), so the listing goes beside this message, once.
      const { value: listing = null } = await $.state.get(LISTING)
      if (listing?.answered !== 'withheld') return next(e)
      await $.state.set(LISTING, { answered: 'restored', text: listing.text })
      $.ui.log(`skills is off: the skill listing withheld earlier goes to the main agent with ${quoteStart(e.text)}`, { to: 'debug' })
      const result = await next({ ...e, context: [...(e.context ?? []), restoredListing(listing.text)] })
      // Refused beneath: the model never read it.
      if (result.drop !== undefined) await $.state.set(LISTING, listing)
      return result
    }
    // A command turn: the person has picked the work already (#19).
    if (commandOf(e.text) !== null) return next(e)
    const known = await sessionCatalog($, profileModel)
    // Profiles switched off: every skill is offered by its description.
    const catalog = known?.filter((skill) => !neverSuggested.has(skill.name)).map((skill) => (isOn(PROFILES) ? skill : { ...skill, profile: null })) ?? null
    if (catalog === null) return next(e)
    const ranker = modRanker(
      {
        ask: (request, timeoutMs) => askLogged($, ctx, 'second skills request', request, timeoutMs),
        opening: (option) => openingOf($, catalog, option.name),
      },
      ranking,
    )
    const part = ranker.part(catalog)
    if (part === null) return next(e)
    const shown: Cell<string[]> = { get: () => $.state.get(SHOWN), set: (value, options) => $.state.set(SHOWN, value, options) }
    /** The skills this message describes for the first time. */
    let described: string[] = []
    // Both requests share the message's wait: the second gets what the first left of timeoutMs.
    const startedAt = await $.clock.now()

    contribute(e.text, {
      ...part,
      settle: async (outcome) => {
        const io: ReportIo = {
          board: { get: () => $.state.get(BOARD), set: (value, options) => $.state.set(BOARD, value, options) },
          decisions: { get: () => $.state.get(DECISIONS), set: (value, options) => $.state.set(DECISIONS, value, options) },
          debug: (line) => $.ui.log(line, { to: 'debug' }),
          now: () => $.clock.now(),
          toast: (text) => $.ui.toast(text),
        }
        // Beside the main agent's own decision for the message: in the log, not on its node.
        const about = { feature: SWITCH, agent: 'main', aside: true as const, forTurn: e.turnId === undefined ? ('next' as const) : ('current' as const), subject: quoteStart(e.text) }
        // What the message's requests were given (longer when its effort request is long), less what the first took.
        const left = (outcome.ok ? outcome.waitMs : ctx.config.timeoutMs) - ((await $.clock.now()) - startedAt)
        // No answer (the main-effort decision says why) or none about the skills: nothing suggested.
        const ranked = outcome.ok ? await ranker.rank(outcome.answers, catalog, { state: outcome.state, timeoutMs: left }) : null
        if (ranked === null) {
          if (outcome.ok) $.ui.log(`skills for ${quoteStart(e.text)}: no answer about the skills`, { to: 'debug' })
          await report(io, { decision: { ...about, skipped: 'unanswered' as const } })
          return
        }
        if (ranked.failed !== undefined) {
          $.ui.log(`skills for ${quoteStart(e.text)}: not rated, the second request failed (${ranked.failed.kind}: ${ranked.failed.detail})`, { to: 'debug' })
          await report(io, { decision: { ...about, failure: { backend: ctx.backend.name, ...ranked.failed } } })
          return
        }
        const { suggest, hint } = pickSkills(ranked, catalog, policy())
        await report(io, {
          decision: {
            ...about,
            outcome: describePicks(suggest, hint),
            reason: describeRanking(ranked, policy()),
            skills: { suggest: suggest.map(({ name, relevance }) => ({ name, relevance })), try: hint.map(({ name, relevance }) => ({ name, relevance })) },
          },
        })
        const { value: before = [] } = await $.state.get(SHOWN)
        const known = new Set([...before, ...alwaysListed])
        const block = relevanceBlock(suggest, known)
        described = suggest.map((skill) => skill.name).filter((name) => !known.has(name))
        if (described.length > 0) await update(shown, (list) => [...new Set([...(list ?? []), ...described])])
        return block === null ? [] : [block]
      },
    })

    const result = await next(e)
    // Refused beneath: the model never read those descriptions.
    if (result.drop !== undefined && described.length > 0) {
      const withdrawn = new Set(described)
      await update(shown, (list) => (list ?? []).filter((name) => !withdrawn.has(name)))
    }
    return result
  })

  // A new conversation (/clear) or a compacted one no longer holds what was
  // given beside earlier messages (descriptions, a restored listing): give it
  // again. A new conversation also reads the skills afresh, and the engine
  // asks about its listing anew.
  on('session.end', { reason: /(?:)/ }, async ($, e, next) => {
    await $.state.set(SHOWN, [])
    await $.state.set(CATALOG, null)
    await $.state.set(LISTING, null)
    return next(e)
  })
  on('session.compact', { trigger: /(?:)/ }, async ($, e, next) => {
    const result = await next(e)
    if (e.agentId !== undefined || result.skip !== undefined) return result
    await $.state.set(SHOWN, [])
    const { value: listing = null } = await $.state.get(LISTING)
    if (listing?.answered === 'restored') await $.state.set(LISTING, { answered: 'withheld', text: listing.text })
    return result
  })
}

/**
 * What the main agent reads in place of the skill listing: where the skills
 * went and how to come by one. Fixed text, naming no skill: the engine keeps
 * the answer for the conversation, and it is part of the prompt cache. It
 * names find_skill in full and says it may need ToolSearch: the tool is
 * deferred, so until loaded the main agent sees only its name. (A wording that
 * also said when to look, in find_skill's own words, did no better on a real
 * engine; DEVELOPMENT.md, 已实测的引擎行为.)
 */
const LISTING_HINT =
  "Dispatch Pilot leaves most of this session's skills out of the skill listing. The ones that fit a message may be suggested beside it. For any other skill, call the find_skill tool (mcp__dispatch-pilot__find_skill; load it with ToolSearch first if it is deferred) with a few words on the work, then load a skill it returns with the Skill tool by its exact name."
/** The same with find_skill switched off: it does not send the main agent to a tool that would only say it is off. */
const LISTING_HINT_WITHOUT_FIND_SKILL =
  "Dispatch Pilot leaves most of this session's skills out of the skill listing. The ones that fit a message may be suggested beside it; load one, or any skill you know, with the Skill tool by its exact name."

/** The listing the feature withheld, as it goes beside a message once the feature is switched off. */
function restoredListing(text: string): string {
  return `Dispatch Pilot's skill suggestions are switched off, so here is the skill listing it had left out:\n\n${text}`
}

/** Why: what each stage of the ranking said (`describeStages`), and the bar a skill had to reach. */
function describeRanking(ranking: SkillRanking, policy: SkillPolicy): string {
  return `${describeStages(ranking)}；相关度 ${policy.minRelevance.toFixed(2)} 起推荐，最多 ${policy.max} 个`
}

/** What the message got: the skills suggested, then those for the person to start. */
function describePicks(suggest: readonly SkillPick[], hint: readonly SkillPick[]): string {
  const suggested = suggest.length > 0 ? `推荐 ${suggest.map((skill) => skill.name).join('、')}` : '没有推荐 skill'
  return hint.length > 0 ? `${suggested}；可试 ${hint.map((skill) => `/${skill.name}`).join(' ')}` : suggested
}

