// The screens' visual language (spec #22 「视觉语言」, prototype D's kit): the
// palette, the cell-width helpers the fixed columns need, and the small parts
// every screen draws (a model chip, an effort tag, a state glyph, a Raster's
// cells). Pure: the element table comes in as `t` (`$.ui.resolve(e)` in the
// hook's file); nothing here reads the board.
//
// Colours: one accent (the theme's `claude`), the theme's semantic keys for
// state, so light and dark terminals both read; hex only where a colour must
// be a fixed one: the effort ramp (the meter's tick borrows two of its stops),
// the four model chips (a light tint with dark ink on it, its own background),
// the four model inks (mid tones that hold on either background), and the
// greys of a Raster (the ribbon's track, what a finished bar softens toward).

import type { Elements, RenderNode } from 'claude-code'
import { EFFORTS, type Effort } from '../decision/effort.ts'
import type { AgentState, Model } from '../core/report.ts'
import type { StatusTone } from './view.ts'

/** The terminal's element table: what the Raster parts draw with. */
export type T = Elements['terminal']
/**
 * The elements every surface has: all that the text parts need. The terminal's and the other surfaces' tables both
 * fit it, so one drawing serves them all; only a Raster (the terminal's alone, `Raster` below) is left out of it.
 */
export type TT = Pick<T, 'Box' | 'Text' | 'Button'>
/** The terminal's Raster constructor: given to a drawing on the terminal, absent on every other surface (a Raster is refused there). */
export type Raster = T['Raster']

export const ACCENT = 'claude'
export const OK = 'success'
export const BAD = 'error'
export const WARN = 'warning'
export const MUTED = 'inactive'
/** A skill for the person to try (「可试 /x」). */
export const SKILL = 'suggestion'

/** An agent's status cell, by its tone (the band's row, the card's state). */
export const STATUS_COLOR: Record<StatusTone, string> = { run: ACCENT, done: MUTED, fail: BAD, warn: WARN, muted: MUTED }

/** The effort ramp, cool to hot: low to max. */
export const EFFORT_COLOR: Record<Effort, string> = {
  low: '#4A90D9',
  medium: '#2BAE9C',
  high: '#D1A21F',
  xhigh: '#E8742A',
  max: '#D93B4B',
}

/** The model chips: a light tint each, dark ink on it. */
export const MODEL_BG: Record<Model, string> = {
  haiku: '#8AD7E1',
  sonnet: '#A9B4F5',
  opus: '#D5A5F0',
  fable: '#F2C078',
}
const MODEL_INK = '#14171C'
/** A model's name written as text, in its chip's hue: deep enough for a light terminal, light enough for a dark one (contrast 3.7 or more on white and on #1E1E1E). */
export const MODEL_FG: Record<Model, string> = {
  haiku: '#1F8A9A',
  sonnet: '#5B6FD6',
  opus: '#A05BC8',
  fable: '#B07A1F',
}

/** A running agent's glyph, one frame per tick. */
export const SPIN = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏']

/** How many nodes a drawn tree has: Desktop refuses one of 2000 (the engine's own limit is 20000, and a test's mount does not check it). */
export function nodeCount(node: RenderNode): number {
  if (typeof node === 'string') return 1
  return 1 + ('children' in node && node.children !== undefined ? node.children.reduce((sum, child) => sum + nodeCount(child), 0) : 0)
}

/**
 * Whether a drawn tree shows anything: some text, or a Button's label, anywhere in it. The engine's own drawing
 * (`type: 'engine'`) cannot be looked into: `engine` says whether it shows something (the footer's, its modes).
 */
export function showsText(node: RenderNode, engine: boolean): boolean {
  if (typeof node === 'string') return node.trim() !== ''
  if (node.type === 'engine') return engine
  if (node.type === 'Button') return node.props.label !== ''
  return 'children' in node && node.children !== undefined && node.children.some((child: RenderNode) => showsText(child, engine))
}

// ---- cell widths --------------------------------------------------------------

/** The cells one code point takes on the terminal: CJK (extension B and later too), emoji and fullwidth two, combining marks none. */
function cells(cp: number): number {
  if (cp < 0x20) return 0
  if (cp < 0x300) return 1
  if (cp <= 0x36f) return 0
  if (cp === 0x200b || cp === 0x200d || (cp >= 0xfe00 && cp <= 0xfe0f)) return 0
  if (
    (cp >= 0x1100 && cp <= 0x115f) ||
    (cp >= 0x2e80 && cp <= 0x303e) ||
    (cp >= 0x3041 && cp <= 0x33ff) ||
    (cp >= 0x3400 && cp <= 0x4dbf) ||
    (cp >= 0x4e00 && cp <= 0x9fff) ||
    (cp >= 0xa000 && cp <= 0xa4cf) ||
    (cp >= 0xac00 && cp <= 0xd7a3) ||
    (cp >= 0xf900 && cp <= 0xfaff) ||
    (cp >= 0xfe30 && cp <= 0xfe6f) ||
    (cp >= 0xff00 && cp <= 0xff60) ||
    (cp >= 0xffe0 && cp <= 0xffe6) ||
    (cp >= 0x1f300 && cp <= 0x1f64f) ||
    (cp >= 0x1f900 && cp <= 0x1f9ff) ||
    (cp >= 0x20000 && cp <= 0x3fffd)
  )
    return 2
  return 1
}

/** The cells a text takes on the terminal. */
export function width(text: string): number {
  let n = 0
  for (const ch of text) n += cells(ch.codePointAt(0) ?? 0)
  return n
}

/** The text cut to at most `w` cells, ending in `…` when something was cut. */
export function fit(text: string, w: number): string {
  if (w <= 0) return ''
  if (width(text) <= w) return text
  let out = ''
  let used = 0
  for (const ch of text) {
    const c = cells(ch.codePointAt(0) ?? 0)
    if (used + c > w - 1) break
    out += ch
    used += c
  }
  return `${out}…`
}

/** The text fitted to `w` cells and padded on the right to fill them. */
function padRight(text: string, w: number): string {
  const cut = fit(text, w)
  return cut + ' '.repeat(Math.max(0, w - width(cut)))
}

/** The text fitted to `w` cells and padded on the left. */
export function padLeft(text: string, w: number): string {
  const cut = fit(text, w)
  return ' '.repeat(Math.max(0, w - width(cut))) + cut
}

/** Seconds as `m:ss`. */
export function mmss(seconds: number): string {
  const s = Math.max(0, Math.floor(seconds))
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`
}

/** A probability or confidence in two digits: `.59`, `1.0`. */
export function pct(p: number): string {
  return p < 0.005 ? '.00' : p >= 0.995 ? '1.0' : p.toFixed(2).slice(1)
}

/** `pct` of a rule step's field, which is typed loosely: `?` where it is not a number. */
export function pctText(value: unknown): string {
  return typeof value === 'number' ? pct(value) : '?'
}

// ---- parts ------------------------------------------------------------------

/** A model chip, 8 cells: the model's tint with dark ink; not routed, the engine's model in amber with a star. */
export function chip(t: TT, model: Model | undefined, routed: boolean) {
  const { Text } = t
  if (model === undefined) return <Text color={MUTED}>{padRight(' —', 8)}</Text>
  if (!routed) return <Text color={WARN} bold>{padRight(` ${model}*`, 8)}</Text>
  return (
    <Text backgroundColor={MODEL_BG[model]} color={MODEL_INK} bold>
      {` ${model.padEnd(6)} `}
    </Text>
  )
}

/** Five pips, as many filled as the level is high, in the level's colour: ▰▰▰▱▱. */
function pips(t: TT, effort: Effort) {
  const { Text } = t
  const n = EFFORTS.indexOf(effort) + 1
  return (
    <Text>
      <Text color={EFFORT_COLOR[effort]}>{'▰'.repeat(n)}</Text>
      <Text color={MUTED}>{'▱'.repeat(5 - n)}</Text>
    </Text>
  )
}

/**
 * The effort as it went out, `w` cells: pips and the level's name in its colour; an integer budget as the engine
 * sent it; none (a model without effort) a dash. Under 6 cells (a narrow band) the pips alone.
 */
export function effortTag(t: TT, effort: Effort | number | undefined, w = 12) {
  const { Text } = t
  const word = w > 5
  if (effort === undefined) return <Text color={MUTED}>{padRight(word ? '▱▱▱▱▱ —' : '▱▱▱▱▱', w)}</Text>
  if (typeof effort === 'number') return <Text color={MUTED}>{padRight(word ? `▱▱▱▱▱ ${effort}` : '▱▱▱▱▱', w)}</Text>
  return (
    <Text>
      {pips(t, effort)}
      {word ? (
        <Text color={EFFORT_COLOR[effort]} bold>
          {padRight(` ${effort}`, w - 5)}
        </Text>
      ) : null}
    </Text>
  )
}

/** `opus·xhigh`: the model in its tint, the effort in the colour of `level` (grey when it is none); both amber when not routed. `bold` as the band draws it, not the footer. */
export function readout(t: TT, model: Model | undefined, effort: string | number | undefined, level: Effort | undefined, routed: boolean, bold = true) {
  const { Text } = t
  const weight = bold ? { bold } : {}
  return (
    <Text>
      {model === undefined ? null : <Text color={routed ? MODEL_FG[model] : WARN} {...weight}>{model}</Text>}
      {model !== undefined && effort !== undefined ? <Text color={MUTED}>·</Text> : null}
      {effort === undefined ? null : <Text color={!routed ? WARN : level === undefined ? MUTED : EFFORT_COLOR[level]} {...weight}>{String(effort)}</Text>}
    </Text>
  )
}

/** The skills of a decision: those suggested with their relevance, then those for the person to try (「可试 /x」). */
export function skillsText(t: TT, skills: { suggest: readonly { name: string; relevance: number }[]; try: readonly { name: string }[] }) {
  const { Text } = t
  return (
    <Text>
      {skills.suggest.map((skill, i) => (
        <Text>
          {i > 0 ? <Text color={MUTED}>{' · '}</Text> : null}
          {skill.name}
          <Text color={OK}>{` ${pct(skill.relevance)}`}</Text>
        </Text>
      ))}
      {skills.try.length === 0 ? null : <Text color={SKILL} bold>{`${skills.suggest.length > 0 ? '  ' : ''}可试 ${skills.try.map((skill) => `/${skill.name}`).join(' ')}`}</Text>}
    </Text>
  )
}

/** An agent's state: a spinner while it runs (amber when its steps are not routed), ✔ done, ✘ failed, ○ queued. */
export function stateGlyph(t: TT, state: AgentState, frame: number, routed: boolean) {
  const { Text } = t
  if (state === 'running') return <Text color={routed ? ACCENT : WARN} bold>{SPIN[frame % SPIN.length]}</Text>
  if (state === 'done') return <Text color={OK}>✔</Text>
  if (state === 'failed') return <Text color={BAD} bold>✘</Text>
  return <Text color={MUTED}>○</Text>
}

// ---- Raster cells ---------------------------------------------------------------

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

function base64(bytes: readonly number[]): string {
  let out = ''
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i] ?? 0
    const b = bytes[i + 1] ?? 0
    const c = bytes[i + 2] ?? 0
    out += B64[a >> 2]
    out += B64[((a & 3) << 4) | (b >> 4)]
    out += i + 1 < bytes.length ? B64[((b & 15) << 2) | (c >> 6)] : '='
    out += i + 2 < bytes.length ? B64[c & 63] : '='
  }
  return out
}

/** The terminal's own colour, in a Raster cell. */
const DEFAULT = 0x01000000

/** `#rrggbb` as the number a Raster cell takes. */
export function rgb(hex: string): number {
  return parseInt(hex.slice(1), 16)
}

/** One cell of a Raster: its glyph (one width-1 character), foreground, background. */
type RasterCell = [string, number, number]

/** Cells, row by row, as the base64 of little-endian u32 triplets a Raster takes. */
function packCells(cells: readonly RasterCell[]): string {
  const bytes: number[] = []
  const push = (v: number) => bytes.push(v & 255, (v >>> 8) & 255, (v >>> 16) & 255, (v >>> 24) & 255)
  for (const [glyph, fg, bg] of cells) {
    push(glyph.codePointAt(0) ?? 32)
    push(fg)
    push(bg)
  }
  return base64(bytes)
}

/** Two colours mixed, `f` of the way from `a` to `b`. */
function mix(a: number, b: number, f: number): number {
  const ch = (shift: number) => Math.round(((a >> shift) & 255) * (1 - f) + ((b >> shift) & 255) * f)
  return (ch(16) << 16) | (ch(8) << 8) | ch(0)
}

/** A colour pulled toward grey: a finished agent's bar. */
export function soft(hex: string): number {
  return mix(rgb(hex), 0x9aa0a6, 0.55)
}

/** `soft`, as the `#rrggbb` a Text's colour takes: a level not picked. */
export function softColor(hex: string): string {
  return `#${soft(hex).toString(16).padStart(6, '0')}`
}

/** The ribbon's empty track, and the bar of an agent with neither an effort nor a model. */
export const TRACK_HEX = '#8A9099'
const TRACK = rgb(TRACK_HEX)
/** The left eighths, for where a bar ends inside a cell. */
const EIGHTHS = ['', '▏', '▎', '▍', '▌', '▋', '▊', '▉']

/**
 * One agent's time ribbon, `columns` cells over the turn's `span` seconds: a thin track, the bar from `from` to
 * `to` (seconds) in `color`, its end exact to an eighth of a cell; a queued agent (`to` null) a dot where it was
 * spawned. Every agent's ribbon has the same span, so bars that overlap ran side by side.
 */
export function ribbonCells(from: number, to: number | null, span: number, columns: number, color: number): string {
  const scale = columns / Math.max(span, 1)
  const start = Math.max(0, Math.min(columns, from * scale))
  const end = to === null ? null : Math.max(start, Math.min(columns, to * scale))
  const out: RasterCell[] = []
  for (let c = 0; c < columns; c++) {
    if (end === null) {
      out.push(c === Math.min(columns - 1, Math.floor(start)) ? ['·', TRACK, DEFAULT] : ['─', TRACK, DEFAULT])
      continue
    }
    // Every agent that started shows at least one cell of its bar.
    const lo = Math.floor(start)
    const covered = Math.min(c + 1, Math.max(end, lo + 1)) - Math.max(c, start)
    if (covered >= 0.94 || (c === lo && end - start < 1)) out.push(['█', color, DEFAULT])
    else if (covered <= 0.06) out.push(['─', TRACK, DEFAULT])
    else if (c < start) out.push(['▐', color, DEFAULT])
    else out.push([EIGHTHS[Math.max(1, Math.min(7, Math.round(covered * 8)))] ?? '▌', color, DEFAULT])
  }
  return packCells(out)
}

/** The effort ramp's colour at `f` in 0..1, between its five stops. */
function rampAt(f: number): number {
  const stops = EFFORTS.map((level) => rgb(EFFORT_COLOR[level]))
  const x = Math.max(0, Math.min(1, f)) * (stops.length - 1)
  const i = Math.min(stops.length - 2, Math.floor(x))
  return mix(stops[i] ?? 0, stops[i + 1] ?? 0, x - i)
}

/**
 * One 100% stacked bar of the effort probabilities, `columns` cells: a segment per level in its ramp colour (the
 * levels not picked softened), a boundary inside a cell drawn with an eighth block, left colour on right colour.
 */
export function stackCells(probs: Record<Effort, number>, picked: Effort | undefined, columns: number): string {
  const total = EFFORTS.reduce((sum, level) => sum + probs[level], 0) || 1
  const colorOf = (level: Effort) => (level === picked || picked === undefined ? rgb(EFFORT_COLOR[level]) : soft(EFFORT_COLOR[level]))
  const edges: { level: Effort; from: number; to: number }[] = []
  let at = 0
  for (const level of EFFORTS) {
    const w = (probs[level] / total) * columns
    edges.push({ level, from: at, to: at + w })
    at += w
  }
  const out: RasterCell[] = []
  for (let c = 0; c < columns; c++) {
    const here = edges.filter((edge) => edge.to > c + 0.001 && edge.from < c + 0.999).map((edge) => ({ level: edge.level, w: Math.min(edge.to, c + 1) - Math.max(edge.from, c) }))
    const widest = [...here].sort((a, b) => b.w - a.w)[0]
    if (widest === undefined) {
      out.push([' ', DEFAULT, DEFAULT])
      continue
    }
    if (here.length === 1 || widest.w > 0.94) {
      out.push(['█', colorOf(widest.level), DEFAULT])
      continue
    }
    const left = here[0] ?? widest
    const right = here.at(-1) ?? widest
    out.push([EIGHTHS[Math.max(1, Math.min(7, Math.round(left.w * 8)))] ?? '▌', colorOf(left.level), colorOf(right.level)])
  }
  return packCells(out)
}

/** The tick's colours: past the line, short of it. */
const PASSED = rgb(EFFORT_COLOR.medium)
const SHORT = rgb(EFFORT_COLOR.high)

/**
 * A confidence meter, `columns` cells: filled to `conf` along the ramp's cool half, a thin track beyond, and a tick
 * at `threshold` (green when `passed`, amber when not; none when no line was asked).
 */
export function meterCells(conf: number, threshold: number | undefined, passed: boolean | null, columns: number): string {
  const tick = threshold === undefined ? -1 : Math.min(columns - 1, Math.round(threshold * columns))
  const fill = Math.max(0, Math.min(1, conf)) * columns
  const out: RasterCell[] = []
  for (let c = 0; c < columns; c++) {
    const color = rampAt(0.2 + (c / columns) * 0.4)
    if (c === tick) out.push(['┃', passed === true ? PASSED : SHORT, c < fill ? color : DEFAULT])
    else if (c + 1 <= fill) out.push(['█', color, DEFAULT])
    else if (c < fill) out.push(['▌', color, DEFAULT])
    else out.push(['─', TRACK, DEFAULT])
  }
  return packCells(out)
}

files.hooks/board/rationale.ts:
// What the rationale pane shows of the board (spec #22 「依据面板」, GLOSSARY
// 依据面板 / 依据卡片 / 规则推演): the card of the agent picked, with its
// decisions and the rules' working step by step; the decision log grouped by
// turn; the lines at its top (what is switched off, the lock, how the skill
// profiles went).
//
// Pure, like view.ts: the board's data, the switches and the pane's own view
// state come in as data. The rules' working is only worded here, never worked
// out again (ADR 0004): every step is one that `pickEffort`, `judgeMidturn` or a
// forced raise stored with its decision, and whether it took effect is the
// step's own `applied`.
//
// The words are the pane's own (Chinese, GLOSSARY terms); a log entry's
// `reason` and a node's `why` come in the decision report's words (Chinese
// too, #32).

import { isEffort, type Effort } from '../decision/effort.ts'
import { UNRESOLVED_OPTIONS } from '../decision/unresolved.ts'
import { OPTION_WORDS } from '../core/unresolved.ts'
import type { LogEntry, ProfilesState, RuleStep, Tone, UnresolvedRecord } from '../core/report.ts'
import { pctText } from './kit.tsx'
import { agentOf, featureOf, type AgentRow, type ScreenView } from './view.ts'

/** The pane's id: `$.ui.open`, `$.ui.close` and the `ui.render` hook's `requestId`. */
export const PANE_ID = 'dp-rationale'
/** Its tab's title, while another pane is open beside it. */
export const PANE_TITLE = '依据'
/** The body columns it asks for when docked beside a fullscreen transcript. */
export const PANE_COLUMNS = 76

/** The pane's own view state (`$.state` `paneView`): the log's turns the person folded or opened, the failed skills shown. */
export type PaneState = {
  /** A turn the person folded (`open` false) or opened; the others are as `OPEN_TURNS` says. */
  folds: { turn: number; open: boolean }[]
  /** The skills that got no profile are listed. */
  failures: boolean
}

export const NO_PANE_STATE: PaneState = { folds: [], failures: false }

/** The keys that fold a turn of the log, newest turn first: one for each of the 20 turns it keeps, never p, n (paging) or f (the failed skills). */
const FOLD_KEYS = ['a', 'b', 'c', 'd', 'e', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'o', 'q', 'r', 's', 't', 'u', 'v', 'w'] as const
/** The key that lists the skills that got no profile. */
export const FAILURES_KEY = 'f'
/** The key that puts the picked agent's transcript in the main view, and the main conversation back. */
export const VIEW_KEY = 'x'
/** How many of the newest turns are open until the person folds them; older ones are folded. */
const OPEN_TURNS = 2

// ---- the card -------------------------------------------------------------------

/** The agent the card is about, and what the log holds of it. */
export type Card = {
  /** Its row on the band (null before any agent is on the board). */
  row: AgentRow | null
  /** Where it is among the rows (for p / n), and how many there are. */
  index: number
  count: number
  /** The decision its route came from (its node's `decision`). */
  route: LogEntry | undefined
  /** Forced raises of its loop (escalation), oldest first. */
  raises: LogEntry[]
  /** The main agent's mid-turn re-decisions of its turn, oldest first. */
  mids: LogEntry[]
}

/** The card of the agent picked on the band (`selected`); the main agent when none is, or the one picked is no longer on it. */
export function cardOf(view: ScreenView, log: readonly LogEntry[]): Card {
  const picked = view.rows.findIndex((row) => row.selected)
  const index = picked >= 0 ? picked : 0
  const row = view.rows[index] ?? null
  if (row === null) return { row: null, index: 0, count: 0, route: undefined, raises: [], mids: [] }
  const { node } = row
  const route = node.decision === undefined ? undefined : log.find((entry) => entry.n === node.decision)
  // An agent's id is its own across turns; the main agent's entries are those of its node's turn.
  const mine = (entry: LogEntry) => agentOf(entry) === node.id && (node.id !== 'main' || entry.turn === node.turn)
  const raises = log.filter((entry) => mine(entry) && featureOf(entry.feature) === 'escalation' && entry.forced !== undefined)
  const mids = node.id !== 'main' ? [] : log.filter((entry) => mine(entry) && entry.mid !== undefined && entry.forced === undefined && (featureOf(entry.feature) === 'midturn-effort' || featureOf(entry.feature) === 'escalation'))
  return { row, index, count: view.rows.length, route, raises, mids }
}

const percent = (p: number) => `${Math.round(p * 100)}%`

/**
 * What an answer to the unresolved question did to the count, in the card's words: the count (`次数 2 → 3`), what that
 * came to (`次数加一`), the options' probabilities, and the bar each was held to. Written from the record the decision
 * stored with its two bars, never worked out again (ADR 0004).
 */
export function unresolvedWords(record: UnresolvedRecord): { count: string; verdict: string; odds: string; bars: string } {
  const p = record.probs
  const { add, reset } = record.thresholds
  const moved = record.before !== record.count
  const verdict = record.change === 'add' ? '次数加一' : record.change === 'reset' ? (moved ? '次数清零' : '本来就是 0，不用清零') : '次数不变'
  // A reset's option is the one the record says the answer leaned to most: the bar is over half, so no other option can pass it.
  const bars =
    record.change === 'add'
      ? `仍未解决 ${percent(p.still_unresolved)} ≥ 加一门槛 ${percent(add)}`
      : record.change === 'reset'
        ? `${OPTION_WORDS[record.top]} ${percent(p[record.top])} ≥ 清零门槛 ${percent(reset)}`
        : `都没到：仍未解决 < 加一门槛 ${percent(add)}，其余 < 清零门槛 ${percent(reset)}`
  return {
    count: moved ? `次数 ${record.before} → ${record.count}` : `次数 ${record.count}`,
    verdict,
    odds: UNRESOLVED_OPTIONS.map((option) => `${OPTION_WORDS[option]} ${percent(p[option])}`).join(' · '),
    bars,
  }
}

/** The row p (`-1`) or n (`+1`) goes to from the card's, held at either end. */
export function pageTo(card: Card, view: ScreenView, step: -1 | 1): AgentRow | null {
  if (card.row === null) return null
  return view.rows[Math.max(0, Math.min(view.rows.length - 1, card.index + step))] ?? null
}

/** How a step of the rules reads: it decided (`hit`), it passed without effect (`pass`), a floor lifted the level (`lift`), the failures forced a raise (`raise`). */
export type StepMark = 'hit' | 'pass' | 'lift' | 'raise'

/** One step of the rules' working, worded: its mark, the rule's name, what it did. */
type StepLine = { mark: StepMark; head: string; body: string }

const word =(value: unknown) => (value === null || value === undefined ? '—' : String(value))

/** The steps the rules walked, as the card writes them (each from the step's own fields). */
export function stepLines(trace: readonly RuleStep[]): StepLine[] {
  const top = trace.find((step) => step.rule === 'top')
  return trace.map((step) => stepLine(step, top))
}

function stepLine(step: RuleStep, top: RuleStep | undefined): StepLine {
  const on = step.applied
  switch (step.rule) {
    case 'top':
      return { mark: 'hit', head: '最可能', body: `${word(step.level)} ${pctText(step.p)}${step.tie === true ? '（并列，取高的一档）' : ''}` }
    case 'max-gate':
      if (on) return { mark: 'hit', head: 'max 门槛', body: `max ${pctText(step.p)} < ${pctText(step.thetaMax)}，改取其余最可能的 ${word(step.level)}` }
      return { mark: 'pass', head: 'max 门槛', body: top?.level === 'max' ? `max ${pctText(step.p)} ≥ ${pctText(step.thetaMax)}，可以取 max` : '最可能的不是 max，不用过门槛' }
    case 'round-up':
      if (on) return { mark: 'hit', head: '上取一档', body: `${word(step.above)} ${pctText(step.p)} ≥ ${pctText(step.threshold)}，取高一档 ${word(step.level)}` }
      if (step.above === null) return { mark: 'pass', head: '上取一档', body: '已是最高一档' }
      if (step.blockedByMax === true) return { mark: 'pass', head: '上取一档', body: `max ${pctText(step.p)} ≥ ${pctText(step.threshold)}，但没到 max 门槛 ${pctText(step.thetaMax)}，不上取` }
      return { mark: 'pass', head: '上取一档', body: `${word(step.above)} ${pctText(step.p)} < ${pctText(step.threshold)}，不上取` }
    case 'model-floor':
      if (step.floor === null) return { mark: 'pass', head: '模型下限', body: `${word(step.model)} 没有下限` }
      if (on) return { mark: 'lift', head: '模型下限', body: `${word(step.model)} 至少 ${word(step.floor)}，${word(step.from)} 抬到 ${word(step.level)}` }
      return { mark: 'pass', head: '模型下限', body: `${word(step.model)} 至少 ${word(step.floor)}，${word(step.from)} 已够` }
    case 'forced-raise':
      return { mark: 'raise', head: '强制升档', body: `${word(step.from)} → ${word(step.level)}（${step.mode === 'max' ? '直接升到 max' : '升一档'}）` }
    case 'theta-up':
      return { mark: on ? 'hit' : 'pass', head: '升档门槛', body: `置信 ${pctText(step.confidence)} ${on ? '≥' : '<'} ${pctText(step.threshold)}，${on ? '把握够' : '把握不够'}` }
    case 'higher-of':
      return on ? { mark: 'hit', head: '取较高', body: `判断的 ${word(step.level)} 高于强制的 ${word(step.from)}，取 ${word(step.level)}` } : { mark: 'pass', head: '取较高', body: `判断的不比强制的高，取 ${word(step.from)}` }
    case 'suggest':
      return { mark: 'hit', head: '建议', body: `${word(step.picked)}，当前 ${word(step.current)}${step.direction === 'same' ? '，不变' : ''}` }
    case 'hold':
      if (on) return { mark: 'hit', head: '防抖', body: `升档后才 ${word(step.sinceRaise)} 步（${word(step.holdSteps)} 步内不降），还差 ${word(step.remaining)} 步` }
      return { mark: 'pass', head: '防抖', body: step.sinceRaise === null ? '这一轮没有升过档，可以降' : `升档已过 ${word(step.sinceRaise)} 步（${word(step.holdSteps)} 步内不降），可以降` }
    case 'theta-down':
      return { mark: on ? 'hit' : 'pass', head: '降档门槛', body: `置信 ${pctText(step.confidence)} ${on ? '≥' : '<'} ${pctText(step.threshold)}，${on ? '把握够' : '把握不够'}` }
    case 'one-step':
      return { mark: 'hit', head: '一次一档', body: `${word(step.from)} 降到 ${word(step.level)}` }
    case 'floor':
      return on ? { mark: 'lift', head: '下限', body: `至少 ${word(step.floor)}，${word(step.from)} 抬到 ${word(step.level)}` } : { mark: 'pass', head: '下限', body: `至少 ${word(step.floor)}，${word(step.from)} 已够` }
    default: {
      const fields = Object.entries(step).filter(([key]) => key !== 'rule' && key !== 'applied').map(([key, value]) => `${key} ${word(value)}`)
      return { mark: on ? 'hit' : 'pass', head: step.rule, body: fields.join(' · ') }
    }
  }
}

/** A mid-turn re-decision as the card's row says it: what it suggested, how sure it was against the line it had to pass, where it ended. */
type MidVerdict = {
  picked: Effort
  current: Effort
  result: Effort
  /** The confidence the answer had, and the line a move needed (absent: none was asked, the lowering held or the level the same). */
  conf?: number
  threshold?: number
  /** The answer passed that line (its step's own `applied`); null when no line was asked. */
  passed: boolean | null
  /** `up` / `down` moved; `blocked` a move short of the line; `held` a lowering waiting after a raise; `same` the level suggested is the current one. */
  kind: 'up' | 'down' | 'blocked' | 'held' | 'same'
  /** Which line: the raise's or the lowering's. */
  line: 'up' | 'down' | null
  /** The steps still to wait, while held. */
  remaining?: number
  /** A floor that lifted the result. */
  floor?: Effort
}

export function midVerdict(entry: LogEntry): MidVerdict | null {
  const mid = entry.mid
  if (mid === undefined) return null
  const steps = entry.trace ?? []
  const suggest = steps.find((step) => step.rule === 'suggest')
  const theta = steps.find((step) => step.rule === 'theta-up' || step.rule === 'theta-down')
  const hold = steps.find((step) => step.rule === 'hold' && step.applied)
  const floor = steps.find((step) => step.rule === 'floor' && step.applied)
  const conf = typeof theta?.confidence === 'number' ? theta.confidence : entry.conf
  const threshold = typeof theta?.threshold === 'number' ? theta.threshold : mid.threshold
  const direction = suggest?.direction ?? (mid.picked === mid.current ? 'same' : null)
  const line = theta === undefined ? (direction === 'up' ? 'up' : direction === 'down' ? 'down' : null) : theta.rule === 'theta-up' ? 'up' : 'down'
  const passed = theta === undefined ? null : theta.applied
  const kind: MidVerdict['kind'] =
    hold !== undefined || mid.held !== undefined
      ? 'held'
      : direction === 'same'
        ? 'same'
        : passed === false
          ? 'blocked'
          : mid.result === mid.current
            ? 'same'
            : line === 'down'
              ? 'down'
              : 'up'
  const remaining = typeof hold?.remaining === 'number' ? hold.remaining : mid.remaining
  return {
    picked: mid.picked,
    current: mid.current,
    result: mid.result,
    ...(conf === undefined ? {} : { conf }),
    ...(threshold === undefined || kind === 'held' ? {} : { threshold }),
    passed: kind === 'held' ? null : passed,
    kind,
    line: kind === 'held' ? 'down' : line,
    ...(kind === 'held' && remaining !== undefined ? { remaining } : {}),
    ...(floor !== undefined && isEffort(floor.floor) ? { floor: floor.floor } : {}),
  }
}

/** A verdict's conclusion in words: `升到 high`, `降档被拦，保持 xhigh`, `防抖中，还差 3 步，保持 xhigh`. */
export function verdictWords(verdict: MidVerdict): string {
  const lifted = verdict.floor === undefined ? '' : `（下限 ${verdict.floor}）`
  switch (verdict.kind) {
    case 'up':
      return `升到 ${verdict.result}${lifted}`
    case 'down':
      return `降一档到 ${verdict.result}${lifted}`
    case 'blocked':
      return `${verdict.line === 'down' ? '降档' : '升档'}被拦，保持 ${verdict.result}${lifted}`
    case 'held':
      return `防抖中${verdict.remaining === undefined ? '' : `，还差 ${verdict.remaining} 步`}，保持 ${verdict.result}${lifted}`
    case 'same':
      return `建议就是当前档，保持 ${verdict.result}${lifted}`
  }
}

// ---- the log ----------------------------------------------------------------------

/** What an entry did, in a word or two: the log's verb, coloured by its tone. */
export function entryVerb(entry: LogEntry): string {
  const feature = featureOf(entry.feature)
  switch (feature) {
    case 'main-effort':
    case 'dispatched-agents':
      return '已决定'
    case 'workflow-agents':
    case 'workflow-labels':
      return entry.sentBack === true ? '退回改写' : '已决定'
    case 'midturn-effort': {
      const verdict = midVerdict(entry)
      if (verdict === null) return '已重判'
      return verdict.kind === 'up' ? '升档' : verdict.kind === 'down' ? '降档' : verdict.kind === 'held' ? '防抖中' : '保持'
    }
    case 'escalation':
      return entry.forced !== undefined ? '强制升档' : entry.mid !== undefined && entry.mid.result !== entry.mid.current ? '重判改档' : '未升档'
    case 'unresolved':
      return entry.hint !== undefined ? '给了强提示' : entry.unresolved === undefined ? '记录' : unresolvedWords(entry.unresolved).verdict
    case 'skills':
      return entry.skills !== undefined && entry.skills.suggest.length + entry.skills.try.length > 0 ? '已建议' : '没有建议'
    case 'find-skill':
      return entry.skills !== undefined && entry.skills.suggest.length > 0 ? '查到' : '没查到'
    case 'skill-profiles':
      return entry.tone === 'ok' ? '画像就绪' : entry.tone === 'warn' ? '画像有失败' : entry.tone === 'fail' ? '画像停写' : '画像暂停'
    case 'decision-model':
      return '改用别的决策模型'
    case 'visual-check':
      return entry.tone === 'fail' ? '核对失败' : '已核对'
    case 'screenshot-takeover':
      return '已接管'
    default:
      return entry.tone === 'fail' ? '失败' : entry.tone === 'warn' ? '注意' : '记录'
  }
}

/** One turn of the log: its fold key (null past the 20 keys), whether it is open, the message it started with, its entries oldest first, its tones counted. */
export type LogGroup = {
  turn: number
  key: string | null
  open: boolean
  prompt: string
  entries: LogEntry[]
  counts: Record<Tone, number>
}

/** The log by turn, newest turn first; each open as the person left it, else the `OPEN_TURNS` newest. */
export function logGroups(log: readonly LogEntry[], state: PaneState): LogGroup[] {
  const turns = [...new Set(log.map((entry) => entry.turn))].sort((a, b) => b - a)
  return turns.map((turn, i) => {
    const entries = log.filter((entry) => entry.turn === turn)
    const chosen = state.folds.find((fold) => fold.turn === turn)
    const counts: Record<Tone, number> = { ok: 0, warn: 0, fail: 0, info: 0 }
    for (const entry of entries) counts[entry.tone] += 1
    return {
      turn,
      key: FOLD_KEYS[i] ?? null,
      open: chosen?.open ?? i < OPEN_TURNS,
      prompt: entries.find((entry) => featureOf(entry.feature) === 'main-effort')?.subject ?? '',
      entries,
      counts,
    }
  })
}

/** The pane's view state with one turn folded or opened (the choice kept for the turns the log still has). */
export function withFold(state: PaneState, turn: number, open: boolean, log: readonly LogEntry[]): PaneState {
  const kept = new Set(log.map((entry) => entry.turn))
  return { ...state, folds: [...state.folds.filter((fold) => fold.turn !== turn && kept.has(fold.turn)), { turn, open }] }
}

// ---- the top lines ------------------------------------------------------------------

/** Why writing the profiles stopped, in a few words (the stop's `detail` follows in its own words). */
const STOPPED: Record<NonNullable<ProfilesState['stop']>['reason'], (model: string) => string> = {
  'store-read': () => '读不到本地存储，不保留也不写',
  'model-refused': (model) => `引擎拒绝了 ${model}`,
  'api-error': (model) => `${model} 返回了接口错误`,
  'store-write': () => '本地存储存不下画像',
  off: () => '写的过程中被关掉了',
  error: () => '出错了',
}

/** How the session's skill profiles went, in one line: `skill 画像：保留 52 · 新写 3 · 失败 1`, `生成中 2/5`, or why it stopped. */
export function profilesLine(profiles: ProfilesState): { text: string; tone: 'muted' | 'warn' | 'fail' } {
  const counts = [`保留 ${profiles.kept}`, ...(profiles.phase === 'writing' ? [] : [`新写 ${profiles.written}`]), ...(profiles.failed > 0 ? [`失败 ${profiles.failed}`] : []), ...(profiles.deferred > 0 && profiles.phase !== 'writing' ? [`延后 ${profiles.deferred}`] : [])].join(' · ')
  if (profiles.phase === 'writing') return { text: `skill 画像：生成中 ${profiles.written}/${profiles.planned} · ${counts}`, tone: profiles.failed > 0 ? 'warn' : 'muted' }
  if (profiles.phase === 'stopped') {
    const stop = profiles.stop
    const why = stop === undefined ? '' : `${STOPPED[stop.reason](profiles.model)}${stop.detail === '' ? '' : `：${stop.detail}`}`
    return { text: `skill 画像：已停写（${why}） · ${counts}`, tone: stop?.reason === 'off' ? 'muted' : 'fail' }
  }
  return { text: `skill 画像：${counts}`, tone: profiles.failed > 0 ? 'warn' : 'muted' }
}

