// The Workflow fallback (#9): which `agent()` call of a script an agent of a
// running Workflow stands for, found by the label it is spawned with, and what
// the main agent is told of it.
//
// The workflow-agents feature (#8) can write the agents' model and effort into
// the script only when the script is inline and it can read the call. For the
// rest (a script given by path or by name, a resumed run, a script it cannot
// read, a call whose prompt is data), each agent is routed as it is spawned
// (`agent.spawn` with `e.workflow`, 2.1.300 on): the spawn's `description` is
// its label, the label says which call it is, and the call's decision (made
// when the run started, or from the agent's own prompt then) sets the spawn's
// model and goes into the plan table.
//
// Pure (see system-one.ts).

import type { Failure } from './backend.ts'
import { termsOf, type AgentModel, type Terms } from './dispatched-agent.ts'
import type { Effort } from './effort.ts'
import { cooked, templatePieces, type AgentCall, type Written } from './workflow-script.ts'
import { callName, decidedAtStart, decidedLine, outcomeOf, type CallOutcome, type Skipped } from './workflow.ts'

/** How the agents of one call are routed. */
export type SiteRoute =
  /** Decided when the run started: what each of its agents is set to (null: the step's own). */
  | { kind: 'set'; model: AgentModel | null; effort: Effort | null }
  /** Decided when each of its agents starts, from that agent's own prompt. */
  | { kind: 'runtime' }
  /** Left to the script: the workflow-agents feature wrote it, it already says what was decided, or no decision was made. */
  | { kind: 'script' }

/** How the label an agent is spawned with is told to be a call's. */
export type LabelMatch =
  /** A label the script writes as a string: that string. */
  | { kind: 'exact'; label: string }
  /** A template label: a regular expression's source, its `${...}` matching anything. */
  | { kind: 'pattern'; source: string }
  /** No label: the engine labels the agent with the prompt's start; `whole` when the prompt has no placeholder, so `head` is all of it. */
  | { kind: 'head'; head: string; whole: boolean }
  /** Nothing to tell it by: a label, or a prompt without one, that the script works out when it runs. */
  | { kind: 'none' }

/** One `agent()` call of a run's script, as this feature keeps it (`labelRuns` in types/index.d.ts). */
export type RunSite = {
  /** The line it starts on, for the log. */
  line: number
  /** The label as written (a template keeps its `${...}`); null when there is none or it is worked out when the script runs. */
  label: string | null
  match: LabelMatch
  route: SiteRoute
  /** The call's own options, for a decision made as its agents start (what the script works out itself is left alone). */
  model: Written
  effort: Written
  agentType: string | null
  /** The person's terms for the call's work, as its decision read them (null: none, or not decided yet); its agents' plans keep them. */
  terms: Terms | null
}

/** The routes of a script's calls, from what was decided about them when the run started (`readOutcomes`). */
export function sitesOf(calls: readonly AgentCall[], outcomes: readonly CallOutcome[]): RunSite[] {
  return calls.map((call, index) => {
    const outcome = outcomes[index]
    return siteOf(call, routeOf(outcome), outcome === undefined || outcome.kind === 'left' ? null : termsOf(outcome.decision))
  })
}

/**
 * The routes of the calls of a script the main agent sent inline: the
 * workflow-agents feature asked about every call but those in `skipped` (a
 * prompt it cannot read, a call past what it asks about), and wrote what it
 * could into the script; those are decided as their agents start. `terms`:
 * what its decisions read of the person's terms for each call, by index.
 */
export function inlineSites(calls: readonly AgentCall[], skipped: readonly Skipped[], terms: readonly (Terms | null)[] = []): RunSite[] {
  const left = new Set(skipped.map((skip) => skip.index))
  return calls.map((call) => siteOf(call, left.has(call.index) ? { kind: 'runtime' } : { kind: 'script' }, terms[call.index] ?? null))
}

function siteOf(call: AgentCall, route: SiteRoute, terms: Terms | null): RunSite {
  return { line: call.line, label: call.label, match: matchOf(call), route, model: call.model, effort: call.effort, agentType: call.agentType, terms }
}

function routeOf(outcome: CallOutcome | undefined): SiteRoute {
  if (outcome === undefined || outcome.kind === 'kept') return { kind: 'script' }
  if (outcome.kind === 'left') return decidedAtStart(outcome) ? { kind: 'runtime' } : { kind: 'script' }
  const model = (outcome.write.model ?? null) as AgentModel | null
  const effort = typeof outcome.write.effort === 'string' ? (outcome.write.effort as Effort) : null
  return { kind: 'set', model, effort }
}

/**
 * How the label the engine gives one of the call's agents is told to be this
 * call's. A label the script writes as a string is that string. A template
 * label (`migrate:${file}`, read as written: the parser keeps its `${...}`) is
 * a pattern: its own text must be there, each placeholder matches anything;
 * one with no text of its own says nothing. A call without a label is labelled
 * with the start of its prompt (measured on 2.1.289: whitespace collapsed, cut
 * at 60 characters): a string prompt's start, or a template's own text before
 * its first placeholder.
 */
function matchOf(call: AgentCall): LabelMatch {
  if (call.labelKind === 'string' && call.label !== null) return { kind: 'exact', label: call.label }
  if (call.labelKind === 'template' && call.label !== null) {
    const source = templateSource(call.label)
    return source === null ? { kind: 'none' } : { kind: 'pattern', source }
  }
  if (call.labelKind === 'none' && call.prompt !== null) {
    const template = call.promptTemplate === true
    const pieces = template ? templatePieces(call.prompt) : [{ text: call.prompt, placeholder: false }]
    const first = pieces[0]
    const whole = pieces.length === 1 && first?.placeholder === false
    // A string prompt is already cooked; a template's text is as written.
    const head = first === undefined || first.placeholder ? '' : flat(template ? cooked(first.text) : first.text)
    return head === '' ? { kind: 'none' } : { kind: 'head', head: whole ? head.slice(0, ENGINE_LABEL) : head, whole }
  }
  return { kind: 'none' }
}

/** A template label as a regular expression's source: its own text in place, each `${...}` anything; null when it has no text of its own. */
function templateSource(template: string): string | null {
  const pieces = templatePieces(template)
  if (pieces.every((piece) => piece.placeholder || piece.text.trim() === '')) return null
  return `^${pieces.map((piece) => (piece.placeholder ? '[\\s\\S]*' : escapeRegExp(cooked(piece.text)))).join('')}$`
}

/**
 * Whether `label`, as the engine recorded it for an agent, is one a call whose label is written as the template `written`
 * (`verify:${b.id}`, read as written) gives. False when `written` has no `${...}`, or no text of its own.
 */
export function fitsTemplate(written: string, label: string): boolean {
  if (!written.includes('${')) return false
  const source = templateSource(written)
  return source !== null && new RegExp(source).test(label)
}

/** How many characters of a prompt the engine labels the agent of a call without a label with. */
const ENGINE_LABEL = 60

/** Text with each run of whitespace one space, trimmed: how a label and a prompt's start compare. */
function flat(text: string): string {
  return text.replace(/\s+/g, ' ').trim()
}

/** Whether `label` is what the engine labels the agent of a call without one, whose prompt starts as `match` says, with. */
function startsAs(label: string, match: { head: string; whole: boolean }): boolean {
  const recorded = flat(label)
  if (match.whole || match.head.length >= ENGINE_LABEL) return recorded === flat(match.head.slice(0, ENGINE_LABEL))
  return recorded.startsWith(match.head)
}

function escapeRegExp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

/**
 * The calls of `sites` an agent spawned with `label` can be one of: the
 * calls whose string label it is; else those whose template it fits; else,
 * when none does, the calls nothing tells apart (a label or prompt the script
 * works out when it runs).
 */
export function sitesFor(label: string, sites: readonly RunSite[]): RunSite[] {
  const exact = sites.filter((site) => site.match.kind === 'exact' && site.match.label === label)
  if (exact.length > 0) return exact
  const fits = sites.filter((site) => (site.match.kind === 'pattern' && new RegExp(site.match.source).test(label)) || (site.match.kind === 'head' && startsAs(label, site.match)))
  if (fits.length > 0) return fits
  return sites.filter((site) => site.match.kind === 'none')
}

/** What the engine writes before a workflow agent's task, up to the task itself (2.1.289); each line of the task follows indented by two spaces. */
const TASK_FOLLOWS = 'The computed task text follows:\n'
/** How the frame starts in which the engine relays the person's request to a workflow agent, before its task (seen on 2.1.281-2.1.282). */
const RELAYED_REQUEST = '[Workflow harness — user request]'

/** The task a script computed, without the frame the engine puts around it; null when `text` is not such a frame. */
export function computedTask(text: string): string | null {
  const at = text.indexOf(TASK_FOLLOWS)
  if (at < 0) return null
  return text
    .slice(at + TASK_FOLLOWS.length)
    .split('\n')
    .map((taskLine) => (taskLine.startsWith('  ') ? taskLine.slice(2) : taskLine))
    .join('\n')
}

/** Whether `text` is the frame in which the engine relays the person's request to a workflow agent (not the agent's task). */
export function isRelayedRequest(text: string): boolean {
  return text.trimStart().startsWith(RELAYED_REQUEST)
}

/** Whether `label` is only what the engine labels the agent of a call without one with: the start of its task. */
export function isTaskStart(label: string, task: string): boolean {
  const recorded = flat(label)
  return recorded !== '' && flat(flat(task).slice(0, ENGINE_LABEL)) === recorded
}

/** How the Workflow tool was handed the script: inline (`script`), by `scriptPath`, by `name`, or inline to resume an earlier run. */
export type Given = 'script' | 'path' | 'name' | 'resume'

/** How a Workflow call was submitted; `script` holds the text when it was inline and is not a resume. */
export type Submission = { given: 'script'; script: string } | { given: Exclude<Given, 'script'> }

/**
 * How the Workflow tool call `e` hands over its script. The one reading of it, for the features that rewrite a script
 * (`script`: the engine runs the text as sent) and those that route by label (every other way): a path or a name runs a
 * script the tool reads itself, and a resume matches the earlier run's agents by their prompts and options.
 */
export function submissionOf(e: { scriptPath?: string | undefined; script?: string | undefined; name?: string | undefined; resumeFromRunId?: string | undefined }): Submission {
  if (e.scriptPath !== undefined) return { given: 'path' }
  if (e.script === undefined || e.name !== undefined) return { given: 'name' }
  return e.resumeFromRunId !== undefined ? { given: 'resume' } : { given: 'script', script: e.script }
}

/**
 * What the main agent reads after the Workflow tool's result about the agents
 * this feature routes as they start; null when there is nothing to say.
 * `launched`: what was decided about each call when the run started (a
 * script given by path or by name, or resumed).
 */
export function launchNote(
  given: Given,
  sites: readonly RunSite[] | null,
  launched: { calls: readonly AgentCall[]; outcomes: readonly CallOutcome[]; describe: (failure: Failure) => string } | null,
): string | null {
  if (sites === null) return "Dispatch Pilot (the user's routing plugin) could not read this script, so it decides each agent's model and effort as the agent starts, from its label and its task."
  if (given === 'script') {
    return sites.some((site) => site.route.kind === 'runtime')
      ? "Dispatch Pilot (the user's routing plugin) sets the model and effort of the agents of the agent() calls it leaves as written, as each one starts, from its label and its task."
      : null
  }
  if (launched === null) return null
  const lines = launched.outcomes.map((outcome, index) => {
    const call = launched.calls[index] as AgentCall
    if (outcome.kind === 'written') return `- ${decidedLine(call, outcome.decision)}`
    if (outcome.kind === 'kept') return `- ${callName(call)}: as the script has it (${outcomeOf(call, outcome.decision)})`
    if (decidedAtStart(outcome)) return `- ${callName(call)}: decided as each of its agents starts, from its label and its task`
    return `- ${callName(call)}: as the script has it (${outcome.failure === undefined ? 'no answer from the decision model' : launched.describe(outcome.failure)})`
  })
  const header = launched.outcomes.some((outcome) => outcome.kind !== 'left')
    ? "Dispatch Pilot (the user's routing plugin) chose a model and an effort for the agent() calls of this Workflow. The script is unchanged: each agent gets its call's choice as it starts, found by its label."
    : "Dispatch Pilot (the user's routing plugin) decides the model and effort of this Workflow's agents as each one starts. The script is unchanged."
  return [header, ...lines].join('\n')
}

/** The person's terms every one of `sites` carries; null when they carry none, or not the same. */
export function sharedTerms(sites: readonly RunSite[]): Terms | null {
  const first = sites[0]?.terms ?? null
  return first !== null && sites.every((site) => JSON.stringify(site.terms) === JSON.stringify(first)) ? first : null
}

/** Whether two routes set the same thing. */
export function sameRoute(a: SiteRoute, b: SiteRoute): boolean {
  if (a.kind !== b.kind) return false
  return a.kind !== 'set' || b.kind !== 'set' || (a.model === b.model && a.effort === b.effort)
}

files.hooks/core/profile-report.ts:
// What the skill profiles' events (features/skill-profiles.ts) come to, for the 「决定汇报」 module (core/report.ts,
// `report`'s `profiles`): the events, the state they add up to, the debug line of each and the decision log entry the
// state ends in. Pure data and functions: the module keeps the state and writes the log (see report.ts: `$` stays in the
// hook owner's file).

import type { LogEntry } from './report.ts'

/** Why writing the profiles stopped for the session (types/index.d.ts, `skillProfiles.stop`). */
type ProfilesStopReason = 'store-read' | 'model-refused' | 'api-error' | 'store-write' | 'off' | 'error'

/** How writing the session's skill profiles went (#33; types/index.d.ts, `skillProfiles`). */
export type ProfilesState = {
  phase: 'writing' | 'done' | 'stopped'
  /** The turn the session start belongs to: the turn of its decision log entry. */
  turn: number
  model: string
  kept: number
  planned: number
  written: number
  failed: number
  deferred: number
  stop?: { reason: ProfilesStopReason; detail: string }
  failures: { name: string; reason: string }[]
}

/** The failed skills the state names; `failed` still counts every one. */
const PROFILES_FAILURES_KEPT = 50

/** Why the writing stopped, with what the debug line and the state say of it. */
export type ProfilesStop =
  | { reason: 'model-refused'; model: string; detail: string }
  | { reason: 'api-error'; skill: string; why: string; ms: number }
  | { reason: 'store-write'; skill: string; detail: string }
  | { reason: 'off' }
  | { reason: 'error'; detail: string }

/**
 * What happens as the skill profiles are written (features/skill-profiles.ts), in the order it happens. `left`:
 * the skills lacking a profile that this session did not get to.
 */
export type ProfileEvent =
  /** The session start has read the catalog: `offered` skills can have one, `due` of them lack one; at most `perSession` are written. */
  | { event: 'start'; model: string; perSession: number; offered: number; due: number }
  /** The store cannot be read: nothing is kept or written. */
  | { event: 'unreadable'; model: string; offered: number }
  /** Another session wrote the profile meanwhile: it is kept. */
  | { event: 'found' }
  | { event: 'written'; skill: string; model: string; ms: number; input: number; output: number }
  /** The model gave no profile for the skill (`why`: the reply's reason); the writing goes on. */
  | { event: 'failed'; skill: string; why: string; ms: number }
  /** The reply for the skill is no profile; the writing goes on. */
  | { event: 'unfit'; skill: string; ms: number; text: string }
  /** The session's most is written; `left` is what no longer fits (the debug line counts what is not written, failed included). */
  | { event: 'quota'; perSession: number; left: number }
  /** The loop is over, as it should be. */
  | { event: 'finish'; left: number }
  | { event: 'stop'; cause: ProfilesStop; left: number }
  /** The store's oldest profiles were dropped (`total` kept before, `kb` of them). */
  | { event: 'tidied'; dropped: number; total: number; kb: number }
  | { event: 'tidy-failed'; detail: string }

/** The debug log's line for an event; null when it has none. */
export function profilesLine(event: ProfileEvent): string | null {
  switch (event.event) {
    case 'start':
      return `skill profiles: ${event.offered - event.due} kept, ${event.due} to write with ${event.model} (at most ${event.perSession} this session)`
    case 'unreadable':
      return 'skill profiles: the store cannot be read, so no profile is kept or written; skills are rated by their descriptions'
    case 'found':
      return null
    case 'written':
      return `skill profile written for ${event.skill} by ${event.model} in ${event.ms} ms (${event.input} input, ${event.output} output tokens)`
    case 'failed':
      return `skill profiles: no profile for ${event.skill} (${event.why}, ${event.ms} ms)`
    case 'unfit':
      return `skill profiles: the reply for ${event.skill} is not a profile (${event.ms} ms): ${JSON.stringify(event.text.slice(0, 80))}`
    case 'quota':
      return `skill profiles: ${event.left} left to write at a later session start (at most ${event.perSession} each)`
    case 'finish':
      return null
    case 'stop': {
      const cause = event.cause
      const more = 'no more profiles are written this session'
      if (cause.reason === 'model-refused') return `skill profiles: ${cause.model} was refused (${cause.detail}); ${more}`
      if (cause.reason === 'api-error') return `skill profiles: no profile for ${cause.skill} (${cause.why}, ${cause.ms} ms); ${more}`
      if (cause.reason === 'store-write') return `skill profiles: the store did not keep the profile of ${cause.skill} (${cause.detail}); ${more}`
      if (cause.reason === 'error') return `skill profiles: stopped writing (${cause.detail})`
      return null
    }
    case 'tidied':
      return `skill profiles: dropped the ${event.dropped} oldest of ${event.total} kept (${event.kb} KB)`
    case 'tidy-failed':
      return `skill profiles: could not tidy the store (${event.detail})`
  }
}

/** The state a session start begins with. Nothing to write (or no store to keep it): it is over at once. */
export function profilesBegin(event: Extract<ProfileEvent, { event: 'start' | 'unreadable' }>, turn: number): ProfilesState {
  if (event.event === 'unreadable') {
    return { phase: 'stopped', turn, model: event.model, kept: 0, planned: 0, written: 0, failed: 0, deferred: event.offered, stop: { reason: 'store-read', detail: '' }, failures: [] }
  }
  const planned = event.due > 0 ? Math.max(0, Math.min(event.due, event.perSession)) : 0
  return { phase: planned > 0 ? 'writing' : 'done', turn, model: event.model, kept: event.offered - event.due, planned, written: 0, failed: 0, deferred: event.due - planned, failures: [] }
}

/**
 * What the model's reply for a skill said it failed with (the engine's reason, as the feature words it), in the
 * person's words: `empty-reply`, `an API error, HTTP 529 overloaded`. What the server said of itself stays as it
 * said it; anything this does not know is left as it is.
 */
function profileWhy(why: string): string {
  if (why === 'empty-reply') return '模型回了空内容'
  if (why === 'aborted') return '请求被中断'
  const api = /^an API error, HTTP (\S+)(?: (.*))?$/.exec(why)
  if (api !== null) return `接口出错（状态码 ${api[1]}${api[2] === undefined || api[2] === '' ? '' : ` ${api[2]}`}）`
  return why
}

/** The state after an event that comes while the profiles are being written; the same state (`===`) when the event changes nothing. */
export function profilesAdvance(state: ProfilesState, event: ProfileEvent): ProfilesState {
  switch (event.event) {
    case 'found':
      return { ...state, kept: state.kept + 1 }
    case 'written':
      return { ...state, written: state.written + 1 }
    case 'failed':
    case 'unfit': {
      const reason = event.event === 'failed' ? profileWhy(event.why) : '回复不是画像'
      const failures = state.failures.length < PROFILES_FAILURES_KEPT ? [...state.failures, { name: event.skill, reason }] : state.failures
      return { ...state, failed: state.failed + 1, failures }
    }
    case 'finish':
      return { ...state, phase: 'done', deferred: event.left }
    case 'stop': {
      const cause = event.cause
      const detail = cause.reason === 'api-error' ? profileWhy(cause.why) : cause.reason === 'store-write' ? `${cause.skill}：${cause.detail}` : cause.reason === 'off' ? '' : cause.detail
      return { ...state, phase: 'stopped', deferred: event.left, stop: { reason: cause.reason, detail } }
    }
    default:
      return state
  }
}

/** How many failed skills the entry's reason names. */
const PROFILES_NAMED = 3

/** The session's one decision log entry for a state the writing has ended in. */
export function profilesEntry(state: ProfilesState): Omit<LogEntry, 'n'> {
  const stopped = state.phase === 'stopped'
  const counts = [`保留 ${state.kept}`, `新写 ${state.written}`, ...(state.failed > 0 ? [`失败 ${state.failed}`] : []), ...(state.deferred > 0 ? [`延后 ${state.deferred}`] : [])].join(' · ')
  const named = state.failures.slice(0, PROFILES_NAMED).map((failure) => `${failure.name}：${failure.reason}`)
  const failed = state.failed > 0 ? `（${named.join('；')}${state.failed > named.length ? `；另有 ${state.failed - named.length} 个` : ''}）` : ''
  const stop = state.stop
  const why =
    stop === undefined
      ? ''
      : stop.reason === 'store-read'
        ? '读不到本地存储，不保留也不写'
        : stop.reason === 'model-refused'
          ? `引擎拒绝了 ${state.model}（${stop.detail}）`
          : stop.reason === 'api-error'
            ? `${state.model} 返回了接口错误：${stop.detail}`
            : stop.reason === 'store-write'
              ? `本地存储存不下画像（${stop.detail}）`
              : stop.reason === 'off'
                ? '写的过程中被关掉了'
                : `出错了（${stop.detail}）`
  return {
    turn: state.turn,
    feature: 'skill-profiles',
    tone: stopped ? (stop?.reason === 'off' ? 'info' : 'fail') : state.failed > 0 ? 'warn' : 'ok',
    outcome: stopped ? '画像停写' : state.failed > 0 ? `画像：${state.failed} 个失败` : '画像就绪',
    subject: '',
    reason: `${stopped ? `${why}；` : ''}${counts}${failed}`,
  }
}

files.hooks/decision/escalation.ts:
// Forced escalation (#7): the request a loop whose tool calls keep failing is
// asked about, what the loop is read from, and the rules that turn the answer
// into a level.
//
// Pure (see system-one.ts). The request is the mid-turn effort request
// (midturn.ts, with its `trouble`) and one more question: is what failed what
// the work expects at this point (a test written to fail first, a search that
// finds nothing), or is the work stuck? Written to TypeSafe's guide for Noul
// (docs/research/typesafe-question-guide.md §2.5): one yes/no question, a high
// value means yes, `criteria.true` is yes. The mod and the eval build it with
// `stuckRequest` (spec #67).

import { withoutReminders } from './context.ts'
import { DEFAULT_ASK, EFFORTS, higherEffort, traceEffort, type Effort, type EffortAsk, type EffortReading, type EffortRules, type EffortStep, type Language } from './effort.ts'
import { midturnEffortPart, midturnState, outcomeOf, resultLine, toolDetail, type MidturnInput, type MidturnLimits, type MidturnStep, type MidturnTool, type Outcome } from './midturn.ts'
import { mergeParts, type Answer, type DecisionRequest, type Part, type Question } from './system-one.ts'
import { computedTask, isRelayedRequest } from './workflow-labels.ts'

/** The part's name and its one question's id: `escalation.expected` in a request. */
export const ESCALATION_PART = 'escalation'
export const EXPECTED = 'expected'

/**
 * How a forced raise moves the level: `one-level` goes up one level, never
 * past xhigh; `max` goes straight to max.
 */
export const RAISE_MODES = ['one-level', 'max'] as const
export type RaiseMode = (typeof RAISE_MODES)[number]

/** The level a forced raise goes to from `current`; null when there is nowhere to go (xhigh or max in `one-level`, max in `max`). */
export function forcedTarget(current: Effort, mode: RaiseMode): Effort | null {
  const at = EFFORTS.indexOf(current)
  const top = mode === 'max' ? EFFORTS.indexOf('max') : EFFORTS.indexOf('xhigh')
  const to = mode === 'max' ? top : Math.min(at + 1, top)
  return to > at ? (EFFORTS[to] as Effort) : null
}

/**
 * One step of a forced raise's working, besides the effort rules' own (`EffortStep`) that read the answer's pick.
 * Data only, like them (ADR 0004).
 */
export type RaiseStep =
  /** The failures force the loop from `from` to `level` (one level up, or max: `mode`). */
  | { rule: 'forced-raise'; applied: true; level: Effort; from: Effort; mode: RaiseMode }
  /** The answer's own pick counts only when it is sure enough: `confidence` >= `threshold` (thetaUp). */
  | { rule: 'theta-up'; applied: boolean; confidence: number; threshold: number }
  /** The higher of the forced level (`from`) and the answer's pick; `applied` when the pick was higher. */
  | { rule: 'higher-of'; applied: boolean; level: Effort; from: Effort }

/**
 * The level a forced raise ends at, with its working: `target` (the one level,
 * or max, the failures force, from `from`), or the decision model's own pick
 * when that is higher and its answer is sure enough (`thetaUp`, as for any
 * mid-turn raise); the level above the pick from `roundUp` and `max` only past `thetaMax`, as everywhere. The steps are the
 * forced raise, then (with an answer) the effort rules' walk to its pick, the
 * confidence check and the comparison.
 */
export function traceRaise(
  reading: EffortReading | null,
  forced: { from: Effort; target: Effort; mode: RaiseMode },
  rules: EffortRules & { thetaUp: number },
): { level: Effort; steps: (EffortStep | RaiseStep)[] } {
  const { target } = forced
  const steps: (EffortStep | RaiseStep)[] = [{ rule: 'forced-raise', applied: true, level: target, from: forced.from, mode: forced.mode }]
  if (reading === null) return { level: target, steps }
  const pick = traceEffort(reading, rules)
  const confidence = reading.confidence ?? Math.max(...reading.probabilities)
  const sure = confidence >= rules.thetaUp
  steps.push(...pick.steps, { rule: 'theta-up', applied: sure, confidence, threshold: rules.thetaUp })
  if (!sure) return { level: target, steps }
  const level = higherEffort(target, pick.effort) as Effort
  steps.push({ rule: 'higher-of', applied: level !== target, level, from: target })
  return { level, steps }
}

/** What went wrong, in one English sentence for the decision model's state (`trouble`): `2 tool calls have failed while working on this request`. */
export function troubleText(counted: { failures: number; hookBlocks: number }): string {
  const n = counted.failures + counted.hookBlocks
  const how = counted.hookBlocks > 0 ? 'failed or been blocked by a hook' : 'failed'
  return `${n} tool call${n === 1 ? ' has' : 's have'} ${how} while working on this request`
}

const EXPECTED_QUESTION: Record<Language, Question> = {
  en: {
    type: 'noul',
    instructions: 'Are the failed tool calls in `recent_steps` what the work on `user_message` expects at this point, rather than a sign that the work is stuck?',
    criteria: {
      true: 'The failures are part of how the work goes: a test written first and run to watch it fail, a search or check that exits with an error because it found nothing or has something to report, a command run to find out whether something exists or works.',
      false: 'The failures are obstacles: the same call failing again and again, a command, path or tool that does not exist or is used wrongly, an error in code just written, or a fix that did not take.',
    },
  },
  zh: {
    type: 'noul',
    instructions: '`recent_steps` 里失败的工具调用，是不是 `user_message` 这项工作此时本来就会遇到的，而不是工作卡住的迹象？',
    criteria: {
      true: '失败本来就是工作的一部分：先写下并运行、要看它失败的测试；因为没找到东西或有东西要报告而以错误退出的搜索或检查；为了弄清某样东西是否存在、能否运行而执行的命令。',
      false: '失败是障碍：同一个调用一再失败；命令、路径或工具不存在或用法不对；刚写的代码有错误；修复没有生效。',
    },
  },
}

/** The part a stuck re-decision adds to its request: `escalation.expected`. */
export function expectedFailurePart(ask: Partial<EffortAsk> = {}): Part {
  const asked = { ...DEFAULT_ASK, ...ask }
  return { part: ESCALATION_PART, questions: { [EXPECTED]: EXPECTED_QUESTION[asked.language] } }
}

/** The probability that the failures were expected (the answer's `noul`); null without a usable answer. */
export function readExpected(answers: Readonly<Record<string, Answer>>): number | null {
  const answer = answers[EXPECTED]
  return answer?.type === 'noul' ? answer.noul : null
}

/** A stuck re-decision's request, and its parts to read the answers back with. */
export type StuckRequest = { request: DecisionRequest; effortPart: Part | null; expectedPart: Part }

/**
 * The request a stuck loop's re-decision sends (`input` with its `trouble`):
 * the mid-turn state and effort question, with the trouble flag, and whether
 * the failures were expected. A loop raised by another model, not a level (a
 * haiku agent at the top level), is asked the second only, its state without a current level.
 */
export function stuckRequest(input: MidturnInput, options: { limits: MidturnLimits; ask?: Partial<EffortAsk>; effort: boolean }): StuckRequest {
  const effortPart = options.effort ? midturnEffortPart(options.ask, { trouble: true }) : null
  const expectedPart = expectedFailurePart(options.ask)
  const state = midturnState(input, options.limits, options.effort ? {} : { currentEffort: false })
  return { request: mergeParts(state, effortPart === null ? [expectedPart] : [effortPart, expectedPart]), effortPart, expectedPart }
}

/** A transcript row as `$.session.messages()` gives it (the part read here); `rowsFromTranscript` reads an agent's transcript file to the same shape. */
export type TranscriptRow = {
  role: 'user' | 'assistant'
  text: string
  toolUses?: readonly { tool_use_id?: string; tool: string; input?: Readonly<Record<string, unknown>>; text?: string; isError?: true }[]
  toolResults?: readonly unknown[]
}

/** A row's words without what the engine wraps in <system-reminder> (not something anyone said). */
function unwrapped(text: string): string {
  return withoutReminders(text).trim()
}

/** The task an agent was given: the first thing said to it in its transcript ('' when there is none). */
export function briefOf(rows: readonly TranscriptRow[]): string {
  for (const row of rows) {
    const words = row.role === 'user' ? unwrapped(row.text) : ''
    if (words !== '') return words
  }
  return ''
}

/**
 * What a loop has done since the last thing a person said, as the decision
 * model reads it: the steps, oldest first, each the text the agent wrote and
 * its tool calls with how they ended (the mid-turn request's `recent_steps`).
 * The transcript gives a response one row per block and the tool results rows
 * of their own, so a step is the run of assistant rows between two user rows.
 * `ended` says how a call ended when it was seen ending (a call that has just
 * ended has no result in the transcript yet, and a hook's refusal reads as
 * any error there); the transcript says it for the rest.
 */
export function stepsFromRows(rows: readonly TranscriptRow[], options: { language: Language; ended?: (toolUseId: string) => Exclude<Outcome, 'running'> | undefined }): MidturnStep[] {
  const said = (row: TranscriptRow) => row.role === 'user' && unwrapped(row.text) !== '' && (row.toolResults?.length ?? 0) === 0
  const from = rows.findLastIndex(said) + 1
  const steps: MidturnStep[] = []
  let texts: string[] = []
  let tools: MidturnTool[] = []
  const close = () => {
    if (texts.length > 0 || tools.length > 0) steps.push({ assistant_text: texts.join('\n'), tools })
    texts = []
    tools = []
  }
  for (const row of rows.slice(from)) {
    if (row.role === 'user') {
      close()
      continue
    }
    if (row.text.trim() !== '') texts.push(row.text.trim())
    for (const use of row.toolUses ?? []) {
      const outcome = (use.tool_use_id === undefined ? undefined : options.ended?.(use.tool_use_id)) ?? outcomeOf(use.tool, { isError: use.isError, text: use.text }, false)
      tools.push({ name: use.tool, result: resultLine(outcome, toolDetail(use.input ?? {}), options.language) })
    }
  }
  close()
  return steps
}

/**
 * An agent's transcript file (`agent-<agentId>.jsonl`, one JSON object a line,
 * as Claude Code writes it) as transcript rows: its task (a workflow agent's
 * framed task unframed; the user's request the engine may relay before it is
 * left out), what it wrote and called, and what came back, each call with how
 * it ended. Lines that are not messages (attachments) are skipped.
 */
export function rowsFromTranscript(jsonl: string): TranscriptRow[] {
  type Block = { type?: unknown; text?: unknown; id?: unknown; name?: unknown; input?: unknown; tool_use_id?: unknown; content?: unknown; is_error?: unknown }
  const messages: { role: 'user' | 'assistant'; content: unknown }[] = []
  for (const line of jsonl.split('\n')) {
    let row: { type?: unknown; message?: { role?: unknown; content?: unknown } }
    try {
      row = JSON.parse(line) as typeof row
    } catch {
      continue
    }
    const role = row.message?.role
    if ((row.type === 'user' || row.type === 'assistant') && (role === 'user' || role === 'assistant')) messages.push({ role, content: row.message?.content })
  }
  const blocks = (content: unknown): Block[] => (Array.isArray(content) ? content.filter((block): block is Block => typeof block === 'object' && block !== null) : [])
  const textOf = (content: unknown): string => (typeof content === 'string' ? content : blocks(content).map((block) => (block.type === 'text' && typeof block.text === 'string' ? block.text : '')).join(''))
  // How each call ended, by its id: what came back for it.
  const results = new Map<string, { text: string; isError: boolean }>()
  for (const message of messages) {
    if (message.role !== 'user') continue
    for (const block of blocks(message.content)) {
      if (block.type === 'tool_result' && typeof block.tool_use_id === 'string') results.set(block.tool_use_id, { text: textOf(block.content), isError: block.is_error === true })
    }
  }
  const rows: TranscriptRow[] = []
  for (const message of messages) {
    if (message.role === 'user') {
      const answered = blocks(message.content).filter((block) => block.type === 'tool_result')
      if (answered.length > 0) {
        rows.push({ role: 'user', text: '', toolResults: answered })
        continue
      }
      const text = textOf(message.content)
      if (isRelayedRequest(text)) continue
      rows.push({ role: 'user', text: computedTask(text) ?? text })
      continue
    }
    const uses = blocks(message.content).flatMap((block) => {
      if (block.type !== 'tool_use' || typeof block.name !== 'string') return []
      const id = typeof block.id === 'string' ? block.id : undefined
      const result = id === undefined ? undefined : results.get(id)
      const input = typeof block.input === 'object' && block.input !== null ? (block.input as Record<string, unknown>) : {}
      return [{ ...(id === undefined ? {} : { tool_use_id: id }), tool: block.name, input, ...(result === undefined ? {} : { text: result.text, ...(result.isError ? { isError: true as const } : {}) }) }]
    })
    rows.push({ role: 'assistant', text: textOf(message.content), ...(uses.length > 0 ? { toolUses: uses } : {}) })
  }
  return rows
}

