// The decisions about a Workflow script's agents (#8): the requests the
// decision model answers about its `agent()` calls, how the answers become what
// is written into each call, and what the main agent is told.
//
// One `agent()` call is one dispatched agent for the decision model: the same
// questions as a dispatched agent's (dispatched-agent.ts), so a call is judged
// the way the eval measures an agent. Several calls share one request: each in
// a part of its own (`agent-0`, `agent-1`, ...) reading a state field of its own
// (`brief_0`, `brief_1`, ...), the person's words in one `user_message`, and
// the script and the conversation once (`WorkflowBackground`). Dispatched agents
// that start together share requests the same way (`agentBatches`, core/agent-lane.ts).
//
// Pure (see system-one.ts).

import type { Asked, Failure } from './backend.ts'
import type { ReferenceReading } from './complexity.ts'
import { clipToTokens, estimateTokens, recentWithin, withinTokens } from './context.ts'
import {
  backgroundState,
  decideDispatch,
  dispatchBrief,
  dispatchPart,
  dispatchReason,
  dispatchState,
  dispatchWords,
  modelFamily,
  type Dispatch,
  type DispatchDecision,
  type DispatchSettings,
} from './dispatched-agent.ts'
import { EFFORTS, type Language } from './effort.ts'
import { redactSecrets } from './redact.ts'
import { renderSummary, type Summary } from './summary.ts'
import { answersFor, MAX_QUESTIONS, mergeParts, type DecisionRequest, type Part, type State } from './system-one.ts'
import { entriesOf, templatePieces, type AgentCall, type CallWrite, type ParsedWorkflow } from './workflow-script.ts'

/** The dispatched agent one `agent()` call stands for, in the eval item's shape. */
export function callDispatch(call: AgentCall, meta: ParsedWorkflow['meta'], words: string): Dispatch {
  return {
    user_message: words,
    kind: 'workflow',
    agent_type: call.agentType,
    description: null,
    prompt: call.prompt ?? '',
    requested_model: call.model.kind === 'literal' ? call.model.value : null,
    workflow_description: meta.description,
    label: call.label,
  }
}

/** One decision request, about the items at `calls`: a script's calls by their indexes in it, an agent lane's agents by their places in its group (`agentBatches`). */
export type Batch = { request: DecisionRequest; parts: Part[]; calls: number[] }

/** Why a call is not asked about: the script builds its prompt when it runs, the script has more calls than are asked about, or its options cannot be written into. */
export type Skipped = { index: number; reason: 'unreadable' | 'capped' | 'unwritable' }

/** The part and state field of call `index`: ids in a request are unique across calls. */
function shapeOf(index: number, settings: DispatchSettings): DispatchSettings {
  return { ...settings, part: `agent-${index}`, field: `brief_${index}` }
}

/** A template needs this many tokens of words of its own, beside what `${...}` fills in, to say what the work is. */
const MIN_OWN_TOKENS = 6

/**
 * Whether the decision model can tell what a call's work is from its prompt as
 * written: a string, or a template without placeholders, is the whole task; a
 * template with placeholders must have words of its own (`${CONTEXT}\n\n${row.prompt}`
 * is a shared context and a table row, which says nothing of the work).
 * `template`: the prompt is a template literal's text as written; only then
 * is a `${` in it a placeholder.
 */
export function tellsTheWork(prompt: string | null, template = false): prompt is string {
  if (prompt === null) return false
  const pieces = template ? templatePieces(prompt) : []
  if (!pieces.some((piece) => piece.placeholder)) return true
  const own = pieces.filter((piece) => !piece.placeholder).map((piece) => piece.text).join(' ')
  return estimateTokens(own.replace(/\s+/g, ' ').trim()) >= MIN_OWN_TOKENS
}

/** At most this many calls of a script are asked about. */
const MAX_CALLS = 24
/** At most this many calls share one request: every question reads the whole state, so each brief added to it dilutes the others (guide §2.1 S5, S6). */
export const MAX_PER_REQUEST = 8
/** At most this many requests are sent for one script, one lane at a time (core/agent-lane.ts). */
const MAX_REQUESTS = 4

/** The most a hook waits for requests about agents in all: the hook has 10 seconds, and what follows them must still fit. */
export const BATCHES_BUDGET_MS = 8000
/** The briefs of a request take at least this many tokens each. */
const MIN_BRIEF = 150
/** What a brief's field adds to it as it is sent (`"brief_12":` and a comma), at most. */
const BRIEF_FIELD = 8

/**
 * What a script's requests carry beside its calls' briefs and the person's words, once in each request: the
 * background the calls were written in. Each part is left out when it is absent (with BACKEND_DEFAULTS `agentBackground`
 * off, the script and the conversation; the eval's items have neither).
 */
export type WorkflowBackground = {
  /** The script as the run has it (`workflow_script`): how its calls hang together, and the data a prompt is built from. */
  script?: string | null
  /** The conversation the Workflow was launched from (`recent_context`), oldest first, a line per message (context.ts `recentLines`). */
  recent?: readonly string[]
  /** The problem summary and the unresolved count, as a dispatched agent's request carries them: background, never a hint (#41). */
  problem_summary?: string
  unresolved_count?: number
  /** What the latest reference images of the session read as (#64): text only, in every request as `reference_complexity`, the same for every call. */
  reference_complexity?: ReferenceReading
}

/** The problem part of a background: the summary and the count. */
type ProblemBackground = Pick<WorkflowBackground, 'problem_summary' | 'unresolved_count'>

/** The problem summary and the unresolved count out of anything that holds them, as a request carries them: a field that is absent (a count of 0 too) is left out. */
export function problemFields(held: ProblemBackground | undefined): ProblemBackground {
  return {
    ...(held?.problem_summary === undefined ? {} : { problem_summary: held.problem_summary }),
    ...(held?.unresolved_count === undefined || held.unresolved_count === 0 ? {} : { unresolved_count: held.unresolved_count }),
  }
}

/**
 * The problem part of the background from the stored count and summary (`$.state` `unresolved`, #41): the summary worded for
 * the decision model, and the count while the person has said "still unresolved" at all. `held`: undefined while the
 * unresolved switch is off or nothing is stored.
 */
export function problemBackground(held: { count: number; summary?: Summary } | undefined, language: Language): ProblemBackground {
  return problemFields({
    ...(held?.summary === undefined ? {} : { problem_summary: renderSummary(held.summary, language) }),
    ...(held === undefined ? {} : { unresolved_count: held.count }),
  })
}

/** The reference reading part of the background (#64): the latest reading of the session's reference images, or nothing. */
export function readingBackground(reference: ReferenceReading | undefined): Pick<WorkflowBackground, 'reference_complexity'> {
  return reference === undefined ? {} : { reference_complexity: reference }
}

/** The state field that holds the script. */
export const SCRIPT_FIELD = 'workflow_script'
/** The script takes at most this share of a request's budget: the briefs, which the questions are about, come first. */
export const SCRIPT_SHARE = 1 / 3
/** A script cut to fit keeps this share of its budget for its end (the last calls, what it returns). */
const SCRIPT_TAIL = 0.3

/**
 * The requests that ask about the script's calls, and the calls they leave
 * out. Calls share a request while their briefs fit the state's budget
 * (`tokens`: the person's words a third at most, the briefs the rest, each
 * brief an equal share of it), their questions fit the 64 a request may hold,
 * and no more than `perRequest` do (MAX_PER_REQUEST in the mod; the eval asks
 * with 1 to compare). What does not fit in MAX_REQUESTS requests (or in
 * MAX_CALLS calls) is left out. What the briefs leave of a request's budget
 * goes to its `background`: the script (a third of the budget at most), then
 * the conversation, newest first. `written`: the decisions are for writing into
 * the script, so a call whose options cannot be edited (no object literal:
 * `agent(prompt, OPTS)`) is left out too, for its agents to be decided as they start.
 */
export function workflowBatches(
  parsed: ParsedWorkflow,
  words: string,
  settings: DispatchSettings,
  tokens: number,
  options: { perRequest?: number; background?: WorkflowBackground; written?: boolean } = {},
): { batches: Batch[]; skipped: Skipped[] } {
  const skipped: Skipped[] = []
  const readable = parsed.calls.filter((call) => {
    const tells = tellsTheWork(call.prompt, call.promptTemplate === true)
    if (!tells) skipped.push({ index: call.index, reason: 'unreadable' })
    else if (options.written === true && call.edit === null) skipped.push({ index: call.index, reason: 'unwritable' })
    return tells && !(options.written === true && call.edit === null)
  })
  if (readable.length === 0) return { batches: [], skipped }
  const items = readable.map((call): BatchItem => ({ index: call.index, dispatch: callDispatch(call, parsed.meta, words) }))
  const { batches, capped } = dispatchBatches(items, words, settings, tokens, { ...options, maxItems: MAX_CALLS, maxRequests: MAX_REQUESTS })
  for (const index of capped) skipped.push({ index, reason: 'capped' })
  return { batches, skipped: skipped.sort((a, b) => a.index - b.index) }
}

/** One agent of a request about several, by its index: its part is `agent-<index>`, its brief `brief_<index>`. */
type BatchItem = { index: number; dispatch: Dispatch }

/**
 * The requests about several agents that share the person's `words` and a `background` (a script's calls; agents that
 * start together, core/agent-lane.ts), and the items left out (`capped`). Items share a request while their briefs fit
 * the state's budget (`tokens`: the person's words a third at most, the briefs the rest, each brief an equal share of
 * it), their questions fit the 64 a request may hold, and no more than `perRequest` do (MAX_PER_REQUEST in the mod; the
 * eval asks with 1 to compare). What does not fit in `maxRequests` requests (or in `maxItems` items) is left out. What
 * the briefs leave of a request's budget goes to its `background`: the script (a third of the budget at most), then the
 * conversation, newest first.
 */
export function dispatchBatches(
  items: readonly BatchItem[],
  words: string,
  settings: DispatchSettings,
  tokens: number,
  options: { perRequest?: number; background?: WorkflowBackground; maxItems?: number; maxRequests?: number } = {},
): { batches: Batch[]; capped: number[] } {
  const perRequest = options.perRequest ?? MAX_PER_REQUEST
  const maxItems = options.maxItems ?? MAX_CALLS
  const maxRequests = options.maxRequests ?? MAX_REQUESTS
  const background = options.background ?? {}
  const capped: number[] = []
  if (items.length === 0) return { batches: [], capped }
  // The person's words as a dispatched agent's decision reads them, shared by every item, with the summary and the count.
  // Sizes are of the state as sent (field names, quotes and escapes counted), so a request's whole state keeps within `tokens`.
  const shared: State = { user_message: dispatchWords(words, tokens), ...backgroundState(background) }
  const room = Math.max(MIN_BRIEF, tokens - estimateTokens(JSON.stringify(shared)))
  // Each brief may take an equal share of a request holding as many of the items as one request holds at most:
  // all of the room for one item, an eighth of it for eight or more (less its field's name).
  const share = Math.max(MIN_BRIEF, Math.floor(room / Math.min(items.length, perRequest, maxItems)) - BRIEF_FIELD)
  type Group = { state: Record<string, unknown>; parts: Part[]; calls: number[]; used: number; questions: number }
  const groups: Group[] = []
  for (const [position, { index, dispatch }] of items.entries()) {
    if (position >= maxItems) {
      capped.push(index)
      continue
    }
    const shape = shapeOf(index, settings)
    const part = dispatchPart(dispatch, shape)
    const field = shape.field as string
    const brief = withinTokens((budget) => dispatchBrief(dispatch, budget), Math.min(share, room))
    const size = estimateTokens(JSON.stringify({ [field]: brief }))
    const questions = Object.keys(part.questions).length
    let group = groups.at(-1)
    if (group === undefined || group.calls.length >= perRequest || group.used + size > room || group.questions + questions > MAX_QUESTIONS) {
      if (groups.length >= maxRequests) {
        capped.push(index)
        continue
      }
      group = { state: {}, parts: [], calls: [], used: 0, questions: 0 }
      groups.push(group)
    }
    group.state[field] = brief
    group.parts.push(part)
    group.calls.push(index)
    group.used += size
    group.questions += questions
  }
  const batches = groups.map((group): Batch => ({ request: mergeParts(withBackground({ ...group.state, ...shared }, background, tokens), group.parts), parts: group.parts, calls: group.calls }))
  return { batches, capped }
}

/** What the agents that share requests (core/agent-lane.ts) share: the person's words and the background they were written in. */
export type AgentShared = { words: string; background: WorkflowBackground }

/**
 * The requests about agents that start together (core/agent-lane.ts), each agent's place in `dispatches` its index. One
 * dispatched agent alone is asked as one always was (`dispatchState`, part `agent` reading `brief`: the eval's request,
 * with its background); several, or a Workflow's agents, share requests as a script's calls do (`dispatchBatches`), so
 * what they share goes in once. Each dispatch is the agent's own fields; the person's words come from `shared`.
 */
export function agentBatches(kind: 'agent' | 'workflow', dispatches: readonly Dispatch[], shared: AgentShared, settings: DispatchSettings, tokens: number): Batch[] {
  const own = dispatches.map((dispatch): Dispatch => ({ ...dispatch, user_message: shared.words }))
  const alone = own[0]
  if (kind === 'agent' && own.length === 1 && alone !== undefined) {
    const { background } = shared
    const dispatch: Dispatch = {
      ...alone,
      ...problemFields(background),
      ...readingBackground(background.reference_complexity),
      ...((background.recent ?? []).length === 0 ? {} : { recent_context: background.recent }),
    }
    const part = dispatchPart(dispatch, settings)
    return [{ request: mergeParts(dispatchState(dispatch, tokens), [part]), parts: [part], calls: [0] }]
  }
  // Every agent of the group is asked about: as many requests as its briefs take, never one left out.
  const items = own.map((dispatch, index): BatchItem => ({ index, dispatch }))
  return dispatchBatches(items, shared.words, settings, tokens, { background: shared.background, maxItems: items.length, maxRequests: items.length }).batches
}

/** An agent's decision from the answers to its batch's request: `decideDispatch` on its part's answers. */
export function agentDecision(batch: Batch, at: number, answers: Readonly<Record<string, unknown>>, dispatch: Dispatch, settings: DispatchSettings): DispatchDecision | null {
  const part = batch.parts[at]
  return part === undefined ? null : decideDispatch(answersFor(part, answers), dispatch, settings)
}

/**
 * A request's state (`base`: its briefs, the person's words, the summary) with the script and the conversation in
 * what it leaves of `tokens`, the whole within `tokens` as it is sent (`withinTokens`).
 */
function withBackground(base: State, background: WorkflowBackground, tokens: number): State {
  if (!background.script && (background.recent ?? []).length === 0) return base
  return withinTokens((budget) => {
    const room = budget - estimateTokens(JSON.stringify(base))
    const script = background.script ? clipToTokens(redactSecrets(background.script), Math.min(Math.floor(budget * SCRIPT_SHARE), room), SCRIPT_TAIL) : ''
    const state: State = script === '' ? base : { ...base, [SCRIPT_FIELD]: script }
    const recent = recentWithin(background.recent ?? [], budget - estimateTokens(JSON.stringify(state)))
    return recent === '' ? state : { ...state, recent_context: recent }
  }, tokens)
}

/**
 * The requests for a script's calls (`workflowBatches`): within `budgets.one`
 * while one request holds them all; when they take several, which go out as the
 * lanes allow (core/agent-lane.ts), each within `budgets.each`, the size the
 * decision model answers several of in time (core/setup.ts BACKEND_DEFAULTS
 * `contextByKind`: `workflow` and `agent`).
 */
export function planBatches(
  parsed: ParsedWorkflow,
  words: string,
  settings: DispatchSettings,
  budgets: { one: number; each: number },
  options: { perRequest?: number; background?: WorkflowBackground; written?: boolean } = {},
): { batches: Batch[]; skipped: Skipped[] } {
  const plan = workflowBatches(parsed, words, settings, budgets.one, options)
  return plan.batches.length > 1 && budgets.each < budgets.one ? workflowBatches(parsed, words, settings, budgets.each, options) : plan
}

/** What became of one call: a model and effort written into it, the script's own choice kept, or the call left as it was. */
export type CallOutcome =
  | { kind: 'written'; decision: DispatchDecision; write: CallWrite }
  | { kind: 'kept'; decision: DispatchDecision }
  | { kind: 'left'; reason: Skipped['reason'] | 'failed' | 'unanswered'; failure?: Failure }

/** The outcome of every call of the script, from the answers to the batches (`asked`, in the batches' order). */
export function readOutcomes(parsed: ParsedWorkflow, plan: { batches: readonly Batch[]; skipped: readonly Skipped[] }, asked: readonly Asked[], words: string, settings: DispatchSettings): CallOutcome[] {
  const outcomes: CallOutcome[] = parsed.calls.map(() => ({ kind: 'left', reason: 'unanswered' }))
  for (const skip of plan.skipped) outcomes[skip.index] = { kind: 'left', reason: skip.reason }
  plan.batches.forEach((batch, b) => {
    const result = asked[b]
    batch.calls.forEach((index, k) => {
      const call = parsed.calls[index] as AgentCall
      if (result === undefined || !result.ok) {
        outcomes[index] = { kind: 'left', reason: 'failed', ...(result !== undefined && !result.ok ? { failure: result.failure } : {}) }
        return
      }
      const decision = decideDispatch(answersFor(batch.parts[k] as Part, result.answers), callDispatch(call, parsed.meta, words), shapeOf(index, settings))
      outcomes[index] = !decision.answered ? { kind: 'left', reason: 'unanswered', failure: { kind: 'parse', detail: 'no answer about the agent' } } : callOutcome(call, decision)
    })
  })
  return outcomes
}

/** What a decision made for a call comes to: a model or an effort to write into it, or the call kept as the script has it. */
export function callOutcome(call: AgentCall, decision: DispatchDecision): Extract<CallOutcome, { kind: 'written' | 'kept' }> {
  const write = writeFor(call, decision)
  return write === null ? { kind: 'kept', decision } : { kind: 'written', decision, write }
}

/** What to write into a call for its decision; null when there is nothing to write. */
function writeFor(call: AgentCall, decision: DispatchDecision): CallWrite | null {
  const write: CallWrite = {}
  // The model the script wrote stands when the decision keeps it or names the same one. One it works out when it
  // runs stands too, unless the person named a model or ruled some out: their terms win over the script's, so the
  // decided model is written in its place.
  const written = call.model.kind === 'literal' ? modelFamily(call.model.value) : null
  const overScript = call.model.kind !== 'dynamic' || decision.source === 'user' || decision.banned.length > 0
  if (decision.model !== null && overScript && decision.source !== 'requested' && decision.model !== written) write.model = decision.model
  // The effort decided replaces the script's own; one the script works out when it runs is not touched,
  // unless the person asked for an effort: that one is never overruled, whatever the script does.
  if (decision.effort !== null) {
    if (call.effort.kind === 'none' || (call.effort.kind === 'literal' && call.effort.value !== decision.effort) || (call.effort.kind === 'dynamic' && decision.effortSource === 'user')) write.effort = decision.effort
  }
  return write.model === undefined && write.effort === undefined ? null : write
}

// --- what is said about the decisions ----------------------------------------

/** How a call is named: its label, else `otherwise`. */
const labelled = (call: AgentCall, otherwise: string): string => (call.label !== null ? JSON.stringify(call.label) : otherwise)

/** How a call is named in what the main agent and the person read: its label, else where it is. */
export function callName(call: AgentCall): string {
  return labelled(call, `agent() at line ${call.line}`)
}

/** What the model and effort of a call come to: what was decided, else what the script had, else `session` (the session's model). */
function modelAndEffort(call: AgentCall, decision: DispatchDecision, session: string): string {
  const model = decision.model ?? (call.model.kind === 'literal' ? (modelFamily(call.model.value) ?? call.model.value) : session)
  return decision.effort === null ? model : `${model} ${decision.effort}`
}

/** The model and effort a call runs with, as a few words: what was decided, else what the script had. */
export function outcomeOf(call: AgentCall, decision: DispatchDecision): string {
  return modelAndEffort(call, decision, 'the session model')
}

/** A decided call as the main agent reads it: its name, the model and effort, and in brackets why. */
export function decidedLine(call: AgentCall, decision: DispatchDecision): string {
  const why = whyOf(decision)
  return `${callName(call)}: ${outcomeOf(call, decision)}${why === '' ? '' : ` (${why})`}`
}

// What the person reads of the same (the board, the decision log): Chinese. The words above are the main agent's.

/** How a call is named to the person: its label, else where it is. */
export function callTitle(call: AgentCall): string {
  return labelled(call, callPlace(call))
}

/** Where a call is, for the person: `第 3 行的 agent()`. */
export function callPlace(call: AgentCall): string {
  return `第 ${call.line} 行的 agent()`
}

/** `outcomeOf`, for the person. */
export function callResult(call: AgentCall, decision: DispatchDecision): string {
  return modelAndEffort(call, decision, '会话的模型')
}

/** Why a call is routed as it is, for the person (`dispatchReason`, a kept model being the script's). */
export function reasonOf(decision: DispatchDecision, requested: string | null, thetaOverride: number): string {
  return dispatchReason(decision, requested, thetaOverride, '脚本指定的')
}

type Left = Extract<CallOutcome, { kind: 'left' }>

/** Whether a call is left for its agents to be decided as they start: the script gives nothing to read or to write into (`unreadable`, `capped`, `unwritable`). */
export function decidedAtStart(outcome: CallOutcome): boolean {
  return outcome.kind === 'left' && (outcome.reason === 'unreadable' || outcome.reason === 'capped' || outcome.reason === 'unwritable')
}

/** The words for why a call was left as the script wrote it: for the main agent, and for the person. */
const LEFT_WORDS = {
  unreadable: { en: 'its prompt is built when the script runs', zh: '它的 prompt 要等脚本运行时才拼出来' },
  capped: { en: 'the script has more agent() calls than are asked about', zh: '脚本里的 agent() 比一次问得过来的多' },
  unwritable: { en: 'its options are no object literal, so nothing can be written into them', zh: '它的选项不是对象字面量，写不进脚本' },
  unanswered: { en: 'no answer from the decision model', zh: '决策模型没有回答' },
} as const

function leftIn(language: 'en' | 'zh', outcome: Left, describe: (failure: Failure) => string): string {
  const reason = outcome.reason === 'failed' ? 'unanswered' : outcome.reason
  return outcome.failure !== undefined && reason === 'unanswered' ? describe(outcome.failure) : LEFT_WORDS[reason][language]
}

/** Why a call was left as the script wrote it, for the main agent. */
export function leftText(outcome: Left, describe: (failure: Failure) => string): string {
  return leftIn('en', outcome, describe)
}

/** `leftText`, for the person. */
export function leftWords(outcome: Left, describe: (failure: Failure) => string): string {
  return leftIn('zh', outcome, describe)
}

/** Why a call got the model and effort it did, in a few words for the main agent: whose model it is, how sure the decision model was, how likely its effort level. */
export function whyOf(decision: DispatchDecision): string {
  const model =
    decision.source === 'user'
      ? 'model: you asked for it'
      : decision.source === 'requested'
        ? "model: the script's own kept"
        : decision.pick === null
          ? ''
          : `model: decided, confidence ${decision.pick.confidence.toFixed(2)}`
  const level = decision.effort === null ? -1 : EFFORTS.indexOf(decision.effort)
  const effort =
    decision.effort === null
      ? ''
      : decision.effortSource === 'user'
        ? 'effort: you asked for it'
        : decision.liftedFrom !== undefined
          ? `effort: ${decision.liftedFrom} lifted to ${decision.effort}, the floor for ${decision.model ?? 'its model'}`
          : decision.reading === null
            ? ''
            : `effort: p ${(decision.reading.probabilities[level] ?? 0).toFixed(2)}`
  return [model, effort].filter((part) => part !== '').join('; ')
}

/**
 * Which Workflow this is, however its options are written: its name and
 * prompts. A main agent that adds a model and effort to a script it was sent
 * back keeps both, so the second submission is recognised as the first's.
 */
export function workflowFingerprint(parsed: ParsedWorkflow): string {
  const text = [parsed.meta.name ?? '', ...parsed.calls.map((call) => call.prompt ?? '\u0000')].join('\u0001')
  // cyrb53: 53 bits of hash, plenty to tell a few Workflows of one session apart.
  let h1 = 0xdeadbeef
  let h2 = 0x41c6ce57
  for (let i = 0; i < text.length; i++) {
    const code = text.charCodeAt(i)
    h1 = Math.imul(h1 ^ code, 2654435761)
    h2 = Math.imul(h2 ^ code, 1597334677)
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909)
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909)
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36)
}

/** What the main agent is told when the Workflow is sent back: nothing ran, what to write into which call, and that the plugin asks it. */
export function returnNote(parsed: ParsedWorkflow, outcomes: readonly CallOutcome[]): string {
  const lines = outcomes.flatMap((outcome, index) => {
    if (outcome.kind !== 'written') return []
    return [`- ${callName(parsed.calls[index] as AgentCall)}: ${entriesOf(outcome.write).join(', ')}`]
  })
  return [
    "Dispatch Pilot (the user's routing plugin) did not start this Workflow. It hands the choice of each agent()'s model and effort back to you, and these are what its decision model chose:",
    ...lines,
    'Submit the same script again with these written into the options of those agent() calls (add them to the options object the call has, or give the call one). The other agent() calls need no change. The second submission runs as you write it, whatever it says.',
    "This is the routing plugin's policy, which the user set; it is not part of the script's task.",
  ].join('\n')
}

/**
 * What the main agent reads after the Workflow tool's result: a line for each
 * call the decisions touched or left. Null when there is nothing for it to
 * know: no call was decided, and none was left for a reason it could change
 * (a decision model that did not answer is the board's to report).
 */
export function rewriteNote(parsed: ParsedWorkflow, outcomes: readonly CallOutcome[], describe: (failure: Failure) => string): string | null {
  const decided = outcomes.some((outcome) => outcome.kind !== 'left')
  if (!decided && !outcomes.some(decidedAtStart)) return null
  const lines = outcomes.map((outcome, index) => {
    const call = parsed.calls[index] as AgentCall
    if (outcome.kind === 'left') return `${callName(call)}: left as written (${leftText(outcome, describe)})`
    if (outcome.kind === 'kept') return `${callName(call)}: kept as written (${outcomeOf(call, outcome.decision)})`
    return decidedLine(call, outcome.decision)
  })
  const written = outcomes.some((outcome) => outcome.kind === 'written')
  const header = written
    ? "Dispatch Pilot (the user's routing plugin) decided a model and an effort for each agent() call of this Workflow and wrote them into the script before it ran:"
    : decided
      ? "Dispatch Pilot (the user's routing plugin) checked the model and effort of the agent() calls of this Workflow; nothing needed to change:"
      : "Dispatch Pilot (the user's routing plugin) left the agent() calls of this Workflow as the script wrote them, so they run as it says:"
  return [header, ...lines.map((line) => `- ${line}`), ...(written ? ['The script file named above holds these changes. To change one, edit its model or effort there and run that file with scriptPath.'] : [])].join('\n')
}

