// The complexity reading (#63, ADR 0008): how complex it is to build what a group of reference images shows, as one Score question
// of five levels asked of Jev (or of pplx without a TypeSafe key), and what the answer is made into. The reading goes into the
// state of the effort request of a message with images (`reference_complexity`), and #64 puts the same field in the mid-turn
// re-decision, the dispatched agents' and the Workflow agents' requests. The eval's visual-check suite (#65) asks and reads the
// same way. The question is its own request, not a question beside the effort question: the questions of a request do not see
// each other's answers, and the effort question is not sensitive to images (ADR 0008).
//
// Pure (see system-one.ts): no `$`; the images arrive read and sized (core/image-files.ts).

import type { BackendName } from './backend.ts'
import { type ImageLimits, limitsFor } from './image-fit.ts'
import { imageRef, type Picture } from './images.ts'
import { answersFor, mergeParts, type Answer, type DecisionRequest, type Part, type RequestImage } from './system-one.ts'
import { requestImage } from './visual-check.ts'

/** A group is at most this many images; one that has more is read by its first ones. */
export const MAX_REFERENCE_IMAGES = 6

/** Each image is brought to at most this many pixels: a reading needs the picture's gist, and a group of six stays under 16k tokens on Jev. */
export const REFERENCE_MAX_PIXELS = 1_000_000

/** What the decision model takes of an image for a reading: its own limits, and about a megapixel at the most. */
export function complexityLimits(backend: BackendName): ImageLimits {
  return { ...limitsFor(backend), maxPixels: REFERENCE_MAX_PIXELS }
}

/**
 * The five levels, lowest first, as the decision model reads them. `en`: the question's description of the level; `summary`: the
 * level in the effort request's state. What a person reads on the card is another table (board/reference.ts).
 */
export const COMPLEXITY_LEVELS: readonly { name: string; en: string; summary: string }[] = [
  {
    name: 'trivial',
    en: 'A single plain shape or flat graphic with almost nothing to it and no fine detail, such as a plain cube, a solid-colour logo or one basic button.',
    summary: 'trivial: a single plain shape or flat graphic, no fine detail',
  },
  {
    name: 'simple',
    en: 'A few plain elements laid out simply, with little detail: a basic screen with a handful of standard controls, or an object made of a few primitive shapes.',
    summary: 'simple: a few plain elements laid out simply, little detail',
  },
  {
    name: 'moderate',
    en: 'A moderate number of distinct parts with some detail or styling: an ordinary app screen, a recognisable object of several components, or a small scene with a few materials.',
    summary: 'moderate: a moderate number of distinct parts with some detail or styling',
  },
  {
    name: 'complex',
    en: 'Many distinct parts with fine detail, layered materials, lighting or effects: a dense interface, a detailed model, or a scene with several kinds of surfaces.',
    summary: 'complex: many distinct parts with fine detail, layered materials, lighting or effects',
  },
  {
    name: 'very complex',
    en: 'A very large amount of intricate detail: a whole city or environment, an organic or highly detailed model with many parts, a scene with many interacting effects, or a screen of many interacting elements.',
    summary: 'very complex: a very large amount of intricate detail, many parts or interacting effects',
  },
]

/** The reading part's name and its one question's id: `complexity.level` in the request. */
export const COMPLEXITY_PART = 'complexity'
export const COMPLEXITY_LEVEL = 'level'

/** What the question points at in the request's state. */
const IMAGES_FIELD = 'reference_images'

/**
 * The request that reads a group of images (`pictures`, at most `MAX_REFERENCE_IMAGES`, already sized): one Score question, with
 * the images in the state under `reference_images`. Throws a RangeError for no image or for more than the most.
 */
export function complexityRequest(pictures: readonly Picture[]): { request: DecisionRequest; part: Part } {
  if (pictures.length === 0) throw new RangeError('a complexity reading needs at least one image')
  if (pictures.length > MAX_REFERENCE_IMAGES) throw new RangeError(`${pictures.length} images in one reading; at most ${MAX_REFERENCE_IMAGES}`)
  const images: RequestImage[] = pictures.map((picture, i) => requestImage(`reference-${i + 1}`, picture))
  const part: Part = {
    part: COMPLEXITY_PART,
    questions: {
      [COMPLEXITY_LEVEL]: {
        type: 'score',
        instructions: `The images in \`${IMAGES_FIELD}\` are references for something that is going to be built to match them (an interface, a 3D model, a scene, an animation). How complex is it to build it so that it matches them? Rate the work of reproducing what the images show, not how important or well known the subject is.`,
        criteria: COMPLEXITY_LEVELS.map((level) => level.en),
      },
    },
  }
  const state = { [IMAGES_FIELD]: images.map((image) => ({ image: imageRef(image.name) })) }
  return { request: { ...mergeParts(state, [part]), images }, part }
}

/** What a group of images reads as: the level, 0 (trivial) to 4 (very complex), and how many images it was read from. */
export type ReferenceReading = { level: number; images: number }

/**
 * The reading an answer gives: the expected level (the probabilities of the five levels weighed by their level, normalised)
 * rounded to a whole level. The expectation, not the most likely level: it moves smoothly from one picture to the next, and the
 * measured readings (a cube 0.14, a sea 1.77, a city 3.14) came out in order that way. Null when the answer is missing, is not
 * a Score or puts no probability on any level.
 */
export function readComplexity(part: Part, answers: Readonly<Record<string, unknown>>, images: number): ReferenceReading | null {
  const answer: Answer | undefined = answersFor(part, answers)[COMPLEXITY_LEVEL]
  if (answer === undefined || answer.type !== 'score') return null
  const raw = COMPLEXITY_LEVELS.map((_, i) => answer.probabilities[String(i)] ?? 0)
  const sum = raw.reduce((a, b) => a + b, 0)
  if (!(sum > 0)) return null
  const expected = raw.reduce((total, p, i) => total + (p / sum) * i, 0)
  return { level: Math.min(COMPLEXITY_LEVELS.length - 1, Math.max(0, Math.round(expected))), images }
}

/** The effort request's state field (and the mid-turn re-decision's, the dispatched agent's, ...) that carries a reading. */
export const REFERENCE_FIELD = 'reference_complexity'

/** What the decision model is told of a reading, in the field `REFERENCE_FIELD`. A hint for the question, never a level the answer is to take. */
export function referenceState(reading: ReferenceReading): Record<string, unknown> {
  const level = COMPLEXITY_LEVELS[reading.level]
  return { level: reading.level, scale: '0 (trivial) to 4 (very complex)', description: level?.summary ?? `level ${reading.level}`, images: reading.images }
}

/** The request state's field for a reading, or nothing when there is none (to spread into a state: `...referenceField(reading)`). */
export function referenceField(reading: ReferenceReading | null | undefined): Record<string, unknown> {
  return reading === undefined || reading === null ? {} : { [REFERENCE_FIELD]: referenceState(reading) }
}

/** Lowercase hexadecimal of bytes. */
const hex = (bytes: ArrayBuffer): string => [...new Uint8Array(bytes)].map((byte) => byte.toString(16).padStart(2, '0')).join('')

async function sha256(text: string): Promise<string> {
  return hex(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text)))
}

/**
 * What names a group of images: a hash of their content, the same whatever order they come in. The same pictures read once
 * (the reading is kept under this key); an image changed, added or left out is another group. 16 hexadecimal digits.
 */
export async function referenceKey(images: readonly { base64: string }[]): Promise<string> {
  const each = await Promise.all(images.map((image) => sha256(image.base64)))
  return (await sha256(each.sort().join('\n'))).slice(0, 16)
}

files.hooks/core/call-budget.ts:
// The time one tool call may spend waiting on the decision model (ADR 0007). A hook has 10 seconds, and a `$.clock.sleep` counts toward
// them (`$.http.fetch` and `$.process.run` do not), but a request waits for its answer on a sleep (decision/backend.ts `within`). So a call
// that sends one request after another (the whole images, then the crops of the zoomed re-check, a series' waves) could add up to more
// than the hook has, and be dropped with nothing answered. The requests of one call share a budget instead: each waits at most its own
// limit, and no longer than what is left; with too little left the request is not sent.
//
// Time is counted as the time at least one request has been waiting, because that is what the sleeps add up to: requests that wait
// together (the pairs of a series' wave) cost it once, and the sips and ffmpeg runs between them cost nothing. That the engine counts
// overlapping sleeps this way is the same assumption features/image-routing.ts makes of its two requests; it was not measured.
//
// Pure (see system-one.ts): the clock is a closure.

/** What the requests of one call may wait in all: the hook's 10 seconds, less one for the rest of its work (image-routing's effort request shares it). */
export const CALL_ROOM_MS = 9000

/** A request with less time than this is not sent: Jev's own wait beside a message is 1.5 seconds, and a request with images takes longer. */
const LEAST_REQUEST_MS = 1500

export type CallBudget = {
  /**
   * Runs `request` with the time it may wait: `limitMs`, or what is left of the call's room when that is less. With less than
   * `LEAST_REQUEST_MS` left it is not run and `unsent` is the result.
   */
  run: <T>(limitMs: number, request: (waitMs: number) => Promise<T>, unsent: T) => Promise<T>
}

/** A budget of `CALL_ROOM_MS` for one call; `now` is the clock (`$.clock.now()`). */
export function callBudget(now: () => Promise<number>): CallBudget {
  let waiting = 0
  let since = 0
  let used = 0
  return {
    async run(limitMs, request, unsent) {
      const at = await now()
      const left = CALL_ROOM_MS - used - (waiting > 0 ? at - since : 0)
      if (left < LEAST_REQUEST_MS) return unsent
      if (waiting++ === 0) since = at
      try {
        return await request(Math.min(limitMs, left))
      } finally {
        const end = await now()
        if (--waiting === 0) used += end - since
      }
    },
  }
}

files.hooks/core/complexity.ts:
// Reading a group of reference images, and keeping the readings (#63, ADR 0008). The one place that gets "the complexity reading of
// these images": features/image-routing.ts calls it (for the message that starts a turn, and for the images the main agent meets,
// #64), without knowing how the images are prepared, asked or kept. A group of images is read once: the readings are kept in
// `$.state` (`referenceReadings`) under a hash of the images' content, the latest of them is what a request that carries no images
// of its own (an agent's, a Workflow batch's) takes (`latestReading`, through features/reference-hint.ts).
//
// Pure of `$`: the engine comes in as closures (`ComplexityIo`), as for `BackendIo` and `ImageFilesIo`; a module cannot pass `$`
// across an import, so every caller builds the closures from its own `$`.

import { errorText, failureText, type Asked, type BackendName, type Failure } from '../decision/backend.ts'
import { complexityLimits, complexityRequest, MAX_REFERENCE_IMAGES, readComplexity, referenceKey, type ReferenceReading } from '../decision/complexity.ts'
import { readImageHeader } from '../decision/image-header.ts'
import type { DecisionRequest } from '../decision/system-one.ts'
import { type ImageFilesIo, type Loaded, type LoadedImage, loadImage } from './image-files.ts'
import { type Cell, update } from './plans.ts'

/** A reading as it is kept: the group's key (a hash of the images' content), the reading, and when (`$.clock.now()`, ms) it was asked or last reused. */
export type KeptReading = ReferenceReading & { key: string; at: number }

/** What `$.state` keeps under `referenceReadings`: the latest groups' readings, the one asked or reused last at the end. */
export type ReferenceReadings = KeptReading[]

/** The readings of this many groups are kept: a conversation moves from one reference to the next. */
const READINGS_KEPT = 8

/**
 * An image to read. `path`: a file (a pasted image's original, a file the agent read). `base64`: the bytes of a PNG or a JPEG the
 * engine handed over without a file (a pasted image's block), written to a file first.
 */
export type ReferenceSource = { path: string } | { base64: string }

/** What a reading needs of the engine. */
export type ComplexityIo = {
  files: ImageFilesIo
  /** One request to the decision model that takes images (`ctx.images.backend`), timed and logged by the caller; it never throws. */
  ask: (request: DecisionRequest) => Promise<Asked>
  /** `$.state` key `referenceReadings`. */
  store: Cell<ReferenceReadings>
  now: () => Promise<number>
  /** The decision model `ask` goes to: it sets the limits the images are brought within. */
  backend: BackendName
  /** A line for the debug log. */
  debug?: (line: string) => void
}

export type ReadingResult =
  /** `cached`: this group had been read; no request was made. */
  | { ok: true; reading: ReferenceReading; key: string; cached: boolean }
  /** `failure`: the request failed (the board says why); absent when no request was made (no image could be read, the answer had no level). */
  | { ok: false; reason: string; failure?: Failure }

/** The reading of the latest group asked or reused; null before any. */
export async function latestReading(store: Pick<Cell<ReferenceReadings>, 'get'>): Promise<ReferenceReading | null> {
  const latest = ((await store.get()).value ?? []).at(-1)
  return latest === undefined ? null : { level: latest.level, images: latest.images }
}

/** The images of `sources` (the first `MAX_REFERENCE_IMAGES`), each brought to about a megapixel and within the model's limits; those that cannot be, with why. */
async function prepare(io: ComplexityIo, sources: readonly ReferenceSource[]): Promise<{ images: LoadedImage[]; reasons: string[] }> {
  const images: LoadedImage[] = []
  const reasons: string[] = []
  for (const source of sources.slice(0, MAX_REFERENCE_IMAGES)) {
    const loaded = await load(io, source)
    if (loaded.ok) images.push(loaded.image)
    else reasons.push(loaded.reason)
  }
  return { images, reasons }
}

async function load(io: ComplexityIo, source: ReferenceSource): Promise<Loaded> {
  try {
    const limits = complexityLimits(io.backend)
    if ('path' in source) return await loadImage(io.files, source.path, limits)
    const header = readImageHeader(source.base64)
    if (header === null) return { ok: false, reason: 'an image the engine handed over is not a PNG or a JPEG' }
    // macOS's base64 decodes its standard input into the file named by -o; the engine's `$.fs.write` writes text only.
    const file = await io.files.newFile(header.format === 'jpeg' ? 'jpg' : 'png')
    const wrote = await io.files.run(['base64', '-D', '-o', file], { stdin: source.base64 })
    if (wrote.exitCode !== 0) return { ok: false, reason: `an image the engine handed over could not be written to a file (exit code ${wrote.exitCode})` }
    return await loadImage(io.files, file, limits)
  } catch (error) {
    return { ok: false, reason: errorText(error) }
  }
}

/**
 * The complexity reading of a group of reference images. The images are prepared first (sips: about a megapixel each, within the
 * model's limits), because a group is recognised by the content it is sent with: one that was read before is answered from the
 * readings kept, without a request; any other is one request to the decision model that takes images. A group of more than six is
 * read by its first six. Never throws: whatever goes wrong is a `reason`.
 */
export async function readReferenceComplexity(io: ComplexityIo, sources: readonly ReferenceSource[]): Promise<ReadingResult> {
  try {
    if (sources.length === 0) return { ok: false, reason: 'no reference image to read' }
    const { images, reasons } = await prepare(io, sources)
    if (images.length === 0) return { ok: false, reason: reasons.join('; ') }
    if (reasons.length > 0) io.debug?.(`reference images left out of the reading: ${reasons.join('; ')}`)
    const key = await referenceKey(images)
    const now = await io.now()

    const kept = (await io.store.get()).value ?? []
    const hit = kept.find((reading) => reading.key === key)
    if (hit !== undefined) {
      await remember(io, { ...hit, at: now })
      return { ok: true, reading: { level: hit.level, images: hit.images }, key, cached: true }
    }

    const { request, part } = complexityRequest(images)
    const asked = await io.ask(request)
    if (!asked.ok) return { ok: false, reason: failureText(io.backend, asked.failure), failure: asked.failure }
    const reading = readComplexity(part, asked.answers, images.length)
    if (reading === null) return { ok: false, reason: `${io.backend}: the answer had no complexity level` }
    await remember(io, { ...reading, key, at: now })
    return { ok: true, reading, key, cached: false }
  } catch (error) {
    return { ok: false, reason: errorText(error) }
  }
}

/** The reading kept as the latest (a store that cannot be written does not lose the reading itself: the next group is asked again). */
async function remember(io: ComplexityIo, reading: KeptReading): Promise<void> {
  try {
    await update(io.store, (list) => [...(list ?? []).filter((other) => other.key !== reading.key), reading].slice(-READINGS_KEPT))
  } catch (error) {
    io.debug?.(`reference reading not kept: ${errorText(error)}`)
  }
}

files.hooks/core/deferred.ts:
// The effort question of a message with reference images, held back until its turn starts (#63, ADR 0008). The message's decision
// is made at `turn.start`, after its images have been read (features/image-routing.ts): the main-effort feature leaves the
// effort part out of the message's ballot (core/ballot.ts) and hands it here instead, as a function from the reading to the
// part, so that the part is built with the reading in its state and its report. The image-routing feature takes it at the turn's
// start, asks it through the core's `askGroups`, and the answer is written as a pending decision, which the core claims in the same
// `turn.start` as for any other message: the plan table keeps its one writer (ADR 0003).
//
// Pure module state, like the ballot: lost on a hot reload, which only costs the decision of a message submitted during that
// reload (its turn goes out unrouted).

import type { ReferenceReading } from '../decision/complexity.ts'
import { keepNewest } from '../decision/keep-newest.ts'
import type { Contribution } from './ballot.ts'

/** A message's effort part, to be built once its images' reading is known (null: it could not be read, or was not asked for). */
export type Deferred = (reading: ReferenceReading | null) => Contribution

const waiting = new Map<string, Deferred>()
/** Parts nobody took (a message that never started a turn) stop piling up here. */
const MOST_WAITING = 8

/** The message with this text waits for its turn to start before its effort is decided. */
export function defer(prompt: string, deferred: Deferred): void {
  waiting.delete(prompt)
  waiting.set(prompt, deferred)
  keepNewest(waiting, MOST_WAITING)
}

/** The message was refused beneath, or is not waiting for a turn after all. */
export function withdraw(prompt: string): void {
  waiting.delete(prompt)
}

/** Takes the part of the message the turn that starts is for: the first of `texts` that has one. */
export function takeDeferred(texts: readonly string[]): { prompt: string; deferred: Deferred } | null {
  for (const text of texts) {
    const deferred = waiting.get(text)
    if (deferred !== undefined) {
      waiting.delete(text)
      return { prompt: text, deferred }
    }
  }
  return null
}

files.hooks/core/image-files.ts:
// Image files for the features that send images to a decision model (#57, ADR 0008): finding an image's size and format with
// sips, bringing it within a model's limits, reading it as bytes. Written for every feature that needs images (visual_check, the
// zoomed re-check, the frames of a recording, the complexity reading), so it keeps no state of its own and asks for nothing but
// the closures of an `ImageFilesIo`: like BackendIo, they are built where `$` is (a module cannot pass `$` across imports).

import { errorText } from '../decision/backend.ts'
import { fits, type ImageLimits, planSize, turnsSides, uprightArgs } from '../decision/image-fit.ts'
import { readImageHeader } from '../decision/image-header.ts'
import type { Picture } from '../decision/images.ts'

/** What a program run gives back (`$.process.run`). */
type ProcessOutput = { exitCode: number; stdout: string; stderr: string }

/** What a program may be run with besides its arguments (`$.process.run`'s `init`; the 30 second default of a run is long enough for sips, not for ffmpeg). */
type ProcessInit = { stdin?: string; timeoutMs?: number }

/**
 * What the image functions need of the engine. All reject when the engine cannot do it (`run` outside the CLI, `readBytes` for a
 * file that is missing or over 4 MiB).
 */
export type ImageFilesIo = {
  /** `$.process.run(argv, init)`: a program by its argument vector, no shell. */
  run(argv: readonly string[], init?: ProcessInit): Promise<ProcessOutput>
  /** `$.fs.read(path, { as: 'bytes' })`: the file's bytes as base64. */
  readBytes(path: string): Promise<string>
  /** The path of a new file for a derived image, in the session's temporary directory (which exists by then). */
  newFile(extension: string): Promise<string>
}

/**
 * An image ready to send. `file` is the one whose bytes `base64` holds, at the size `width` by `height` and upright (the file it
 * came from when nothing had to be done to it), for what is done to the image further (the zoomed re-check crops from it).
 */
export type LoadedImage = Picture & { file: string }

/** An image loaded, or why it could not be (written for the model, in English). */
export type Loaded = { ok: true; image: LoadedImage } | { ok: false; reason: string }

/** What sips says of an image. */
type ImageInfo = { width: number; height: number; format: string }

/** A path as an argument of a program: one that starts with a dash is not taken for an option (the path is the model's). */
export const asArgument = (path: string): string => (path.startsWith('-') ? `./${path}` : path)

/** The first line of what a program said, for a reason. */
const firstLine = (text: string): string => text.trim().split('\n')[0]?.slice(0, 200) ?? ''

/** Why a program run failed, for a reason: the exit code and the first line it said. */
export const failedRun = (run: ProcessOutput): string => `exit code ${run.exitCode}: ${firstLine(run.stderr) || firstLine(run.stdout) || 'no message'}`

/** The size and format of an image file, or why sips could not read it. */
async function inspect(io: ImageFilesIo, path: string): Promise<{ ok: true; info: ImageInfo } | { ok: false; reason: string }> {
  const { stdout } = await io.run(['sips', '-g', 'pixelWidth', '-g', 'pixelHeight', '-g', 'format', asArgument(path)])
  const width = Number(/pixelWidth: (\d+)/.exec(stdout)?.[1])
  const height = Number(/pixelHeight: (\d+)/.exec(stdout)?.[1])
  const format = /format: (\S+)/.exec(stdout)?.[1]
  if (!(width > 0) || !(height > 0) || format === undefined) return { ok: false, reason: `${path} is not an image sips can read (is the path right?)` }
  return { ok: true, info: { width, height, format } }
}

/** The format an image is sent in when it is not a PNG or a JPEG already: photographic formats become JPEG, the rest PNG. */
function formatFor(format: string): 'png' | 'jpeg' {
  return format === 'png' || format === 'jpeg' ? format : /^(heic|heif|jp2|dng|raw)$/.test(format) ? 'jpeg' : 'png'
}

/** A way to bring the file to what the request sends: in this format, at this share of the size the limits allow. */
type Attempt = { format: 'png' | 'jpeg'; share: number }

/**
 * The file at `path` as an image within `limits`, read as bytes. An image that fits and is a PNG or a JPEG is read as it is;
 * any other is made by sips into a new file (scaled to fit, converted). The engine reads at most 4 MiB: when a read is refused,
 * the image is made smaller: first as a JPEG, then at three quarters and then at half the size. `share`: the share of its size to
 * bring it to, within the limits (1 for the whole size).
 */
export async function loadImage(io: ImageFilesIo, path: string, limits: ImageLimits, share = 1): Promise<Loaded> {
  let inspected: Awaited<ReturnType<typeof inspect>>
  try {
    inspected = await inspect(io, path)
  } catch (error) {
    return loadWithoutSips(io, path, limits, errorText(error))
  }
  if (!inspected.ok) return inspected
  const { width, height, format } = inspected.info
  const wanted = formatFor(format)
  const attempts: Attempt[] = ([
    { format: wanted, share },
    { format: 'jpeg', share },
    { format: 'jpeg', share: share * 0.75 },
    { format: 'jpeg', share: share * 0.5 },
  ] as Attempt[]).filter((attempt, i, all) => all.findIndex((other) => other.format === attempt.format && other.share === attempt.share) === i)
  let refused = ''
  for (const attempt of attempts) {
    // A share is of the size the limits allow the image (#60: an image over a limit, as a frame of a recording is, would otherwise
    // come to more than its share of a budget), and a share can still be too small for the limits: it is then the smallest that fits.
    const whole = planSize(width, height, limits)
    if (!whole.ok) return { ok: false, reason: `${path}: ${whole.reason}` }
    const size = attempt.share === 1 ? whole : planSize(Math.round(whole.width * attempt.share), Math.round(whole.height * attempt.share), limits)
    if (!size.ok) return { ok: false, reason: `${path}: ${size.reason}` }
    let file = path
    const resize = size.width !== width || size.height !== height
    const convert = attempt.format !== format
    if (resize || convert) {
      file = await io.newFile(attempt.format === 'jpeg' ? 'jpg' : 'png')
      const run = await io.run(['sips', ...(resize ? ['-z', String(size.height), String(size.width)] : []), ...(convert ? ['-s', 'format', attempt.format] : []), ...(attempt.format === 'jpeg' && convert ? ['-s', 'formatOptions', '85'] : []), asArgument(path), '--out', file])
      if (run.exitCode !== 0) return { ok: false, reason: `sips could not prepare ${path} (${failedRun(run)})` }
    }
    try {
      let base64 = await io.readBytes(file)
      let [wide, high] = [size.width, size.height]
      let readFrom = file
      // Jev does not apply a JPEG's EXIF orientation, and sips cannot tell it: the tag is read out of the bytes, and the pixels turned.
      const orientation = attempt.format === 'jpeg' ? (readImageHeader(base64)?.orientation ?? 1) : 1
      if (orientation > 1) {
        const upright = await io.newFile('jpg')
        const turned = await io.run(['sips', ...uprightArgs(orientation), asArgument(file), '--out', upright])
        if (turned.exitCode !== 0) return { ok: false, reason: `sips could not turn ${path} upright (${failedRun(turned)})` }
        base64 = await io.readBytes(upright)
        readFrom = upright
        if (turnsSides(orientation)) [wide, high] = [high, wide]
      }
      return { ok: true, image: { file: readFrom, format: attempt.format, base64, width: wide, height: high } }
    } catch (error) {
      refused = errorText(error)
    }
  }
  return { ok: false, reason: `${path} could not be read: ${refused}` }
}

/**
 * Several images for one request, each as `loadImage` loads it, in the order of `paths`. With a budget of `megapixels` in all
 * (`imageMegapixelBudget`): when the images come to more, they are all loaded again at the one share that brings them to it.
 * A request's images cost tokens by their pixels; a budget cannot go below the smallest size the limits allow.
 */
export async function loadImages(io: ImageFilesIo, paths: readonly string[], limits: ImageLimits, megapixels?: number): Promise<Loaded[]> {
  const loaded: Loaded[] = []
  for (const path of paths) loaded.push(await loadImage(io, path, limits))
  if (megapixels === undefined) return loaded
  const pixels = loaded.reduce((sum, one) => sum + (one.ok ? one.image.width * one.image.height : 0), 0) / 1_000_000
  if (pixels <= megapixels || loaded.some((one) => !one.ok)) return loaded
  // A little under, so that the rounding of each side does not leave the total over the budget.
  const share = Math.sqrt(megapixels / pixels) * 0.98
  const smaller: Loaded[] = []
  for (const path of paths) smaller.push(await loadImage(io, path, limits, share))
  return smaller
}

/** What `loadAll` comes to: all the images, or why not, with the first image when that one was got (to hand back to look at). */
export type LoadedAll = { ok: true; images: LoadedImage[] } | { ok: false; reason: string; first: LoadedImage | null }

/** `loadImages`, read as a whole: every image, or the reason of the first that could not be had (a throw is a reason too). Never throws. */
export async function loadAll(io: ImageFilesIo, paths: readonly string[], limits: ImageLimits, megapixels?: number): Promise<LoadedAll> {
  let loaded: Loaded[]
  try {
    loaded = await loadImages(io, paths, limits, megapixels)
  } catch (error) {
    return { ok: false, reason: errorText(error), first: null }
  }
  const head = loaded[0]
  const first = head?.ok === true ? head.image : null
  const broken = loaded.find((one) => !one.ok)
  if (broken !== undefined && !broken.ok) return { ok: false, reason: broken.reason, first }
  return { ok: true, images: loaded.flatMap((one) => (one.ok ? [one.image] : [])) }
}

/**
 * Where sips cannot run (outside the CLI): a PNG or a JPEG that already fits, and is upright, is read as it is, its size from its
 * own header; any other cannot be sized or converted, and the reason says so. `why`: what the engine said of running sips.
 */
async function loadWithoutSips(io: ImageFilesIo, path: string, limits: ImageLimits, why: string): Promise<Loaded> {
  let base64: string
  try {
    base64 = await io.readBytes(path)
  } catch (error) {
    return { ok: false, reason: `${path} could not be read: ${errorText(error)}` }
  }
  const header = readImageHeader(base64)
  if (header === null) return { ok: false, reason: `${path} is not a PNG or a JPEG, and sips could not run to convert it (${why})` }
  if (!fits(header.width, header.height, limits)) return { ok: false, reason: `${path} is ${header.width}x${header.height}, which the decision model does not take, and sips could not run to resize it (${why})` }
  if (header.orientation > 1) return { ok: false, reason: `${path} lies on its side by its EXIF orientation, which the decision model does not apply, and sips could not run to turn it upright (${why})` }
  return { ok: true, image: { file: path, format: header.format, base64, width: header.width, height: header.height } }
}

files.hooks/core/work-files.ts:
// The mod's temporary directory (#62, spec #55): `$TMPDIR/dispatch-pilot/<session id>/`, one subdirectory for each session. The
// images the mod makes (a scaled or converted copy, a frame of a recording, a screenshot the takeover keeps from an MCP tool's
// result) are files in it, named by number; nothing in it is needed once the session is over, and the directory is not cleaned
// up (the system empties its temporary directory). Like the other modules that touch the world, it asks for closures only: a
// module cannot pass `$` across an import.

/** What the temporary directory needs of the engine. */
export type WorkFilesIo = {
  /** `$.process.run(argv)`: rejects outside the CLI. */
  run(argv: readonly string[]): Promise<unknown>
  /** `$.env.get('TMPDIR')` (the call spells the name out): rejects when the engine will not tell. */
  tmpdir(): Promise<string | undefined>
  /** `$.session.id()`. */
  sessionId(): Promise<string>
}

/** The session's directory, made, by session id (module level: a hot reload loses it, at the cost of one `mkdir -p` more). */
const made = new Map<string, Promise<string>>()
/** Told from the files an earlier load of the module made, which a hot reload leaves in the same directory. */
let stamp: string | undefined
let count = 0

/** A session id as a directory's name: letters, digits, `_` and `-`. */
const nameOf = (id: string): string => id.replace(/[^A-Za-z0-9_-]/g, '_').slice(0, 80) || 'session'

/** The path of a new file with this extension in the session's directory, which exists by then. Rejects when it cannot be made. */
export async function newWorkFile(io: WorkFilesIo, extension: string): Promise<string> {
  stamp ??= Math.floor(Math.random() * 0xffffff).toString(36)
  const session = nameOf(await io.sessionId().catch(() => `unknown-${stamp}`))
  let dir = made.get(session)
  if (dir === undefined) {
    dir = (async () => {
      const base = ((await io.tmpdir().catch(() => undefined)) ?? '').trim() || '/tmp'
      const path = `${base.replace(/\/+$/, '')}/dispatch-pilot/${session}`
      await io.run(['mkdir', '-p', path])
      return path
    })().catch((error: unknown) => {
      // Not made (no CLI, a full disk): the next file tries again.
      made.delete(session)
      throw error
    })
    made.set(session, dir)
  }
  return `${await dir}/image-${stamp}-${++count}.${extension}`
}

files.hooks/decision/turn-start.ts:
// The part of a message's decision request that is the main agent's effort: the
// effort question, the unresolved-count question beside it, and the fields they
// read beside the conversation (a command turn's command, the problem summary).
// The mod's main-effort feature puts it in the ballot and the eval builds it for
// every item it asks, so the two ask the same thing (ADR 0005).
//
// Pure (see system-one.ts).

import { referenceField, type ReferenceReading } from './complexity.ts'
import { estimateTokens, turnStartState, type ContextLimits, type ContextMessage } from './context.ts'
import { DEFAULT_ASK, turnStartEffortPart, type EffortAsk } from './effort.ts'
import { renderSummary, SUMMARY_FIELD, type Summary } from './summary.ts'
import { mergeParts, type DecisionRequest, type Part } from './system-one.ts'
import { COUNT_FIELD, givesHint, withHint, withUnresolved } from './unresolved.ts'

/** The state's budget is never cut below this many tokens by what the parts add to it. */
const LEAST_STATE = 100

/**
 * The decision request of a message: the state of `turnStartState` and the parts' questions and fields. What the parts
 * add to the state (a command turn's command, the problem summary) is counted in `limits.tokens`, so the whole state, as
 * it is sent, stays within it: the conversation gives way to those fields, never the message (a decision model may read only the head
 * of a long state, with its keys sorted).
 */
export function messageRequest(input: { prompt: string; messages: readonly ContextMessage[]; limits: ContextLimits; parts: readonly Part[] }): DecisionRequest {
  const added = Object.assign({}, ...input.parts.map((part) => part.state ?? {})) as Record<string, unknown>
  const room = Object.keys(added).length === 0 ? input.limits.tokens : Math.max(LEAST_STATE, input.limits.tokens - estimateTokens(JSON.stringify(added)))
  return mergeParts(turnStartState({ prompt: input.prompt, messages: input.messages, limits: { ...input.limits, tokens: room } }), input.parts)
}

export type TurnStartPartInput = {
  /** How the effort question is asked; the unresolved question and the summary are written in its language. */
  ask?: Partial<EffortAsk>
  /** Whether the unresolved question is asked beside the effort question (the person's own message, the switch on). */
  unresolved?: boolean
  /** A command turn's command, as `core/commands.ts` words it: what the command is for. */
  command?: Readonly<Record<string, string>> | null
  /** The problem summary the decision model reads from this message on; none when there is none yet or the switch is off. */
  summary?: Summary | null
  /** How many times the person has said the problem is still unresolved, before this message; the state carries it from the first on. */
  count?: number
  /** The count from which the effort question has the strong hint (`unresolvedMaxAfter`; 0 or none: never). */
  maxAfter?: number
  /** What the reference images the message came with read as (#63): in the state as `reference_complexity`, a hint for the effort question, which is not changed. */
  reference?: ReferenceReading | null
}

/**
 * The effort part, still named `effort` (so that it goes in the effort request, which has a state budget of its own,
 * `contextByKind.messagePlain`): its questions, and the state fields beyond `user_message` and `recent_context` that they read.
 */
export function turnStartPart(input: TurnStartPartInput = {}): Part {
  const ask = { ...DEFAULT_ASK, ...input.ask }
  const part = turnStartEffortPart(ask)
  const count = input.count ?? 0
  const asked = input.unresolved === true ? withUnresolved(part, ask.language) : part
  // With the three-way question in the request, the hinted effort question goes beside the plain one: its answer is used
  // only when the same request says the problem is still unresolved (decision/unresolved.ts HINTED).
  const questions = givesHint(count, input.maxAfter ?? 0) ? withHint(asked, ask.language, { beside: input.unresolved === true }) : asked
  const state: Record<string, unknown> = {
    ...(input.command === undefined || input.command === null ? {} : { command: input.command }),
    ...(input.summary === undefined || input.summary === null ? {} : { [SUMMARY_FIELD]: renderSummary(input.summary, ask.language) }),
    ...(count > 0 ? { [COUNT_FIELD]: count } : {}),
    ...referenceField(input.reference),
  }
  return Object.keys(state).length === 0 ? questions : { ...questions, state }
}

files.hooks/core/unresolved.ts:
// The unresolved count and the problem summary that goes with it: the one module
// that writes them (`$.state` `unresolved`; GLOSSARY 未解决次数, 问题摘要, ADR 0005).
// The main-effort feature moves the count by each message's answer; the unresolved
// feature starts it over when the conversation ends and keeps the summary (a cheap
// model writes it after each of the person's turns, in the background). They only
// count and record; both are a basis for the decision model's judgment of effort,
// never a rule.
//
// The summary starts over wherever the count does: the problem is solved, another
// one begins, `/clear`, a new session. A write of it that is still going on then
// is dropped when it lands (its turn is no longer in `writing`).
//
// Cells come in as closures (a `$` cannot cross a file), like the plan table's.

import { countAfter, UNRESOLVED_OPTIONS, type UnresolvedJudgement, type UnresolvedOption } from '../decision/unresolved.ts'
import { markLast, SUMMARY_TIMEOUT_MS, type Summary } from '../decision/summary.ts'
import { replace, update, type Cell } from './plans.ts'
import type { Effort } from '../decision/effort.ts'
import type { Decided, HintRecord, UnresolvedRecord } from './report.ts'

/** The summary as it is kept: the turn it was last written for beside it. */
export type StoredSummary = Summary & { turn: string }

/** What `$.state` `unresolved` holds. */
export type UnresolvedState = {
  count: number
  summary?: StoredSummary
  /** The turns whose summaries are queued or being written, oldest first. */
  writing?: string[]
  /** The turn whose summary, once written, has its last attempt marked unresolved. */
  owed?: string
}

/** The stored count and summary (`$.state` `unresolved`). */
export type CountCell = Cell<UnresolvedState>

/** What the log and the card call the three options. */
export const OPTION_WORDS: Readonly<Record<UnresolvedOption, string>> = {
  still_unresolved: '仍未解决',
  resolved: '已经解决',
  new_or_unrelated: '新问题或无关',
}

/**
 * The state after one more message that said "still unresolved": the count up by one, and the last attempt of the
 * summary marked unresolved, or, when a write of the newest turn's summary is still going on (the summary does not
 * yet hold the attempt the message is about), marked once that write lands.
 */
function oneMore(current: UnresolvedState | undefined): UnresolvedState {
  const state = current ?? { count: 0 }
  const next: UnresolvedState = { ...state, count: state.count + 1 }
  const newest = state.writing?.at(-1)
  if (newest !== undefined) return { ...next, owed: newest }
  if (state.summary !== undefined) next.summary = { ...markLast(state.summary), turn: state.summary.turn }
  return next
}

/** The count before and after a change (a change that leaves it as it was is not written); a clear takes the summary too. */
export async function moveCount(cell: CountCell, change: UnresolvedJudgement['change']): Promise<{ before: number; count: number }> {
  if (change === 'keep') {
    const count = await keptCount(cell)
    return { before: count, count }
  }
  const { before, after } = await replace(cell, (current) => (change === 'add' ? oneMore(current) : { count: countAfter(current?.count ?? 0, change) }))
  return { before: before?.count ?? 0, count: after.count }
}

/** A conversation that ends (`/clear`, a new session) starts the count and the summary over. */
export async function clearCount(cell: CountCell): Promise<void> {
  await update(cell, () => ({ count: 0 }))
}

/** The count the session holds now (0 when none): what the effort request carries, and what the strong hint is given at. */
export async function keptCount(cell: CountCell): Promise<number> {
  return (await cell.get()).value?.count ?? 0
}

/** The summary, when there is one: what the effort request carries. */
export async function keptSummary(cell: CountCell): Promise<StoredSummary | null> {
  return (await cell.get()).value?.summary ?? null
}

/** A turn of the person's ended: its summary is to be written. */
export async function queueSummary(cell: CountCell, turn: string): Promise<void> {
  await update(cell, (current) => {
    const state = current ?? { count: 0 }
    return { ...state, writing: [...(state.writing ?? []).filter((queued) => queued !== turn), turn] }
  })
}

/** What a write that starts now continues: whether its turn is still wanted (a clear since would have taken it out), and the summary so far. */
export async function summaryFor(cell: CountCell, turn: string): Promise<{ wanted: boolean; previous: StoredSummary | null }> {
  const state = (await cell.get()).value
  return { wanted: state?.writing?.includes(turn) === true, previous: state?.summary ?? null }
}

/** `state` with the turns still being written and the turn owed a mark set as given; each is left out of it when there is none. */
function withWriting(state: UnresolvedState, writing: readonly string[], owed: string | undefined): UnresolvedState {
  const next: UnresolvedState = { ...state }
  delete next.writing
  delete next.owed
  if (writing.length > 0) next.writing = [...writing]
  if (owed !== undefined) next.owed = owed
  return next
}

/** A write of `turn`'s summary ended without a summary (or is no longer wanted): it is off the list, and nothing is owed to it. */
export async function dropSummary(cell: CountCell, turn: string): Promise<void> {
  await update(cell, (current) => {
    if (current === undefined) return { count: 0 }
    return withWriting(current, (current.writing ?? []).filter((queued) => queued !== turn), current.owed === turn ? undefined : current.owed)
  })
}

/**
 * `turn`'s summary was written. It is kept (its last attempt marked unresolved when a message said so while it was
 * being written) unless the write is no longer wanted: false then.
 */
export async function landSummary(cell: CountCell, turn: string, summary: Summary): Promise<boolean> {
  const { before } = await replace(cell, (current) => {
    if (current === undefined || current.writing?.includes(turn) !== true) return current ?? { count: 0 }
    const { writing, owed } = current
    return withWriting({ ...current, summary: { ...(owed === turn ? markLast(summary) : summary), turn } }, writing.filter((queued) => queued !== turn), owed === turn ? undefined : owed)
  })
  return before?.writing?.includes(turn) === true
}

/** The writes a reload of the mod lost: the turns still on the list that no write of this load is running. They are taken off it. */
export async function lostSummaries(cell: CountCell, running: ReadonlySet<string>): Promise<string[]> {
  const lost = (await cell.get()).value?.writing?.filter((turn) => !running.has(turn)) ?? []
  // Nothing lost: nothing is written (a session start finds this almost every time).
  if (lost.length === 0) return []
  await update(cell, (current) => {
    if (current?.writing === undefined) return current ?? { count: 0 }
    const { writing, owed } = current
    return withWriting(current, writing.filter((turn) => running.has(turn)), owed !== undefined && lost.includes(owed) ? undefined : owed)
  })
  return lost
}

/** Why a write of the summary made none: the cheap model could not be asked, answered with an error, a reply without words, or no reply in time, or said something that is no summary; or a reload of the mod lost the call. */
export type SummaryFailure =
  | 'lost'
  | { reason: 'refused'; detail: string }
  | { reason: 'api-error'; status: number | null; error: string }
  | { reason: 'empty-reply' }
  | { reason: 'aborted' }
  | { reason: 'unfit'; text: string }

/** A write that made no summary, as the log's decision: the summary stays as it was. */
export function summaryFailure(failure: SummaryFailure, model: string): Pick<Decided, 'outcome' | 'reason' | 'tone'> {
  const why =
    failure === 'lost'
      ? '热重载中断了正在写摘要的调用'
      : failure.reason === 'refused'
        ? `引擎拒绝了写摘要的模型 ${model}：${failure.detail}`
        : failure.reason === 'api-error'
          ? `写摘要的模型 ${model} 出错（状态码 ${failure.status ?? '无'}，${failure.error}）`
          : failure.reason === 'empty-reply'
            ? `写摘要的模型 ${model} 没有给出文字`
            : failure.reason === 'aborted'
              ? `写摘要的调用超过 ${SUMMARY_TIMEOUT_MS / 1000} 秒，或被中断`
              : `写摘要的模型 ${model} 的回答不是摘要的结构：「${failure.text}」`
  return { outcome: '摘要没写成', reason: `${why}；问题摘要保持原样`, tone: 'warn' }
}

const pct = (p: number) => `${Math.round(p * 100)}%`

/** What a judged answer did to the count, as the log's decision: the count's move in a few words, why, and the record the card draws. */
export function unresolvedDecision(judged: UnresolvedJudgement, moved: { before: number; count: number }): Pick<Decided, 'outcome' | 'reason' | 'tone' | 'conf' | 'unresolved'> {
  const p = judged.probabilities
  const t = judged.thresholds
  const odds = UNRESOLVED_OPTIONS.map((option) => `${OPTION_WORDS[option]} ${pct(p[option])}`).join(' · ')
  const crossed: UnresolvedOption = p.resolved >= t.reset ? 'resolved' : 'new_or_unrelated'
  const rule =
    judged.change === 'add'
      ? `仍未解决 ${pct(p.still_unresolved)} ≥ 加一门槛 ${pct(t.add)}，次数加一`
      : judged.change === 'reset'
        ? `${OPTION_WORDS[crossed]} ${pct(p[crossed])} ≥ 清零门槛 ${pct(t.reset)}，次数清零`
        : `仍未解决没到加一门槛 ${pct(t.add)}，已经解决、新问题或无关也没到清零门槛 ${pct(t.reset)}，次数不变`
  const conf = judged.confidence === null ? '没有' : judged.confidence.toFixed(2)
  const record: UnresolvedRecord = {
    before: moved.before,
    count: moved.count,
    change: judged.change,
    top: judged.top,
    probs: { ...p },
    ...(judged.confidence === null ? {} : { conf: judged.confidence }),
    thresholds: t,
  }
  return {
    outcome: judged.change === 'keep' ? `次数 ${moved.count}（不变）` : `次数 ${moved.before} → ${moved.count}`,
    reason: `${odds}；${rule}；置信度 ${conf}（只记录，不参与）`,
    tone: judged.change === 'keep' ? 'info' : 'ok',
    ...(judged.confidence === null ? {} : { conf: judged.confidence }),
    unresolved: record,
  }
}

/**
 * A strong hint given, as the log's decision (beside the effort's own, never a node of the board): the count it was
 * given at, the setting it had reached, and the level the decision model came to (`effort`; null when the request got no
 * usable answer). `where: 'mid'` for a mid-turn re-decision's.
 */
export function hintDecision(hint: HintRecord, effort: Effort | null): Pick<Decided, 'outcome' | 'reason' | 'tone' | 'hint' | 'effort'> {
  const where = hint.where === 'mid' ? '中途重判' : '发消息时'
  const came = effort === null ? '这次请求没有给出档位' : `决策模型判出 ${effort}`
  return {
    outcome: `已给强提示（次数 ${hint.count}）`,
    reason:
      hint.used === false
        ? `${where}：次数 ${hint.count} ≥ ${hint.maxAfter}（unresolvedMaxAfter），请求里另问了一道带强提示的 effort 题；这条消息没判为仍未解决，用的是不带提示的那一题，${came}`
        : `${where}：次数 ${hint.count} ≥ ${hint.maxAfter}（unresolvedMaxAfter），effort 题带强提示：这项工作属于多次尝试都没解决的故障，按故障整体的难度评，max 门槛用强提示的；${came}`,
    tone: 'info',
    hint,
    ...(effort === null ? {} : { effort }),
  }
}

