// The geometry of the zoomed re-check (#59, ADR 0008): where a Box answer lies in an image, the piece of the image to cut out
// around it, and the sips arguments that cut it out and enlarge it. The numbers are the ones of the experiment that found the
// re-check worth doing (a margin of 15% around the box, at least 160 pixels, at most 3.5 to 1, enlarged to about 1000 pixels on the
// long side). The eval's visual-check suite (#65) crops with the same functions, so this is pure (see system-one.ts).

import type { BoxAnswer } from './system-one.ts'

/** A box in an image, each edge as a share of the image's height or width from the top left (a Box answer's). */
export type Box = BoxAnswer['box']

/** The size of an image in pixels. */
export type Size = { width: number; height: number }

/** A piece of an image in pixels: the top left corner and the size. */
export type Rect = { x: number; y: number; width: number; height: number }

/** The margin around a box, as a share of the box's own size on each side. */
const MARGIN = 0.15
/** A crop is at least this many pixels on each side: a smaller piece is not enough to see the context of a part. */
const MIN_CROP = 160
/** A crop is at most this many times longer than wide (or wider than long). */
const MAX_ASPECT = 3.5
/** A crop is enlarged until its longer side is this long (Jev takes 256 to 1568 on each side). */
export const ENLARGE_TO = 1000

/** The share of the screen above which a box is too large to be "another place" (ADR 0008: at most a quarter of the picture). */
export const ELSEWHERE_MAX_AREA = 0.25
/** The confidence from which the box of "where do they differ" is taken to be a place that differs (below it the model is unsure, not sure of a match). */
export const ELSEWHERE_MIN_CONFIDENCE = 0.2

/** How far the aspect ratios of two images may be apart (as a share) for them to be taken for the same view of the same thing. */
const SAME_SHAPE = 0.02

/** The least a box must be wide and high (as a share of the image) to be one: below it the model has boxed nothing. */
const LEAST_EXTENT = 0.002

/**
 * A Box answer's edges put in order and inside the image; null for a box that is not one (an edge that is not a number, or no
 * extent at all).
 */
export function normalizeBox(box: Box): Box | null {
  const edges = [box.top, box.bottom, box.left, box.right]
  if (!edges.every((edge) => Number.isFinite(edge))) return null
  const clamp = (edge: number): number => Math.min(1, Math.max(0, edge))
  const [top, bottom] = [clamp(Math.min(box.top, box.bottom)), clamp(Math.max(box.top, box.bottom))]
  const [left, right] = [clamp(Math.min(box.left, box.right)), clamp(Math.max(box.left, box.right))]
  return bottom - top < LEAST_EXTENT || right - left < LEAST_EXTENT ? null : { top, bottom, left, right }
}

/** The smallest box that holds both. */
export function unionBox(a: Box, b: Box): Box {
  return { top: Math.min(a.top, b.top), bottom: Math.max(a.bottom, b.bottom), left: Math.min(a.left, b.left), right: Math.max(a.right, b.right) }
}

/** The share of the image a box covers. */
export const boxArea = (box: Box): number => (box.right - box.left) * (box.bottom - box.top)

/** The share of `inner` that lies within `outer` (0 to 1). */
export function coverage(inner: Box, outer: Box): number {
  const width = Math.max(0, Math.min(inner.right, outer.right) - Math.max(inner.left, outer.left))
  const height = Math.max(0, Math.min(inner.bottom, outer.bottom) - Math.max(inner.top, outer.top))
  return boxArea(inner) === 0 ? 0 : (width * height) / boxArea(inner)
}

/**
 * The piece of an image of `size` to cut out for `box`: the box with a margin of 15% on each side, at least 160 pixels each way,
 * not more than 3.5 to 1 (the short side is made longer), moved to lie within the image (and made smaller where the image itself
 * is smaller, or so narrow that its shape would not allow the ratio).
 */
export function cropRect(box: Box, size: Size): Rect {
  const x0 = box.left * size.width
  const x1 = box.right * size.width
  const y0 = box.top * size.height
  const y1 = box.bottom * size.height
  let width = Math.max(MIN_CROP, (x1 - x0) * (1 + 2 * MARGIN))
  let height = Math.max(MIN_CROP, (y1 - y0) * (1 + 2 * MARGIN))
  if (width / height > MAX_ASPECT) height = width / MAX_ASPECT
  else if (height / width > MAX_ASPECT) width = height / MAX_ASPECT
  width = Math.min(size.width, width)
  height = Math.min(size.height, height)
  // The image itself may be too small or too narrow for the ratio: the piece is then made smaller, never more than 3.5 to 1.
  if (width / height > MAX_ASPECT) width = height * MAX_ASPECT
  else if (height / width > MAX_ASPECT) height = width * MAX_ASPECT
  width = Math.max(1, Math.round(width))
  height = Math.max(1, Math.round(height))
  // Rounding must not tip the ratio over 3.5 to 1.
  if (width > height * MAX_ASPECT) {
    if (Math.ceil(width / MAX_ASPECT) <= size.height) height = Math.ceil(width / MAX_ASPECT)
    else width = Math.floor(height * MAX_ASPECT)
  } else if (height > width * MAX_ASPECT) {
    if (Math.ceil(height / MAX_ASPECT) <= size.width) width = Math.ceil(height / MAX_ASPECT)
    else height = Math.floor(width * MAX_ASPECT)
  }
  const x = Math.round((x0 + x1) / 2 - width / 2)
  const y = Math.round((y0 + y1) / 2 - height / 2)
  return { x: Math.min(Math.max(0, x), size.width - width), y: Math.min(Math.max(0, y), size.height - height), width, height }
}

/** The same piece of another image, by proportion: the rect of an image of size `from`, in an image of size `to`. */
export function scaleRect(rect: Rect, from: Size, to: Size): Rect {
  const width = Math.min(to.width, Math.max(1, Math.round((rect.width * to.width) / from.width)))
  const height = Math.min(to.height, Math.max(1, Math.round((rect.height * to.height) / from.height)))
  const x = Math.round((rect.x * to.width) / from.width)
  const y = Math.round((rect.y * to.height) / from.height)
  return { x: Math.min(Math.max(0, x), to.width - width), y: Math.min(Math.max(0, y), to.height - height), width, height }
}

/** The size a piece has once it is enlarged until its longer side is `longSide` (as `sips -Z` does, to the nearest pixel). */
export function enlargedSize(rect: Size, longSide: number = ENLARGE_TO): Size {
  const longest = Math.max(rect.width, rect.height)
  return { width: Math.max(1, Math.round((rect.width * longSide) / longest)), height: Math.max(1, Math.round((rect.height * longSide) / longest)) }
}

/**
 * The sips arguments that cut `rect` out of `source` into `out`. A crop and an enlargement cannot go in one call (measured with
 * sips on macOS 26: given together, `-Z` is applied before `-c`), so they are two: `sipsEnlargeArgs` after this one.
 */
export function sipsCropArgs(source: string, rect: Rect, out: string): string[] {
  return ['sips', '-c', String(rect.height), String(rect.width), '--cropOffset', String(rect.y), String(rect.x), source, '--out', out]
}

/** The sips arguments that make the longer side of `file` `longSide` pixels, the file itself being replaced. */
export function sipsEnlargeArgs(file: string, longSide: number = ENLARGE_TO): string[] {
  return ['sips', '-Z', String(longSide), file, '--out', file]
}

/**
 * Whether two images show the same view: `said` when the agent said (`same_view`), else whether their aspect ratios are the
 * same (to 2%): a screenshot and its design are alike in shape, a render and a photo of the real thing are not.
 */
export function sameView(said: boolean | null, a: Size, b: Size): boolean {
  if (said !== null) return said
  const [ratioA, ratioB] = [a.width / a.height, b.width / b.height]
  return Math.abs(ratioA - ratioB) / ratioA <= SAME_SHAPE
}

files.hooks/core/zoom-review.ts:
// The zoomed re-check of two images (#59, ADR 0008), for every feature that compares a pair of images: visual_check against a reference
// or another screenshot, and the quality series (#61), which compares each two neighbours. Given the parts the checks name and the
// boxes the decision model located them in, it cuts the crops out of the two images, asks one Noul of each pair of crops, and reads
// the verdict of each check off the crops. Like image-files.ts it keeps no state and asks for nothing but closures (a module cannot
// pass `$` across an import): the files, and `ask`, which sends one request to the decision model that takes images.

import { type Asked, type Failure, failureText } from '../decision/backend.ts'
import { imageRef, type Picture } from '../decision/images.ts'
import { mergeParts, type DecisionRequest } from '../decision/system-one.ts'
import { allUnsure, STILL_BARS, type Bars, type Check, type CheckResult } from '../decision/visual-check.ts'
import { cropLabel, type ShownPlace } from '../decision/visual-check-tool.ts'
import { batchPairs, type Boxed, type Elsewhere, fallBack, judgeZoom, type LocatePlan, locatePlan, MAX_CROPPED_CHECKS, readLocated, readZoom, withinFailed, zoomRequest, type ZoomPair } from '../decision/visual-check-zoom.ts'
import { type Box, cropRect, type Rect, sameView, scaleRect, unionBox } from '../decision/zoom.ts'
import { type Crop, cropImage } from './image-crops.ts'
import type { ImageFilesIo, LoadedImage } from './image-files.ts'

/** What the zoomed re-check needs of the world: files and programs, and the decision model that takes images. */
export type ZoomDeps = {
  files: ImageFilesIo
  /** One request to the decision model that takes images (Jev: the Box questions and the pinned model are its own). */
  ask: (request: DecisionRequest) => Promise<Asked>
  /** The name the decision model goes by in a reason. */
  backend: string
}

/** What is compared: the screenshot, and the images it is compared with. */
export type ZoomSubjects = {
  candidate: LoadedImage
  /** The images the screenshot is compared with, and the names they go by in the request (`reference`, `reference-1`, `other`). */
  others: readonly LoadedImage[]
  names: readonly string[]
  /** For each of `others`, whether it shows the same view as the screenshot. */
  sameViews: readonly boolean[]
}

/** A crop of a part that failed: the screenshot's and the other image's, to show the agent. */
export type FailedCrops = { index: number; candidate: Crop; other: Crop }

/** The place the whole screen asked about, if it is to be reported, with the crops of it (a crop that could not be made is null). */
export type Place = { place: Elsewhere; candidate: Crop | null; other: Crop | null }

/** What the zoomed re-check comes to. */
export type ZoomOutcome = {
  /** A result for each check, in order: from the crops, or, where that failed, from the whole images (only a fail), with the reason. */
  results: CheckResult[]
  /** The crops of the checks that failed on their crops, to attach. */
  failed: FailedCrops[]
  /** Another place that may differ; null when there is none to report. */
  elsewhere: Place | null
  /** The first request to the decision model that failed, if one did (the board keeps it as a note: #58); null when none did. */
  failure: Failure | null
}

/** A crop is not worth showing when it is nearly all of the image: the agent has that already. */
const WORTH_SHOWING = 0.9

/** The crops of one pair: the screenshot's and the other image's, and where each was cut. */
type PairCrops = { candidate: Crop; other: Crop }

/**
 * The rects to cut for a part: the same piece of both images by proportion, from the union of the two boxes, when they show the
 * same view; else each image around its own box.
 */
function rectsFor(subjects: ZoomSubjects, k: number, candidateBox: Box, otherBox: Box): { candidate: Rect; other: Rect } {
  const candidate = subjects.candidate
  const other = subjects.others[k] as LoadedImage
  if (subjects.sameViews[k]) {
    const rect = cropRect(unionBox(candidateBox, otherBox), candidate)
    return { candidate: rect, other: scaleRect(rect, candidate, other) }
  }
  return { candidate: cropRect(candidateBox, candidate), other: cropRect(otherBox, other) }
}

/**
 * The zoomed re-check. `whole`: the answers of the whole images for each check, which stand for a check whose re-check failed
 * (only a fail is taken from them, by the bars of a screenshot). `plan` and `located` come from the request that asked the Box
 * questions. `bars`: those the crops are judged by.
 */
export async function zoomReview(deps: ZoomDeps, subjects: ZoomSubjects, checks: readonly Check[], whole: readonly CheckResult[], plan: LocatePlan, located: ReturnType<typeof readLocated>, bars: Bars = STILL_BARS): Promise<ZoomOutcome> {
  const reasons = new Map<number, string>(plan.skipped)
  const pairs: ZoomPair[] = []
  const crops = new Map<ZoomPair, PairCrops>()
  const cache = new Map<string, Promise<Awaited<ReturnType<typeof cropImage>>>>()
  /** A crop of `image` at `rect`, made once however many pairs use it. */
  const cut = (image: LoadedImage, rect: Rect) => {
    const key = `${image.file}|${rect.x},${rect.y},${rect.width},${rect.height}`
    let made = cache.get(key)
    if (made === undefined) {
      made = cropImage(deps.files, image, rect)
      cache.set(key, made)
    }
    return made
  }
  // The crops of every pair, made at once.
  await Promise.all(
    located.boxed.map(async (boxed) => {
      const { index, check } = boxed.located
      if (boxed.candidate === null) {
        reasons.set(index, 'the decision model did not locate the part in the screenshot')
        return
      }
      const candidateBox = boxed.candidate
      const names = new Map<string, string>()
      await Promise.all(
        boxed.references.map(async (otherBox, k) => {
          if (otherBox === null) {
            reasons.set(index, `the decision model did not locate the part in ${subjects.names[k]}`)
            return
          }
          const rects = rectsFor(subjects, k, candidateBox, otherBox)
          const [candidate, other] = await Promise.all([cut(subjects.candidate, rects.candidate), cut(subjects.others[k] as LoadedImage, rects.other)])
          if (!candidate.ok || !other.ok) {
            reasons.set(index, (!candidate.ok ? candidate : (other as { reason: string })).reason)
            return
          }
          // One name for each distinct crop of the screenshot (several images compared with can ask for the same piece of it).
          const key = `${candidate.crop.rect.x},${candidate.crop.rect.y},${candidate.crop.rect.width},${candidate.crop.rect.height}`
          if (!names.has(key)) names.set(key, names.size === 0 ? `zoom-${index}-candidate` : `zoom-${index}-candidate-${names.size + 1}`)
          const name = subjects.names[k] as string
          const pair: ZoomPair = {
            index,
            reference: k,
            check,
            candidate: { name: names.get(key) as string, picture: candidate.crop },
            other: { name: `zoom-${index}-${name}`, picture: other.crop },
            otherField: `${name}_crop`,
          }
          pairs.push(pair)
          crops.set(pair, { candidate: candidate.crop, other: other.crop })
        }),
      )
    }),
  )
  // The pairs in the order of the checks and the images, whatever order their crops were made in.
  pairs.sort((a, b) => a.index - b.index || a.reference - b.reference)
  // The second request(s): one Noul for each pair of crops, split where the crops would cost more than a request holds.
  const probabilities = new Map<ZoomPair, number | null>()
  let failure: Failure | null = null
  await Promise.all(
    batchPairs(pairs).map(async (batch) => {
      const { request, part } = zoomRequest(batch)
      const asked = await deps.ask(request)
      if (!asked.ok) {
        failure ??= asked.failure
        for (const pair of batch) {
          probabilities.set(pair, null)
          if (!reasons.has(pair.index)) reasons.set(pair.index, `the zoomed re-check failed (${failureText(deps.backend, asked.failure)})`)
        }
        return
      }
      for (const [pair, probability] of readZoom(part, asked.answers, batch)) {
        probabilities.set(pair, probability)
        if (probability === null && !reasons.has(pair.index)) reasons.set(pair.index, 'the decision model gave no answer to the zoomed re-check')
      }
    }),
  )
  // The verdicts: the crops decide; for a check they cannot be made for, the whole image gives only a fail.
  const failed: FailedCrops[] = []
  const failedBoxes: Box[] = []
  const results = checks.map((check, index): CheckResult => {
    const own = pairs.filter((pair) => pair.index === index)
    const judged = judgeZoom(check, own.map((pair) => probabilities.get(pair) ?? null), bars)
    const wholeAnswer = whole[index] as CheckResult
    if (judged === null) return fallBack(wholeAnswer, reasons.get(index) ?? 'the zoomed re-check could not be made')
    if (judged.verdict === 'fail') {
      // The pair that differs most is the one to show.
      const worst = own.reduce((lowest, pair) => ((probabilities.get(pair) ?? 1) < (probabilities.get(lowest) ?? 1) ? pair : lowest), own[0] as ZoomPair)
      const pair = crops.get(worst) as PairCrops
      const share = (pair.candidate.rect.width * pair.candidate.rect.height) / (subjects.candidate.width * subjects.candidate.height)
      if (share <= WORTH_SHOWING) failed.push({ index, candidate: pair.candidate, other: pair.other })
      const boxed = located.boxed.find((one) => one.located.index === index)
      if (boxed?.candidate != null) failedBoxes.push(boxed.candidate)
    }
    return judged
  })
  return { results, failed, elsewhere: await placeOf(deps, subjects, located.elsewhere, failedBoxes), failure }
}

/** Another place that may differ, with its crops, unless a check that failed has reported it already. */
async function placeOf(deps: ZoomDeps, subjects: ZoomSubjects, elsewhere: Elsewhere | null, failedBoxes: readonly Box[]): Promise<Place | null> {
  if (elsewhere === null || withinFailed(elsewhere, failedBoxes)) return null
  // The question is asked only of one other image that shows the same view: the same piece of both is cut.
  const other = subjects.others[0]
  if (other === undefined) return { place: elsewhere, candidate: null, other: null }
  const rect = cropRect(elsewhere.box, subjects.candidate)
  const [candidate, theOther] = await Promise.all([cropImage(deps.files, subjects.candidate, rect), cropImage(deps.files, other, scaleRect(rect, subjects.candidate, other))])
  return { place: elsewhere, candidate: candidate.ok ? candidate.crop : null, other: theOther.ok ? theOther.crop : null }
}

/** A crop that goes along with the answer, and what it shows. */
export type Attachment = { label: string; picture: Picture }

/** The crops the answer shows (of the checks that failed, at most three; of another place) and what it says of that place. */
export function attachmentsOf(zoomed: ZoomOutcome): { crops: Attachment[]; elsewhere: ShownPlace | null } {
  const crops: Attachment[] = zoomed.failed.slice(0, MAX_CROPPED_CHECKS).flatMap((one) => [
    { label: cropLabel({ check: one.index }, 'your screenshot'), picture: one.candidate },
    { label: cropLabel({ check: one.index }, 'the image it is compared with'), picture: one.other },
  ])
  const place = zoomed.elsewhere
  if (place === null) return { crops, elsewhere: null }
  const { candidate, other } = place
  const cropped = candidate !== null && other !== null
  if (cropped) crops.push({ label: cropLabel({ place: true }, 'your screenshot'), picture: candidate }, { label: cropLabel({ place: true }, 'the image it is compared with'), picture: other })
  return { crops, elsewhere: { box: place.place.box, confidence: place.place.confidence, cropped } }
}

// ---- A pair of images, on their own ----------------------------------------------------------------------------------

/** What `comparePair` compares: two images, and whether they show the same view (`null`: by the shapes of the images). */
export type ImagePair = { candidate: LoadedImage; other: LoadedImage; sameView: boolean | null }

/**
 * A pair of images and the parts to compare in them, from the Box questions to the verdicts: asks the decision model where each
 * part is in both images (and where the images differ), cuts the crops, and judges each part on them. For any pair of images, with
 * no first request of the whole images before it (the quality series, #61, compares each two neighbours so). A check whose re-check
 * cannot be made ends unsure with the reason; nothing throws. `bars`: those the crops are judged by.
 */
export async function comparePair(deps: ZoomDeps, pair: ImagePair, checks: readonly Check[], bars: Bars = STILL_BARS): Promise<ZoomOutcome> {
  const subjects: ZoomSubjects = { candidate: pair.candidate, others: [pair.other], names: ['other'], sameViews: [sameView(pair.sameView, pair.candidate, pair.other)] }
  const unasked = (reason: string, failure: Failure | null = null): ZoomOutcome => ({ results: allUnsure(checks, reason), failed: [], elsewhere: null, failure })
  const plan = locatePlan(subjects.names, subjects.sameViews, checks)
  if (plan.parts.length === 0) return unasked('no part of the image is named, so there is nothing to cut out')
  const state = { candidate: imageRef('candidate'), other: imageRef('other') }
  const asked = await deps.ask({
    ...mergeParts(state, plan.parts),
    images: [pair.candidate, pair.other].map((image, i) => ({ name: i === 0 ? 'candidate' : 'other', format: image.format, base64: image.base64, width: image.width, height: image.height })),
  })
  if (!asked.ok) return unasked(`the parts could not be located (${failureText(deps.backend, asked.failure)})`, asked.failure)
  const whole = allUnsure(checks, 'the whole images were not compared')
  return zoomReview(deps, subjects, checks, whole, plan, readLocated(plan, asked.answers), bars)
}

