// The queue every decision request waits in for its place under an account's rate limit (pplx-rate.ts, jev-rate.ts). What
// makes a place free differs (pplx: the sends of the last second, kept in a `$.state` cell; Jev: a count of requests and a
// bucket of tokens), so each limit tells the queue only whether a place is free now. Who is next, how long a request may wait
// and what the callers get back are the same:
//
// - the effort question of a message goes first (the person waits for it), the rest in the order they came; only the first
//   in the queue takes a place, even when a later request would fit, so a large request is not passed over for ever;
// - a request waits for its place at most until its own deadline, and is not held for a place that comes too late to be
//   answered in what is left (LEAST_SEND_MS);
// - the order is the request's, not its try's: a request that asks again keeps its place in line (`Ticket`).
//
// Pure (see system-one.ts): the clock and the timer come in as closures.

import { within, type Asked, type BackendIo } from './backend.ts'
import { EFFORT_PART } from './effort.ts'
import type { DecisionRequest } from './system-one.ts'

/** A request with less time left than this cannot be answered, so it is not sent (core/agent-lane.ts `MIN_ASK_MS` likewise). */
export const LEAST_SEND_MS = 200

/** The effort question of a message goes before everything else; the rest keep their order. */
export function priorityOf(request: DecisionRequest): number {
  return Object.keys(request.questions).some((id) => id.startsWith(`${EFFORT_PART}.`)) ? 0 : 1
}

/** Where a request stands in line: the best priority first, the earliest `order` of those. One request keeps its ticket through a retry. */
export type Ticket = { priority: number; order: number }

type Waiter = Ticket & { wake: () => void }

/** The clock and the timer of the host (`BackendIo.pace.now`, `BackendIo.sleep`). */
export type QueueClock = { now: () => Promise<number>; sleep: BackendIo['sleep'] }

export type RateQueue = {
  /** A ticket for a request that is just being asked: its priority, and the next order. */
  ticket: (request: DecisionRequest) => Ticket
  /** Lets whoever sleeps for a place look again at once: a limit has eased (tokens came back) before the time the sleeper was told. */
  nudge: () => void
  /**
   * Waits for a place and takes it: how long it waited in ms; null when `deadline` comes first or can no longer be met.
   * `take(now)` is asked only of the first in the queue: it takes the place and answers 0 when the place is free at `now`,
   * else the ms until it will be. A better request that arrives while the first sleeps goes ahead of it, since the first
   * looks at the queue again when it wakes.
   */
  place: (ticket: Ticket, deadline: number, clock: QueueClock, take: (now: number) => number | Promise<number>) => Promise<number | null>
}

export function rateQueue(): RateQueue {
  const queue: Waiter[] = []
  /** Who sleeps until a place comes free. */
  const napping = new Set<() => void>()
  let arrivals = 0

  /** The waiter whose turn it is: the best priority, the earliest of those. */
  const first = (): Waiter | undefined => queue.reduce<Waiter | undefined>((best, one) => (best === undefined || one.priority < best.priority || (one.priority === best.priority && one.order < best.order) ? one : best), undefined)

  return {
    ticket: (request) => ({ priority: priorityOf(request), order: arrivals++ }),
    nudge() {
      for (const wake of [...napping]) wake()
    },
    async place(ticket, deadline, clock, take) {
      // Before the queue is joined: a clock that fails must not leave a request at its head.
      const since = await clock.now()
      const me: Waiter = { ...ticket, wake: () => {} }
      queue.push(me)
      try {
        for (;;) {
          if (first() !== me) {
            // Not our turn: until the one in front leaves, or the time is up. (No await between the check and `wake`.)
            const woken = new Promise<true>((done) => {
              me.wake = () => done(true)
            })
            const left = deadline - LEAST_SEND_MS - (await clock.now())
            if (left <= 0 || (await within(clock.sleep, woken, left, false)) === false) return null
            continue
          }
          const now = await clock.now()
          if (deadline - now < LEAST_SEND_MS) return null
          const wait = await take(now)
          if (wait === 0) return now - since
          // The place comes free after `wait`, or sooner when `nudge` says so; a request that cannot be sent before its deadline is not held up until it.
          if (deadline - (now + wait) < LEAST_SEND_MS) return null
          let wake = () => {}
          const nudged = new Promise<true>((done) => {
            wake = () => done(true)
          })
          napping.add(wake)
          try {
            await within(clock.sleep, nudged, wait, false)
          } finally {
            napping.delete(wake)
          }
        }
      } finally {
        queue.splice(queue.indexOf(me), 1)
        for (const one of queue) one.wake()
      }
    },
  }
}

/** The answer as the callers get it: a failure without `retryAfterMs`, which only passes between the backend and the limit (the board keeps what the person reads of it, in `detail`); with the `notes` the debug log is to carry. */
export function handedOver(asked: Asked, notes: readonly string[]): Asked {
  const withNotes = notes.length === 0 ? asked : { ...asked, notes: [...(asked.notes ?? []), ...notes] }
  if (withNotes.ok || withNotes.failure.retryAfterMs === undefined) return withNotes
  const { retryAfterMs: _wait, ...failure } = withNotes.failure
  return { ok: false, failure, ...(withNotes.notes === undefined ? {} : { notes: withNotes.notes }) }
}

files.hooks/decision/image-header.ts:
// What the first bytes of a PNG or a JPEG say: its size, and the orientation a JPEG's EXIF gives it. Read from the base64 text
// of the file (`$.fs.read(path, { as: 'bytes' })` gives no more), without decoding more of it than the header needs. Where there
// is sips (the CLI) it tells the size; this is for where there is not, and for the orientation, which sips cannot tell.
// Pure (see system-one.ts).

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

/** What a header says of an image. `orientation`: the EXIF tag, 1 (upright) to 8; 1 for a PNG or a JPEG without one. */
export type ImageHeader = { format: 'png' | 'jpeg'; width: number; height: number; orientation: number }

/** A reader of the bytes of a base64 text: the byte at an index, or 0 beyond the end. */
function bytesOf(base64: string): (index: number) => number {
  const value = (at: number): number => {
    const char = base64[at]
    return char === undefined || char === '=' ? 0 : Math.max(0, ALPHABET.indexOf(char))
  }
  return (index) => {
    const group = Math.floor(index / 3) * 4
    const bits = (value(group) << 18) | (value(group + 1) << 12) | (value(group + 2) << 6) | value(group + 3)
    return (bits >> ((2 - (index % 3)) * 8)) & 255
  }
}

/** The size of the file in bytes that a base64 text holds. */
function byteLength(base64: string): number {
  return Math.max(0, Math.floor((base64.length * 3) / 4) - (base64.endsWith('==') ? 2 : base64.endsWith('=') ? 1 : 0))
}

export function readImageHeader(base64: string): ImageHeader | null {
  const at = bytesOf(base64)
  const length = byteLength(base64)
  const u16 = (index: number, little = false) => (little ? at(index) | (at(index + 1) << 8) : (at(index) << 8) | at(index + 1))
  const u32 = (index: number, little = false) => (little ? (u16(index, true) | (u16(index + 2, true) << 16)) >>> 0 : ((u16(index) << 16) | u16(index + 2)) >>> 0)
  const text = (index: number, count: number) => String.fromCharCode(...Array.from({ length: count }, (_, i) => at(index + i)))

  if (length >= 24 && at(0) === 0x89 && text(1, 3) === 'PNG') return { format: 'png', width: u32(16), height: u32(20), orientation: 1 }

  if (length >= 4 && at(0) === 0xff && at(1) === 0xd8) {
    let orientation = 1
    let index = 2
    while (index + 4 <= length) {
      if (at(index) !== 0xff) return null
      const marker = at(index + 1)
      if (marker === 0xff) {
        index += 1
        continue
      }
      // Markers without a length, and the start of the image data, which the size comes before.
      if (marker === 0x01 || (marker >= 0xd0 && marker <= 0xd8)) {
        index += 2
        continue
      }
      if (marker === 0xd9 || marker === 0xda) return null
      const segment = u16(index + 2)
      // The start of a frame: precision, then the height and the width.
      if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) return { format: 'jpeg', width: u16(index + 7), height: u16(index + 5), orientation }
      if (marker === 0xe1 && text(index + 4, 4) === 'Exif') orientation = exifOrientation(index + 10, index + 2 + segment)
      index += 2 + segment
    }
    return null
  }
  return null

  /** The orientation in the TIFF block that starts at `from` and ends before `to`, 1 when it has none. */
  function exifOrientation(from: number, to: number): number {
    const little = text(from, 2) === 'II'
    if (!little && text(from, 2) !== 'MM') return 1
    const first = from + u32(from + 4, little)
    const entries = u16(first, little)
    for (let i = 0; i < entries && first + 2 + i * 12 + 12 <= to; i++) {
      const entry = first + 2 + i * 12
      if (u16(entry, little) === 0x0112) {
        const value = u16(entry + 8, little)
        return value >= 1 && value <= 8 ? value : 1
      }
    }
    return 1
  }
}

files.hooks/core/image-crops.ts:
// Cutting a piece out of an image and enlarging it (#59, ADR 0008), for the zoomed re-check: sips does it in two calls on a new
// file of the session's temporary directory. Like image-files.ts it keeps no state and asks for nothing but an `ImageFilesIo`.

import { errorText } from '../decision/backend.ts'
import { ENLARGE_TO, enlargedSize, type Rect, sipsCropArgs, sipsEnlargeArgs } from '../decision/zoom.ts'
import type { Picture } from '../decision/images.ts'
import { asArgument, failedRun, type ImageFilesIo } from './image-files.ts'

/** What a crop is cut from: the image's file (already in the size and format that are sent) and its format, which the crop keeps. */
export type CropSource = { file: string; format: 'png' | 'jpeg' }

/** A crop, enlarged and read as bytes; `rect` is the piece of the source it is. */
export type Crop = Picture & { rect: Rect }

/** A crop made, or why it could not be (written for the model, in English). */
export type Cropped = { ok: true; crop: Crop } | { ok: false; reason: string }

/**
 * The piece `rect` of `source`, cut out and enlarged until its long side is `longSide` pixels, and read. The crop and the
 * enlargement are two calls of sips (given together, sips applies the enlargement first). Never throws: a program that fails, is
 * missing or is not allowed (outside the CLI) is a reason.
 */
export async function cropImage(io: ImageFilesIo, source: CropSource, rect: Rect, longSide: number = ENLARGE_TO): Promise<Cropped> {
  try {
    const file = await io.newFile(source.format === 'jpeg' ? 'jpg' : 'png')
    const cut = await io.run(sipsCropArgs(asArgument(source.file), rect, file))
    if (cut.exitCode !== 0) return { ok: false, reason: `sips could not cut a crop out of ${source.file} (${failedRun(cut)})` }
    const enlarged = await io.run(sipsEnlargeArgs(file, longSide))
    if (enlarged.exitCode !== 0) return { ok: false, reason: `sips could not enlarge a crop (${failedRun(enlarged)})` }
    const base64 = await io.readBytes(file)
    const { width, height } = enlargedSize(rect, longSide)
    return { ok: true, crop: { rect, format: source.format, base64, width, height } }
  } catch (error) {
    return { ok: false, reason: `a crop could not be made (${errorText(error)})` }
  }
}

files.hooks/decision/visual-check-sequence.ts:
// A series of quality levels in visual_check (#61, ADR 0008): the agent hands over screenshots of one view at rising levels (the
// sea at low, medium, high, ultra) and asks whether the higher levels still look different in the places it names, so as to find
// the level from which they do not. Each two neighbouring levels are compared as any pair of images is (core/zoom-review.ts
// `comparePair`: the named part located in both, cropped, enlarged, judged on the crops); this module is what comes of the pairs.
// The eval's visual-check suite (#65) reads a series the very same way, so it is pure (see system-one.ts).

import { packByCost } from './images.ts'
import { SERIES_PASS_AT, type CheckResult } from './visual-check.ts'

/** Most levels one call takes: each neighbouring pair is its own requests, and they go out in waves (`pairWaves`). */
export const MAX_LEVELS = 12

// ---- What the agent reads of it -------------------------------------------------------------------------------------

/** With Jev, in the tool's description (visual-check-tool.ts): what a series is for, how it is judged, what to put in the final report. */
export const SERIES_DESCRIPTION =
  `To find the quality level from which higher ones look no different, give the screenshots of one view at rising levels in images, lowest first (2 to ${MAX_LEVELS} levels), with sequence: true, and name the parts the level may change: each two neighbouring levels are compared in every part you name, on enlarged crops, and the answer lists each pair and says from which level up nothing differs. It counts as no difference only if every part you named passes (${SERIES_PASS_AT} or more). Use it instead of handing the user the levels to compare. A still does not show flicker or rippling jitter: for those cut the same moment out of a recording of each level (for example with ffmpeg) and give those frames as the series. List the levels you tried, the parts you compared, the result and the probabilities in your final report.`

/** With pplx, in its description: a series needs the zoomed re-check, which needs the boxes only Jev answers. */
export const SERIES_UNAVAILABLE =
  'With pplx, sequence (a series of quality levels) is not available: it needs the zoomed re-check, which needs a TypeSafe key. Look at the levels yourself.'

// ---- What a pair comes to -------------------------------------------------------------------------------------------

/**
 * What two neighbouring levels come to. "No difference" is the weak direction of the decision model's answers, which only a pass
 * at SERIES_PASS_AT (0.9: the old bar, kept for this; a screenshot passes at 0.8) on the crop of a part can show (ADR 0008), and it takes every part the checks name: `same` when all pass; `differs`
 * when any fails (a part known to differ outweighs a doubt about another); `unsure` otherwise.
 */
export type PairConclusion = 'same' | 'differs' | 'unsure'

export function pairConclusion(results: readonly Pick<CheckResult, 'verdict'>[]): PairConclusion {
  if (results.some((result) => result.verdict === 'fail')) return 'differs'
  return results.length > 0 && results.every((result) => result.verdict === 'pass') ? 'same' : 'unsure'
}

// ---- What the series comes to ---------------------------------------------------------------------------------------

/**
 * What the pairs come to, by levels counted from 1. `from`: the higher levels look alike from this one up (it is the lowest
 * level beyond which a higher one is not worth its cost). `differs`: the top pair still differs, so there is no such level;
 * `every`: every pair differs. `unknown`: the top pair could not be told.
 */
export type SeriesVerdict = { kind: 'from'; level: number } | { kind: 'differs'; every: boolean } | { kind: 'unknown' }

/**
 * The series' verdict from the conclusions of its pairs, in order (the pair `i` is level `i + 1` and level `i + 2`). The levels
 * from which none differs from the next are the unbroken run of `same` pairs at the top; a pair lower down that looked the same
 * does not count when a higher one differs again.
 */
export function seriesVerdict(pairs: readonly PairConclusion[]): SeriesVerdict {
  const top = pairs.at(-1)
  if (top === 'differs') return { kind: 'differs', every: pairs.every((pair) => pair === 'differs') }
  if (top !== 'same') return { kind: 'unknown' }
  let first = pairs.length - 1
  while (first > 0 && pairs[first - 1] === 'same') first--
  return { kind: 'from', level: first + 1 }
}

// ---- Sending the pairs ----------------------------------------------------------------------------------------------

/** About how many input tokens the images of the pairs in one wave may cost in all: three requests at the 24,000 tokens a Jev request takes of images. */
const WAVE_TOKENS = 72_000
/** Most pairs in one wave, however small their images: each is a few requests of its own. */
const WAVE_PAIRS = 6

/**
 * The pairs split into waves that go out one after the other, the pairs of a wave at once: a series of many levels at full size
 * would otherwise put a dozen requests of two large images on the decision model together and wait for the slowest. `tokens`:
 * what the images of each pair cost, in order. A pair is never split; the result holds the pairs' indexes.
 */
export function pairWaves(tokens: readonly number[]): number[][] {
  return packByCost(tokens, WAVE_TOKENS, WAVE_PAIRS)
}

