      "default": false
    },
    "agentOverride": {
      "type": "number",
      "title": "推翻主 agent 选的模型所需的置信度",
      "description": "主 agent 为它派出的 agent 指定了模型时，决策模型的选择置信度至少达到它（0 到 1）才会推翻。你在消息里自己点名的模型从不被推翻。默认 0.6。"
    },
    "skillsMax": {
      "type": "number",
      "title": "最多推荐几个 skill",
